app.get("/donors/:id/materials", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" }); // BUILD-75 B: the parent must be YOURS before children are answered — even an empty list confirms nothing about another tenant
  const rows = await query("SELECT id,org_id,donor_id,file_name,file_type,file_url,notes,uploaded_by,uploaded_at FROM donor_materials WHERE donor_id=? AND org_id=? ORDER BY uploaded_at DESC", [req.params.id, req.user.orgId]);
  res.json(rows);
}));

// Server-side backstop for donor material uploads. The client only checks
// file.size<1MB before base64-encoding — trivially bypassed by calling the
// API directly, so it's not a real limit on its own. The MIME allowlist is
// the actual fix for the stored-XSS risk: file_type is attacker/uploader-
// controlled and the frontend's viewMaterial() trusts it verbatim to build a
// Blob it opens via window.open(URL.createObjectURL(...)) — if file_type
// were ever "text/html" or "image/svg+xml", that blob would execute as
// script in the browser. That path isn't reachable today only because
// GET /donors/:id/materials happens to exclude file_data from its SELECT
// (an apparently unrelated bug that also makes the "View" button do nothing
// for base64 uploads) — an accident, not a real control. Constraining
// file_type to genuinely inert formats at write time closes the actual gap,
// so it stays closed even if that unrelated bug gets "fixed" later by
// someone adding file_data back to a read response.
const MATERIAL_MAX_BYTES = 1024 * 1024; // 1MB, matches the documented convention
const MATERIAL_ALLOWED_MIME_TYPES = new Set([
  "application/pdf",
  "image/jpeg", "image/png", "image/gif", "image/webp",
  "application/msword",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.ms-excel",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "text/plain",
  "text/csv",
  "application/octet-stream",
]);

app.post("/donors/:id/materials", requireAuth, wrap(async (req, res) => {
  const { file_name, file_type, file_url, file_data, notes } = req.body;
  if (!file_name) return res.status(400).json({ error: "file_name required" });
  if (file_type && !MATERIAL_ALLOWED_MIME_TYPES.has(file_type)) {
    return res.status(400).json({ error: `Unsupported file type: ${file_type}` });
  }
  if (file_data && Buffer.byteLength(file_data, "base64") > MATERIAL_MAX_BYTES) {
    return res.status(400).json({ error: "File too large. Maximum size is 1MB." });
  }
  const donorCheck = await query("SELECT id FROM donors WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!donorCheck.length) return res.status(404).json({ error: "Donor not found" });
  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const id = "mat_" + uuid().slice(0,8);
  await run(
    "INSERT INTO donor_materials (id,org_id,donor_id,file_name,file_type,file_url,file_data,notes,uploaded_by) VALUES (?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, req.params.id, file_name, file_type||"", file_url||null, file_data||null, notes||"", userRow[0]?.name||""]
  );
  const rows = await query("SELECT id,org_id,donor_id,file_name,file_type,file_url,notes,uploaded_by,uploaded_at FROM donor_materials WHERE id=?", [id]);
  // Log interaction
  try {
    const ext = file_type ? file_type.split("/").pop() : "file";
    await run(
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name) VALUES (?,?,?,?,?,?,?,?)",
      ["int_"+uuid().slice(0,8), req.user.orgId, req.params.id, "material",
       `Material added: ${file_name} (${ext})`,
       new Date().toISOString().split("T")[0], req.user.userId, userRow[0]?.name||""]
    );
  } catch(e) { console.error("Material log:", e.message); }
  res.status(201).json(rows[0]);
}));

app.delete("/materials/:id", requireAuth, wrap(async (req, res) => {
  const existing = await query("SELECT * FROM donor_materials WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Not found" });
  await run("DELETE FROM donor_materials WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  res.json({ ok: true });
}));

// ── Households / soft credit (BUILD-14) ────────────────────────────────────
// A household groups 2+ constituents. HARD CREDIT NEVER MOVES: donors.
// total_giving stays each donor's own gift sum, org hard total = SUM(all
// gifts) regardless of grouping. Combined giving and soft credit are DERIVED
// (never stored counters), so they cannot double-count. See db.js migration.
function lastName(name) {
  const parts = String(name || "").trim().split(/\s+/);
  return parts.length ? parts[parts.length - 1] : "";
}

// Full derived view of a household: members (with per-member hard credit +
// primary flag), combined giving, member count. Combined = SUM(members'
// hard credit) — a pure aggregation over the same gift rows.
async function householdView(householdId, orgId) {
  const hh = await query("SELECT * FROM households WHERE id=? AND org_id=?", [householdId, orgId]);
  if (!hh.length) return null;
  const members = await query(
    `SELECT id, name, email, phone, total_giving, gift_count, last_gift_date, last_gift_amount,
            stage, status, assigned_to, assigned_to_name
     FROM donors WHERE household_id=? AND org_id=? AND deleted_at IS NULL
     ORDER BY total_giving DESC, id`, [householdId, orgId]);
  const combinedGiving = members.reduce((s, m) => s + (parseFloat(m.total_giving) || 0), 0);
  const combinedGiftCount = members.reduce((s, m) => s + (parseInt(m.gift_count, 10) || 0), 0);
  return {
    ...hh[0],
    members: members.map(m => ({
      ...m,
      total_giving: parseFloat(m.total_giving) || 0,
      last_gift_amount: parseFloat(m.last_gift_amount) || 0,
      gift_count: parseInt(m.gift_count, 10) || 0,
      is_primary: m.id === hh[0].primary_donor_id,
      // per-member soft credit = combined − own hard credit = other members' gifts
      soft_credit: combinedGiving - (parseFloat(m.total_giving) || 0),
    })),
    member_count: members.length,
    combined_giving: combinedGiving,
    combined_gift_count: combinedGiftCount,
  };
}

app.get("/households", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT h.id, h.name, h.primary_donor_id, h.joint_acknowledgment, h.created_at,
            COUNT(d.id)::int AS member_count, COALESCE(SUM(d.total_giving),0) AS combined_giving
     FROM households h
     LEFT JOIN donors d ON d.household_id = h.id AND d.org_id = h.org_id AND d.deleted_at IS NULL
     WHERE h.org_id=?
     GROUP BY h.id
     ORDER BY combined_giving DESC, h.name`, [req.user.orgId]);
  res.json(rows.map(r => ({ ...r, member_count: parseInt(r.member_count, 10) || 0, combined_giving: parseFloat(r.combined_giving) || 0 })));
}));

app.get("/households/:id", requireAuth, wrap(async (req, res) => {
  const view = await householdView(req.params.id, req.user.orgId);
  if (!view) return res.status(404).json({ error: "Household not found" });
  // Combined giving history — all members' gifts merged, newest first
  const gifts = await query(
    `SELECT g.id, g.donor_id, d.name AS donor_name, g.amount, g.date, g.type, g.campaign
     FROM gifts g JOIN donors d ON d.id = g.donor_id
     WHERE d.household_id=? AND g.org_id=? AND d.deleted_at IS NULL
     ORDER BY g.date DESC, g.id DESC LIMIT 200`, [req.params.id, req.user.orgId]);
  view.giving_history = gifts.map(g => ({ ...g, amount: parseFloat(g.amount) || 0 }));
  res.json(view);
}));

// Validate a proposed member set: all ids exist in this org, none already in
// a DIFFERENT household. Returns { error } (with status) or { ids, primary }.
// ── BUILD-97 Part 2 — AN ORGANISATION IS NOT A PERSON, AND THE PERSON
// SURFACES ARE WHERE THAT HAS TEETH ────────────────────────────────────────
// BUILD-80 Part 7 gave `donors.kind` three values and used it to keep
// organisations off Drift and the re-engage list, and stopped there. Two person
// surfaces were left open, and both are the kind of wrong that reaches a donor:
//
//   · A HOUSEHOLD is a marriage or a family living at one address, combined for
//     acknowledgment. "The Sunrise Foundation Household" is not a thing, and
//     the combined figure it produces would put a foundation's grants on a
//     person's giving record.
//   · A PLANNED GIFT is a bequest, an estate, an IRA beneficiary designation, a
//     life-insurance policy. Every one of them is a thing that happens because
//     a PERSON died. A foundation does not leave a bequest, and a chip on its
//     record saying it might is the product not knowing what it is looking at.
//
// One helper, one sentence, so the two refusals cannot drift apart. Kind NULL
// is a legacy row and reads as a person (the BUILD-84 rule), so nothing that
// predates the column is refused.
const PERSON_ONLY_SENTENCE = (what, name) =>
  `${name || "That record"} is an organisation, not a person, so it cannot ${what}. ` +
  `Organisations have their own list, with grant-cycle language rather than household and estate language.`;

async function validateHouseholdMembers(memberIds, primaryDonorId, orgId, allowHouseholdId) {
  const ids = Array.isArray(memberIds) ? [...new Set(memberIds.filter(Boolean))] : [];
  if (ids.length < 2) return { status: 400, error: "A household needs at least two members." };
  const members = await query(
    "SELECT id, name, kind, household_id FROM donors WHERE id = ANY(?) AND org_id=? AND deleted_at IS NULL",
    [ids, orgId]);
  if (members.length !== ids.length) return { status: 404, error: "One or more donors not found in this organization." };
  const foreign = members.find(m => m.household_id && m.household_id !== allowHouseholdId);
  if (foreign) return { status: 400, error: "A donor is already in another household." };
  // BUILD-97 Part 2 — a household is people. Checked on the MEMBER LIST rather
  // than at either route, so the create path and the edit path cannot disagree.
  const orgMember = members.find(m => m.kind === "organisation" || m.kind === "anonymous");
  if (orgMember) return { status: 400, error: PERSON_ONLY_SENTENCE("be part of a household", orgMember.name) };
  const primary = primaryDonorId && ids.includes(primaryDonorId) ? primaryDonorId : ids[0];
  return { ids, primary };
}

app.post("/households", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, memberIds, primaryDonorId, jointAcknowledgment } = req.body;
  const v = await validateHouseholdMembers(memberIds, primaryDonorId, req.user.orgId, null);
  if (v.error) return res.status(v.status).json({ error: v.error });
  // Default name: "The {primary's last name} Household"
  let hhName = (name && String(name).trim()) || "";
  if (!hhName) {
    const primaryRow = await query("SELECT name FROM donors WHERE id=? AND org_id=?", [v.primary, req.user.orgId]);
    const ln = lastName(primaryRow[0]?.name);
    hhName = ln ? `The ${ln} Household` : "Household";
  }
  const id = "hh_" + uuid().slice(0, 8);
  await withTransaction(async (client) => {
    await runTx(client, "INSERT INTO households (id,org_id,name,primary_donor_id,joint_acknowledgment,created_by,created_by_name) VALUES (?,?,?,?,?,?,?)",
      [id, req.user.orgId, hhName, v.primary, jointAcknowledgment !== false, actor(req).id, actor(req).name]);
    await runTx(client, "UPDATE donors SET household_id=? WHERE id = ANY(?) AND org_id=?", [id, v.ids, req.user.orgId]);
  });
  res.status(201).json(await householdView(id, req.user.orgId));
}));

app.put("/households/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const hh = await query("SELECT * FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!hh.length) return res.status(404).json({ error: "Household not found" });
  const { name, memberIds, primaryDonorId, jointAcknowledgment } = req.body;
  let ids = null, primary = hh[0].primary_donor_id;
  if (memberIds !== undefined) {
    const v = await validateHouseholdMembers(memberIds, primaryDonorId, req.user.orgId, req.params.id);
    if (v.error) return res.status(v.status).json({ error: v.error });
    ids = v.ids; primary = v.primary;
  } else if (primaryDonorId) {
    // primary change without member change — must be an existing member
    const m = await query("SELECT id FROM donors WHERE id=? AND org_id=? AND household_id=?", [primaryDonorId, req.user.orgId, req.params.id]);
    if (!m.length) return res.status(400).json({ error: "New primary must be a member of the household." });
    primary = primaryDonorId;
  }
  await withTransaction(async (client) => {
    if (ids) {
      // drop members no longer in the set, then (re)attach the set
      await runTx(client, "UPDATE donors SET household_id=NULL WHERE household_id=? AND org_id=? AND NOT (id = ANY(?))", [req.params.id, req.user.orgId, ids]);
      await runTx(client, "UPDATE donors SET household_id=? WHERE id = ANY(?) AND org_id=?", [req.params.id, ids, req.user.orgId]);
    }
    await runTx(client,
      "UPDATE households SET name=COALESCE(?,name), primary_donor_id=?, joint_acknowledgment=COALESCE(?,joint_acknowledgment), updated_at=NOW() WHERE id=? AND org_id=?",
      [name && String(name).trim() ? String(name).trim() : null, primary,
       jointAcknowledgment === undefined ? null : (jointAcknowledgment !== false), req.params.id, req.user.orgId]);
  });
  res.json(await householdView(req.params.id, req.user.orgId));
}));

app.delete("/households/:id", requireAuth, wrap(async (req, res) => {
  const hh = await query("SELECT id FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!hh.length) return res.status(404).json({ error: "Household not found" });
  await withTransaction(async (client) => {
    await runTx(client, "UPDATE donors SET household_id=NULL WHERE household_id=? AND org_id=?", [req.params.id, req.user.orgId]);
    await runTx(client, "DELETE FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  });
  res.json({ ok: true });
}));

// Per-donor soft-credit breakdown: hard = own gifts, soft = other household
// members' gifts, combined = the household total. Derived, no stored counter.
app.get("/donors/:id/soft-credit", requireAuth, wrap(async (req, res) => {
  const d = await query("SELECT id, household_id, total_giving FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!d.length) return res.status(404).json({ error: "Donor not found" });
  const hardCredit = parseFloat(d[0].total_giving) || 0;
  const householdId = d[0].household_id || null;
  let householdCombined = hardCredit, softCredit = 0;
  if (householdId) {
    const agg = await query(
      "SELECT COALESCE(SUM(total_giving),0) AS combined FROM donors WHERE household_id=? AND org_id=? AND deleted_at IS NULL",
      [householdId, req.user.orgId]);
    householdCombined = parseFloat(agg[0].combined) || 0;
    softCredit = householdCombined - hardCredit;
  }
  // BUILD-98 Part 1 — the soft credits on OTHER people's gifts, which is a
  // different thing from the household view above: a DAF recommender, the
  // spouse on a joint cheque, the board member who asked. Hard stays hard;
  // "with soft credit" is its own figure, beside it and labelled.
  const scRows = await query(
    `SELECT sc.id, sc.amount, sc.pct, sc.role, g.id AS gift_id, g.date, g.amount AS gift_amount,
            dg.id AS giver_id, dg.name AS giver_name
       FROM gift_soft_credits sc
       JOIN gifts g ON g.id = sc.gift_id AND g.org_id = sc.org_id
       JOIN donors dg ON dg.id = g.donor_id AND dg.org_id = g.org_id
      WHERE sc.org_id=? AND sc.donor_id=? ORDER BY g.date DESC LIMIT 200`, [req.user.orgId, req.params.id]);
  const giftSoftCents = scRows.reduce((t, r) => t + Math.round(Number(r.amount) * 100), 0);
  res.json({ donorId: d[0].id, householdId, hardCredit, softCredit, householdCombined,
    giftSoftCredit: giftSoftCents / 100,
    hardPlusGiftSoft: (Math.round(hardCredit * 100) + giftSoftCents) / 100,
    giftSoftCredits: scRows.map(r => ({ id: r.id, amount: Number(r.amount), pct: r.pct == null ? null : Number(r.pct), role: r.role,
      giftId: r.gift_id, date: r.date, giftAmount: Number(r.gift_amount), giverId: r.giver_id, giverName: r.giver_name })) });
}));


// BUILD-98 Part 1 — an imported gift's soft credit, tribute and matching
// employer, from NAMES. Resolution is deterministic and org-scoped: an email or
// an exact name that points at exactly one record is that record; a person
// named as a soft credit who is not on file is CREATED (a DAF recommender is a
// person the org should know); an honouree who is not on file stays a NAME
// (a memorial is often for somebody who never gave); a matching employer is
// found by exact name or created as an organisation.
// ── BUILD-99 (major gifts) Part 6 — PROPOSALS FROM A FILE ──────────────────
// Written AFTER the import transaction commits, the same seam BUILD-98's gift
// extras use and for the same reason: a proposal points at a person, and the
// people are created inside that transaction.
//
// THREE RULES, and each one is why this is not just an INSERT loop:
//   · A PROPOSAL IS NOT A GIFT. Nothing here touches `gifts`, `donors.total_giving`
//     or the ledger. An imported open ask is money that has NOT arrived, and the
//     import receipt routes it off the cash total by name ("open proposals").
//   · ONE OPEN PER FUND STILL HOLDS. A file carrying two open asks on one person
//     for one fund is a file with a duplicate in it; the second is SKIPPED and
//     COUNTED, never written and never silently merged into the first.
//   · A STAGE OR PROBABILITY THE PRODUCT DOES NOT RECOGNISE IS NOT GUESSED. An
//     unreadable stage falls back to `identified` and is COUNTED as having done
//     so; an unreadable probability is left BLANK, which the weighted total
//     already knows how to say out loud. Neither is invented.
async function importProposals(orgId, rows, who, donorIdByIndex) {
  const P = await import("../shared/proposalShape.js");
  const out = { written: 0, skippedDuplicate: 0, stageDefaulted: 0, probabilityDropped: 0,
                unresolved: [], fundsCreated: 0 };
  if (!Array.isArray(rows) || !rows.length) return out;

  const fundCache = new Map();
  const fundIdFor = async (name) => {
    const nm = String(name || "").trim();
    if (!nm) return null;
    const key = nm.toLowerCase();
    if (fundCache.has(key)) return fundCache.get(key);
    const [hit] = await query("SELECT id FROM fin_funds WHERE org_id=? AND LOWER(name)=LOWER(?) LIMIT 1", [orgId, nm]);
    let id = hit ? hit.id : null;
    if (!id) {
      // A fund named in a file IS a fund (BUILD-88a A.7), created UNRESTRICTED —
      // a restriction is a board decision, not a column.
      id = "fund_" + uuid().slice(0, 10);
      await run("INSERT INTO fin_funds (id,org_id,name,restricted,description) VALUES (?,?,?,false,'Created by an import')",
        [id, orgId, nm.slice(0, 120)]);
      out.fundsCreated++;
    }
    fundCache.set(key, id);
    return id;
  };
  const ownerCache = new Map();
  const ownerFor = async (name) => {
    const nm = String(name || "").trim();
    if (!nm) return null;
    const key = nm.toLowerCase();
    if (ownerCache.has(key)) return ownerCache.get(key);
    // Matched to a user of THIS org by name or email, exactly; ambiguity resolves
    // to nobody (the import owner-matching rule — never mis-assign).
    const hits = await query(
      "SELECT id, name FROM users WHERE org_id=? AND (LOWER(name)=LOWER(?) OR LOWER(email)=LOWER(?)) LIMIT 2", [orgId, nm, nm]);
    const u = hits.length === 1 ? hits[0] : null;
    ownerCache.set(key, u);
    return u;
  };

  for (const r of rows) {
    let donorId = null;
    if (r.donorIndex !== undefined && r.donorIndex !== null) donorId = donorIdByIndex(Number(r.donorIndex));
    if (!donorId && r.donorName) {
      const [d] = await query("SELECT id FROM donors WHERE org_id=? AND deleted_at IS NULL AND LOWER(name)=LOWER(?) ORDER BY created_at, id LIMIT 1",
        [orgId, String(r.donorName).trim()]);
      donorId = d ? d.id : null;
    }
    if (!donorId) { out.unresolved.push({ purpose: String(r.purpose || "").slice(0, 80), donorName: r.donorName || null, why: "nobody on file to put it on" }); continue; }

    let askCents = 0;
    try { askCents = parseMoneyOrThrow(r.askAmount, "askAmount"); } catch { askCents = 0; }
    if (!(askCents > 0)) { out.unresolved.push({ purpose: String(r.purpose || "").slice(0, 80), why: "no ask amount that could be read" }); continue; }

    // THE STAGE WORD MAY BE THE FILE'S, NOT STEWARD'S. A Salesforce export says
    // "Prospecting"; a Bloomerang or DonorPerfect one says "Submitted" or
    // "Negotiation". Steward's own key is tried first, then NPSP's documented
    // ladder (which those words overlap), and only then does it default — so a
    // real export's vocabulary is READ rather than flattened to Identified and
    // counted as a failure.
    let stage = String(r.stage || "").trim().toLowerCase();
    if (!P.stageFor(stage)) {
      const NP = await import("../shared/npspPreset.js");
      const mapped = NP.npspProposalStage(r.stage);
      if (mapped) stage = mapped;
      else { stage = "identified"; out.stageDefaulted++; }
    }
    const prob = P.normalizeProbability(r.probability);
    if (prob === undefined) out.probabilityDropped++;

    const fundId = await fundIdFor(r.fund);
    const owner = await ownerFor(r.owner);
    const purpose = P.sanitizePurpose(r.purpose) || "Ask";
    const close = /^\d{4}-\d{2}-\d{2}$/.test(String(r.expectedClose || "")) ? String(r.expectedClose) : null;

    const id = "opp_" + uuid().slice(0, 8);
    const ins = await query(
      `INSERT INTO opportunities
         (id,org_id,donor_id,name,target_amount,status,proposal_stage,probability,fund_id,notes,
          officer_id,officer_name,expected_close,created_by,created_by_name,updated_at)
       SELECT ?::text,?::text,?::text,?::text,?::numeric,?::text,?::text,?::integer,?::text,?::text,
              ?::text,?::text,?::date,?::text,?::text,NOW()
        WHERE NOT EXISTS (
          SELECT 1 FROM opportunities x WHERE x.org_id=?::text AND x.donor_id=?::text
            AND COALESCE(x.fund_id,'') = ?::text AND x.proposal_stage = ANY(?::text[]))
       RETURNING id`,
      [id, orgId, donorId, purpose, toDollars(askCents), P.statusForStage(stage), stage,
       prob == null || prob === undefined ? null : prob, fundId, P.sanitizeNotes(r.notes),
       owner ? owner.id : null, owner ? owner.name : null, close, who.id, who.name,
       orgId, donorId, fundId || "", P.isOpenStage(stage) ? P.OPEN_STAGE_KEYS : []]);
    if (ins.length) out.written++;
    else out.skippedDuplicate++;
  }
  return out;
}

async function importGiftExtras(orgId, pending, who) {
  await GC_READY;
  const out = { softCredits: 0, tributes: 0, tributeNotices: 0, matches: 0, peopleCreated: 0, unresolved: [] };
  const cache = new Map();
  const made = { count: 0 };
  const byName = async (name, opts = {}) => {
    const id = await donorByNameOrCreate(orgId, name, { ...opts, who, cache, made });
    out.peopleCreated = made.count;
    return id;
  };
  for (const { giftId, g } of pending) {
    const [gift] = await query("SELECT * FROM gifts WHERE id=? AND org_id=?", [giftId, orgId]);
    if (!gift) continue;
    const cents = Math.round(Number(gift.amount) * 100);
    const raw = {};
    const c = g.credit;
    if (c.softCredit && c.softCredit.name) {
      const pid = await byName(c.softCredit.name, { create: true });
      if (pid && pid !== gift.donor_id) raw.softCredits = [{ donorId: pid, amount: c.softCredit.amount ?? null, pct: c.softCredit.pct ?? null, role: "recommender" }];
      else if (!pid) out.unresolved.push({ kind: "soft_credit", name: c.softCredit.name });
    }
    if (c.tribute && c.tribute.name) {
      const type = GC.normaliseTributeType(c.tribute.type) || GC.TRIBUTE_HONOR;
      if (!GC.normaliseTributeType(c.tribute.type) && c.tribute.type) out.unresolved.push({ kind: "tribute_type", name: c.tribute.type });
      const hid = await byName(c.tribute.name);
      raw.tribute = { type, donorId: hid, name: c.tribute.name, notifyName: c.tribute.notifyName || null };
    }
    if (c.matchEmployer) {
      const eid = await byName(c.matchEmployer, { create: true, kind: "organisation" });
      if (eid && eid !== gift.donor_id) raw.match = { employerId: eid };
    }
    const ck = await checkGiftExtras(orgId, gift.donor_id, cents, raw);
    if (ck.errors || ck.notFound) { out.unresolved.push({ kind: "gift_credit", name: giftId, why: (ck.errors || ["not found"]).join("; ") }); continue; }
    const r = await writeGiftExtras(orgId, gift, ck.extras, { actorId: who.id, actorName: who.name });
    out.softCredits += r.softCredits; if (ck.extras.tribute) out.tributes++;
    if (r.tributeNotice) out.tributeNotices++; if (r.matchPledgeId) out.matches++;
  }
  return out;
}
// ── BUILD-98 Part 1 — a gift's soft credits, tribute and match ─────────────
app.get("/gifts/:id/extras", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id, donor_id, amount, tribute_type, tribute_donor_id, tribute_name, match_employer_id, match_pledge_id FROM gifts WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Gift not found" });
  const [soft, notice, match] = await Promise.all([
    query(`SELECT sc.donor_id, sc.amount, sc.pct, sc.role, d.name FROM gift_soft_credits sc
             JOIN donors d ON d.id = sc.donor_id AND d.org_id = sc.org_id
            WHERE sc.gift_id=? AND sc.org_id=? ORDER BY d.name`, [g.id, orgId]),
    query("SELECT id, status, notify_name, notify_email, notify_address, body FROM tribute_notices WHERE gift_id=? AND org_id=?", [g.id, orgId]),
    g.match_pledge_id ? query(
      `SELECT p.id, p.amount, p.status, p.due_date, d.name AS employer_name, COALESCE(pp.paid,0) AS paid
         FROM pledges p JOIN donors d ON d.id = p.donor_id AND d.org_id = p.org_id
         LEFT JOIN (SELECT pledge_id, SUM(amount) AS paid FROM gifts WHERE org_id=? AND pledge_id IS NOT NULL GROUP BY pledge_id) pp ON pp.pledge_id = p.id
        WHERE p.id=? AND p.org_id=?`, [orgId, g.match_pledge_id, orgId]) : [],
  ]);
  res.json({
    softCredits: soft.map(r => ({ donorId: r.donor_id, name: r.name, amount: Number(r.amount), pct: r.pct == null ? null : Number(r.pct), role: r.role })),
    tribute: g.tribute_type ? { type: g.tribute_type, donorId: g.tribute_donor_id, name: g.tribute_name } : null,
    tributeNotice: notice[0] || null,
    match: match[0] ? { pledgeId: match[0].id, employerId: g.match_employer_id, employerName: match[0].employer_name,
      expected: Number(match[0].amount), received: Number(match[0].paid), status: match[0].status, dueDate: match[0].due_date } : null,
  });
}));

// Add or change them after the gift exists. Soft credits are REPLACED as a set;
// a tribute is set; a match is added once (a second one is refused by the
// database, not by an if-statement).
app.put("/gifts/:id/extras", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT * FROM gifts WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Gift not found" });
  const ck = await checkGiftExtras(orgId, g.donor_id, Math.round(Number(g.amount) * 100),
    { softCredits: req.body?.softCredits, tribute: req.body?.tribute, match: req.body?.match });
  if (ck.notFound) return res.status(404).json({ error: "Donor not found" });
  if (ck.errors) return res.status(400).json({ error: ck.errors.join("; ") });
  const extras = { ...ck.extras };
  if (!Array.isArray(req.body?.softCredits)) delete extras.softCredits;   // absent means "leave them"
  const result = await writeGiftExtras(orgId, g, extras, { actorId: actor(req).id, actorName: actor(req).name });
  res.json({ ok: true, ...result });
}));

// The notices waiting to go to families. Steward never sends one: she prints
// or copies it, and marks it sent.
app.get("/tribute-notices", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT t.id, t.gift_id, t.tribute_type, t.honouree_name, t.notify_name, t.notify_email, t.notify_address, t.body, t.status, t.created_at,
            d.id AS donor_id, d.name AS donor_name
       FROM tribute_notices t JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
      WHERE t.org_id=? AND t.status='waiting' AND d.deleted_at IS NULL ORDER BY t.created_at DESC LIMIT 200`, [req.user.orgId]);
  res.json({ notices: rows });
}));
app.post("/tribute-notices/:id/sent", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { changes } = await run("UPDATE tribute_notices SET status='sent', sent_at=NOW(), sent_by=?, sent_by_name=? WHERE id=? AND org_id=? AND status='waiting'",
    [actor(req).id, actor(req).name, req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));
app.post("/tribute-notices/:id/skip", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("UPDATE tribute_notices SET status='skipped' WHERE id=? AND org_id=? AND status='waiting'", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

async function ackOrg(orgId) {
  const [o] = await query(
    `SELECT id, name, legal_name, receipt_address, receipt_signature_name, receipt_signature_title,
            logo_data, brand_accent, brand_accent_fg, ack_backlog_days FROM orgs WHERE id=?`, [orgId]);
  if (!o) return null;
  const display = await donorFacingOrgName(orgId, o.name || "").catch(() => o.name || "");
  return { ...o, display };
}

async function ackTemplate(orgId, templateId) {
  await ACK_READY;
  if (templateId) {
    const [t] = await query("SELECT * FROM ack_letter_templates WHERE id=? AND org_id=?", [templateId, orgId]);
    return t || null;
  }
  // Only a template somebody MARKED default stands in for "no choice". Taking
  // whichever saved template came first would print the wrong letter.
  const [t] = await query("SELECT * FROM ack_letter_templates WHERE org_id=? AND is_default=true ORDER BY created_at ASC LIMIT 1", [orgId]);
  return t || { id: null, name: "Standard thank-you", body: ACK.DEFAULT_ACK_TEMPLATE, is_default: true, builtIn: true };
}

// The gifts, grouped into one letter per donor. Every id is checked against
// this org; a foreign id is simply not found.
async function ackLetterSet(orgId, giftIds, templateId, { addressesOnly = false, signerFallback = null } = {}) {
  await ACK_READY;
  const ids = [...new Set((Array.isArray(giftIds) ? giftIds : []).map(String).filter(Boolean))].slice(0, 1000);
  if (!ids.length) return { error: "Choose the gifts to write letters for." };
  const tpl = await ackTemplate(orgId, templateId);
  if (!tpl) return { notFound: true };
  const org = await ackOrg(orgId);
  const rows = await query(
    `SELECT g.id, g.donor_id, g.amount, g.date, g.tribute_type, g.tribute_name, f.name AS fund,
            d.name, d.kind, d.salutation, d.address, d.address2, d.city, d.state, d.zip, d.country, d.deceased
       FROM gifts g JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id
      WHERE g.org_id=? AND g.id = ANY(?) AND d.deleted_at IS NULL
      ORDER BY d.name, g.date`, [orgId, ids]);
  const byDonor = new Map();
  for (const r of rows) {
    const e = byDonor.get(r.donor_id) || { donor: r, gifts: [] };
    e.gifts.push({ id: r.id, amount: r.amount, date: r.date, fund: r.fund, tributeType: r.tribute_type, tributeName: r.tribute_name });
    byDonor.set(r.donor_id, e);
  }
  // The letter is signed by the org's receipt signer when one is set, and
  // otherwise by the person printing it — a letter she prints goes out over
  // her name, which is true. Never blank: an unsigned letter is not posted.
  const signer = org.receipt_signature_name || signerFallback || "";
  const orgFields = { name: org.display, signer, signerTitle: org.receipt_signature_name ? (org.receipt_signature_title || "") : "" };
  const letters = [], skipped = [];
  for (const { donor, gifts } of byDonor.values()) {
    const giftIdsHere = gifts.map(g => g.id);
    // A letter to somebody who has died is not a thank-you; it goes to the
    // family by hand, and the batch says so rather than printing it.
    if (donor.deceased) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: "marked deceased" }); continue; }
    const address = ACK.addressLines(donor);
    if (!address) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: "no postal address on file" }); continue; }
    // Labels need an address and nothing else; a template the gift cannot fill
    // must not cost somebody their envelope.
    if (addressesOnly) { letters.push({ donorId: donor.donor_id, name: donor.name, address, text: "", giftIds: giftIdsHere, totalCents: 0 }); continue; }
    const fields = ACK.letterFields({ donor, gifts, org: orgFields });
    const r = ACK.renderLetter(tpl.body, fields);
    if (r.missing.length) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: `nothing to put in ${r.missing.map(k => `{{${k}}}`).join(", ")}` }); continue; }
    letters.push({ donorId: donor.donor_id, name: donor.name, address, text: r.text, giftIds: giftIdsHere, totalCents: fields._totalCents });
  }
  const found = new Set(rows.map(r => r.id));
  return { template: { id: tpl.id, name: tpl.name, builtIn: !!tpl.builtIn }, org, letters, skipped,
           notFound: ids.filter(id => !found.has(id)).length };
}

function renderLettersPdf(org, letters, { dateLine }) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margins: { top: 50, bottom: 40, left: 72, right: 72 }, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    const INK = "#0f1a12", SUB = "#5a554f";
    const accent = org.brand_accent || "#0d5c3a";
    let logo = null;
    if (org.logo_data && /^data:image\/(png|jpe?g);base64,/.test(org.logo_data)) {
      try { logo = Buffer.from(org.logo_data.split(",")[1], "base64"); } catch { logo = null; }
    }
    for (const L of letters) {
      doc.addPage();
      const PW = doc.page.width;
      // Letterhead: the org's name and return address, top left; the logo right.
      doc.rect(0, 0, PW, 6).fill(accent);
      if (logo) { try { doc.image(logo, PW - 72 - 60, 22, { fit: [60, 44] }); } catch { /* a logo that will not draw costs the logo, not the letter */ } }
      doc.font("Helvetica-Bold").fontSize(13).fillColor(INK).text(org.display, 72, 26, { width: PW - 220, lineBreak: false });
      if (org.receipt_address) doc.font("Helvetica").fontSize(8.5).fillColor(SUB).text(org.receipt_address, 72, 44, { width: PW - 220 });
      doc.font("Helvetica").fontSize(10).fillColor(INK).text(dateLine, 72, 100, { width: PW - 144, align: "right" });
      // The address, exactly where the window of a #10 envelope is.
      doc.font("Helvetica").fontSize(11).fillColor(INK)
        .text(L.address.join("\n"), ACK.WINDOW.x, ACK.WINDOW.y, { width: ACK.WINDOW.w, height: ACK.WINDOW.h, lineGap: 1 });
      // The body starts below the window and is held to the page: a long
      // letter is cut at the page, never allowed to spill onto a second.
      const top = ACK.WINDOW.y + ACK.WINDOW.h + 40;
      doc.font("Times-Roman").fontSize(11.5).fillColor(INK)
        .text(L.text, 72, top, { width: PW - 144, height: doc.page.height - top - 50, lineGap: 3, ellipsis: true });
    }
    doc.end();
  });
}

function renderLabelsPdf(addresses) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margin: 0, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    let page = -1;
    addresses.forEach((lines, i) => {
      const o = ACK.labelOrigin(i);
      if (o.page !== page) { doc.addPage(); page = o.page; }
      doc.font("Helvetica").fontSize(10).fillColor("#0f1a12")
        .text(lines.join("\n"), o.x + 12, o.y + 10, { width: ACK.LABELS_5160.w - 24, height: ACK.LABELS_5160.h - 14, lineGap: 0, ellipsis: true });
    });
    doc.end();
  });
}

// ── ACKNOWLEDGMENT ROUTES ──────────────────────────────────────────────────
app.get("/acknowledgments/templates", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const rows = await query("SELECT id, name, body, is_default, created_by_name, updated_at FROM ack_letter_templates WHERE org_id=? ORDER BY is_default DESC, name", [req.user.orgId]);
  res.json({
    templates: rows.length ? rows : [{ id: null, name: "Standard thank-you", body: ACK.DEFAULT_ACK_TEMPLATE, is_default: true, builtIn: true }],
    mergeFields: ACK.ACK_MERGE_FIELDS,
  });
}));

app.post("/acknowledgments/templates", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const name = String(req.body?.name || "").trim().slice(0, 120);
  const body = String(req.body?.body || "");
  if (!name) return res.status(400).json({ error: "Give the letter a name." });
  const v = ACK.validateTemplate(body);
  if (!v.ok) return res.status(400).json({ error: v.errors.join(" ") });
  const id = "alt_" + uuid().slice(0, 10);
  const makeDefault = req.body?.isDefault === true;
  if (makeDefault) await run("UPDATE ack_letter_templates SET is_default=false WHERE org_id=?", [req.user.orgId]);
  await run(`INSERT INTO ack_letter_templates (id,org_id,name,body,is_default,created_by,created_by_name) VALUES (?,?,?,?,?,?,?)`,
    [id, req.user.orgId, name, body, makeDefault, actor(req).id, actor(req).name]);
  res.status(201).json({ id });
}));

app.put("/acknowledgments/templates/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const [t] = await query("SELECT id FROM ack_letter_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const name = String(req.body?.name || "").trim().slice(0, 120);
  const body = String(req.body?.body || "");
  const v = ACK.validateTemplate(body);
  if (!name) return res.status(400).json({ error: "Give the letter a name." });
  if (!v.ok) return res.status(400).json({ error: v.errors.join(" ") });
  if (req.body?.isDefault === true) await run("UPDATE ack_letter_templates SET is_default=false WHERE org_id=?", [req.user.orgId]);
  await run("UPDATE ack_letter_templates SET name=?, body=?, is_default=COALESCE(?, is_default), updated_at=NOW() WHERE id=? AND org_id=?",
    [name, body, req.body?.isDefault === true ? true : null, t.id, req.user.orgId]);
  res.json({ ok: true });
}));

app.delete("/acknowledgments/templates/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM ack_letter_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

// The backlog: gifts nobody has thanked, older than the org's own N days.
app.get("/acknowledgments/backlog", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const orgId = req.user.orgId;
  const org = await ackOrg(orgId);
  const days = Number.isInteger(org?.ack_backlog_days) && org.ack_backlog_days >= 0 ? org.ack_backlog_days : ACK.DEFAULT_ACK_BACKLOG_DAYS;
  const today = orgToday(await orgTz(orgId));                 // ORG_TZ_SEAM_OK
  const cutoff = orgTime.addDays(today, -days);
  const rows = await query(
    `SELECT g.id, g.amount, g.date, g.donor_id, d.name, d.address, d.city, d.state, d.zip, d.deceased, f.name AS fund
       FROM gifts g JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id
      WHERE g.org_id=? AND COALESCE(g.acknowledgement_sent,false) = false AND g.acknowledgement_sent_at IS NULL
        AND g.is_sample IS NOT TRUE AND d.is_sample IS NOT TRUE AND d.deleted_at IS NULL
        AND g.date <= ? AND g.date >= ?
      ORDER BY g.date ASC, d.name LIMIT 500`, [orgId, cutoff, orgTime.addDays(today, -730)]);
  res.json({
    days, cutoff,
    // The one sentence under the count, per BUILD-97 Part 2.
    sentence: `Gifts that arrived more than ${days === 1 ? "a day" : days + " days"} ago and nobody has marked as thanked. An administrator can change the number of days here.`,
    gifts: rows.map(r => ({ id: r.id, amount: Number(r.amount), date: r.date, donorId: r.donor_id, name: r.name, fund: r.fund,
      hasAddress: !!ACK.addressLines(r), deceased: !!r.deceased })),
  });
}));

app.put("/acknowledgments/settings", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const n = Number(req.body?.backlogDays);
  if (!Number.isInteger(n) || n < 0 || n > 365) return res.status(400).json({ error: "backlogDays is a whole number of days, 0 to 365." });
  await run("UPDATE orgs SET ack_backlog_days=? WHERE id=?", [n, req.user.orgId]);
  res.json({ backlogDays: n });
}));

// What the batch WOULD print, and who it would leave out and why. Read-only.
app.post("/acknowledgments/letters/preview", requireAuth, wrap(async (req, res) => {
  const [me] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, req.body?.templateId || null, { signerFallback: me?.name || null });
  if (set.error) return res.status(400).json({ error: set.error });
  if (set.notFound === true) return res.status(404).json({ error: "Template not found" });
  res.json({ template: set.template, letters: set.letters.map(l => ({ donorId: l.donorId, name: l.name, address: l.address, text: l.text, giftIds: l.giftIds, total: l.totalCents / 100 })),
             skipped: set.skipped, giftsNotFound: set.notFound });
}));

// The PDF. One page per donor. A POST, because it carries a selection — and a
// print changes nothing: marking the letters sent is its own request.
app.post("/acknowledgments/letters/pdf", requireAuth, wrap(async (req, res) => {
  const [me] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, req.body?.templateId || null, { signerFallback: me?.name || null });
  if (set.error) return res.status(400).json({ error: set.error });
  if (set.notFound === true) return res.status(404).json({ error: "Template not found" });
  if (!set.letters.length) return res.status(409).json({ error: "no_letters", skipped: set.skipped,
    message: "None of these gifts can be printed yet. The reason is beside each name." });
  const today = orgToday(await orgTz(req.user.orgId));           // ORG_TZ_SEAM_OK
  const pdf = await renderLettersPdf(set.org, set.letters, { dateLine: ACK.formatLetterDate(today) });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="thank-you-letters-${today}.pdf"`);
  res.setHeader("X-Letters-Printed", String(set.letters.length));
  res.setHeader("X-Letters-Skipped", String(set.skipped.length));
  res.setHeader("Access-Control-Expose-Headers", "X-Letters-Printed, X-Letters-Skipped");
  res.end(pdf);
}));

// Mailing labels, Avery 5160: one per donor, never one per gift.
app.post("/acknowledgments/labels/pdf", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, null, { addressesOnly: true });
  if (set.error) return res.status(400).json({ error: set.error });
  const addresses = set.letters.map(l => l.address);
  if (!addresses.length) return res.status(409).json({ error: "no_addresses", skipped: set.skipped });
  const pdf = await renderLabelsPdf(addresses);
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="mailing-labels.pdf"`);
  res.setHeader("X-Labels", String(addresses.length));
  res.setHeader("Access-Control-Expose-Headers", "X-Labels");
  res.end(pdf);
}));

// Who thanked them, when, and how. Idempotent: a gift already marked keeps its
// first stamp, because "who thanked them first" is the fact worth keeping.
app.post("/acknowledgments/mark", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const ids = [...new Set((Array.isArray(req.body?.giftIds) ? req.body.giftIds : []).map(String))].slice(0, 1000);
  const via = String(req.body?.via || "");
  if (!ids.length) return res.status(400).json({ error: "Choose the gifts that were thanked." });
  if (!ACK.ACK_VIA.includes(via)) return res.status(400).json({ error: `How were they thanked? One of: ${ACK.ACK_VIA.join(", ")}.` });
  // "Who thanked them" is read by a person, so it is their NAME — actor()'s
  // name is the login email, which is an audit stamp, not a signature.
  const [u] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const who = u?.name || actor(req).name;
  const rows = await query(
    `UPDATE gifts SET acknowledgement_sent=true, acknowledgement_sent_at=COALESCE(acknowledgement_sent_at, NOW()),
                      acknowledged_by=COALESCE(acknowledged_by, ?), acknowledged_by_name=COALESCE(acknowledged_by_name, ?),
                      acknowledged_via=COALESCE(acknowledged_via, ?)
      WHERE org_id=? AND id = ANY(?) RETURNING id`, [actor(req).id, who, via, req.user.orgId, ids]);
  // The drafted thank-you (88b) for these gifts is done too; leaving it in the
  // queue would ask her to thank somebody twice.
  await run("UPDATE thank_you_drafts SET sent_at=COALESCE(sent_at, NOW()) WHERE org_id=? AND gift_id = ANY(?) AND sent_at IS NULL AND skipped_at IS NULL", [req.user.orgId, ids]).catch(() => {});
  res.json({ marked: rows.length });
}));

// ── Constituent designations (BUILD-14) ────────────────────────────────────
