// ── Officer portfolios + color (BUILD-14, Team plan) ───────────────────────
// Read is ungated (a Core org still sees its officers), but returns `tier` +
// `single_user` so the UI locks the color feature and hides it for a
// one-person shop. Assigning a color is Team-only and admin-gated.
app.get("/portfolio/officers", requireAuth, wrap(async (req, res) => {
  const orgRows = await query("SELECT plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const tier = orgRows.length ? orgPlanTier(orgRows[0]) : "core";
  // portfolio_count/giving use the SAME definition as Home's cards + the board
  // (BUILD-30): assigned donors in a pipeline stage. The stage guard lives in the
  // JOIN so a non-pipeline-stage donor can't inflate the legend past the board.
  const officers = await query(
    `SELECT u.id, u.name, u.email, u.role, u.portfolio_color,
            COUNT(d.id)::int AS portfolio_count, COALESCE(SUM(d.total_giving),0) AS portfolio_giving
     FROM users u
     LEFT JOIN donors d ON d.assigned_to = u.id AND d.org_id = u.org_id AND d.deleted_at IS NULL AND COALESCE(d.stage, d.suggested_stage) = ANY(?)
     WHERE u.org_id=? GROUP BY u.id ORDER BY portfolio_giving DESC, u.name`, [ALL_PIPELINE_STAGES, req.user.orgId]);
  // Pending invitees (invited, not yet accepted, unexpired) are surfaced too so
  // the import officer-mapping screen can match + assign donors to them BEFORE
  // they accept (the assignment resolves into their portfolio on acceptance).
  // Includes each invite's held pending-donor count so the UI can show it.
  const invites = await query(
    `SELECT i.id, i.email,
            COUNT(d.id)::int AS pending_count
       FROM invites i
       LEFT JOIN donors d ON d.pending_assignee_invite_id = i.id AND d.org_id = i.org_id AND d.deleted_at IS NULL
      WHERE i.org_id=? AND i.accepted_at IS NULL AND i.expires_at > NOW()
      GROUP BY i.id, i.email ORDER BY i.created_at DESC`, [req.user.orgId]);
  res.json({
    tier,
    single_user: officers.length <= 1,
    officers: officers.map(o => ({
      ...o,
      portfolio_count: parseInt(o.portfolio_count, 10) || 0,
      portfolio_giving: parseFloat(o.portfolio_giving) || 0,
    })),
    invites: invites.map(i => ({ id: i.id, email: i.email, name: inviteeDisplayName(i.email), pending_count: parseInt(i.pending_count, 10) || 0 })),
  });
}));

app.put("/portfolio/officers/:userId/color", requireAuth, requireAdmin, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const { color } = req.body;
  if (color && !/^#[0-9a-fA-F]{6}$/.test(String(color))) return res.status(400).json({ error: "Color must be a 6-digit hex like #1a6b4a." });
  const u = await query("SELECT id FROM users WHERE id=? AND org_id=?", [req.params.userId, req.user.orgId]);
  if (!u.length) return res.status(404).json({ error: "Officer not found" });
  await run("UPDATE users SET portfolio_color=? WHERE id=? AND org_id=?", [color || null, req.params.userId, req.user.orgId]);
  res.json({ ok: true, userId: req.params.userId, color: color || null });
}));

// ── Moves management & prospect pipeline (BUILD-15, Team plan) ─────────────
// The whole pipeline is a staffed-office capability → Team. Reads return a
// `tier`/`locked` flag rather than 403'ing so a Core org renders a graceful
// "upgrade to manage a major-gifts pipeline" state, not a broken tab. Every
// WRITE (move, opportunity) is hard requirePlan('team') + checkWriteAccess.

// GET /pipeline — the board: prospects grouped by stage, officer color map,
// ask amount + stage age + next task per card, and the forecast. Batched
// queries only (no N+1). Optional ?assignedTo= (portfolio) and ?designation=.
app.get("/pipeline", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const orgRows = await query("SELECT plan, subscription_status FROM orgs WHERE id=?", [orgId]);
  const tier = orgRows.length ? orgPlanTier(orgRows[0]) : "core";
  const stages = ALL_PIPELINE_STAGES.map(id => ({ id, label: id.charAt(0).toUpperCase() + id.slice(1) }));
  // Core orgs get a READ-only locked preview populated with their OWN data
  // (the board derives entirely from donors.stage / opportunities / moves /
  // tasks — all org-scoped reads a Core user already has). Writes stay hard-
  // gated on POST /pipeline/:donorId/move (requirePlan('team') → 403), so this
  // only softens the read presentation; it does not open a write path.
  const locked = tier !== "team";

  const officers = await query(
    "SELECT id, name, portfolio_color FROM users WHERE org_id=? ORDER BY name", [orgId]);
  const single_user = officers.length <= 1;

  // BUILD-32 Part 4 — the "My portfolio / All portfolios" toggle (and the
  // officer filter) is meaningless unless 2+ officers actually have donors to
  // work. Count distinct officers with ≥1 ASSIGNED donor in a pipeline stage
  // (the same membership definition the board uses). `multiOfficer` drives
  // hiding the single-value pickers client-side; `canViewAll` still gates on
  // admin (a lone admin sees no toggle even though they could "view all").
  const distinctOfficers = await query(
    `SELECT COUNT(DISTINCT assigned_to)::int AS c FROM donors
       WHERE org_id=? AND assigned_to IS NOT NULL AND deleted_at IS NULL
         AND stage = ANY(?)`, [orgId, ALL_PIPELINE_STAGES]);
  const multiOfficer = (distinctOfficers[0]?.c || 0) >= 2;

  // ── The board is a PORTFOLIO, not the donor list ─────────────────────────
  // Membership = ASSIGNMENT (BUILD-30): a donor assigned to an officer is on
  // that officer's board, full stop. There is no separate "on the board" flag.
  // Unassigned (e.g. bulk-imported) donors match nothing here — they live in
  // the Directory with their stage LABEL and never flood this board. `scope`
  // defaults to the caller's own portfolio; a specific `assignedTo` overrides.
  // The exact same `portfolioMembership` helper feeds Home's Portfolio and
  // Pipeline cards, so all three counts are one number by construction.
  // Cross-officer visibility ("All portfolios", or filtering to another officer)
  // is an ADMIN/ED oversight view — the whole-shop forecast Team sells. An
  // individual officer only ever sees their OWN portfolio (BUILD-31 Part 4).
  // Enforced server-side, not just hidden in the UI: a non-admin's scope=all or
  // foreign assignedTo is downgraded to their own portfolio.
  const isAdmin = req.user.role === "admin";
  let scope = req.query.scope === "all" ? "all" : "mine";
  let assignedTo = req.query.assignedTo || null;
  if (!isAdmin) {
    scope = "mine";
    if (assignedTo && assignedTo !== userId) assignedTo = null;
  }
  const membership = portfolioMembership({ orgId, userId, scope, assignedTo, alias: "d" });
  const filters = [membership.where];
  const params = [...membership.params];
  if (req.query.designation) {
    filters.push("EXISTS (SELECT 1 FROM donor_designations dd WHERE dd.donor_id = d.id AND dd.org_id = d.org_id AND dd.kind = ?)");
    params.push(req.query.designation);
  }
  if (req.query.search && String(req.query.search).trim()) {
    filters.push("LOWER(d.name) LIKE ?"); params.push("%" + String(req.query.search).trim().toLowerCase() + "%");
  }
  const minGiving = parseFloat(req.query.minGiving);
  if (Number.isFinite(minGiving) && minGiving > 0) { filters.push("d.total_giving >= ?"); params.push(minGiving); }

  const donors = await query(
    `SELECT d.id, d.name, COALESCE(d.stage, d.suggested_stage) AS stage, (d.stage IS NULL) AS stage_suggested,
            d.total_giving, d.last_gift_date, d.assigned_to, d.assigned_to_name, d.updated_at, d.created_at
       FROM donors d WHERE ${filters.join(" AND ")}`, params);

  // Open asks aggregated per donor (org-wide, joined in JS).
  const oppAgg = await query(
    `SELECT donor_id, COALESCE(SUM(target_amount),0) AS ask, COUNT(*)::int AS cnt
       FROM opportunities WHERE org_id=? AND status='open' GROUP BY donor_id`, [orgId]);
  const askByDonor = Object.fromEntries(oppAgg.map(o => [o.donor_id, { ask: parseFloat(o.ask) || 0, cnt: o.cnt }]));

  // Most recent move INTO the donor's current stage → stage age.
  const lastMoves = await query(
    `SELECT DISTINCT ON (donor_id, to_stage) donor_id, to_stage, created_at
       FROM moves WHERE org_id=? ORDER BY donor_id, to_stage, created_at DESC`, [orgId]);
  const moveInto = {};
  for (const m of lastMoves) moveInto[m.donor_id + "|" + m.to_stage] = m.created_at;

  // Next open task per donor (earliest due).
  const nextTasks = await query(
    `SELECT DISTINCT ON (donor_id) donor_id, title, due FROM tasks
       WHERE org_id=? AND done=0 AND donor_id IS NOT NULL
       ORDER BY donor_id, (NULLIF(due,'')) ASC NULLS LAST`, [orgId]);
  const taskByDonor = Object.fromEntries(nextTasks.map(t => [t.donor_id, { title: t.title, due: t.due }]));

  // BUILD-76 Part 2 — pipeline cards carry the drift badge, same computation
  // as the home list (scoped to the board's own donors).
  const boardIds = donors.map(d => d.id);
  const { map: driftMap } = await computeDriftForDonors(orgId, { donorIds: boardIds.length ? boardIds : ["_none_"] });

  const now = Date.now();
  const columns = {}; ALL_PIPELINE_STAGES.forEach(s => { columns[s] = []; });
  let forecastOpen = 0, forecastWeighted = 0, openCount = 0;
  for (const d of donors) {
    const a = askByDonor[d.id] || { ask: 0, cnt: 0 };
    forecastOpen += a.ask; openCount += a.cnt;
    forecastWeighted += a.ask * (STAGE_WEIGHT[d.stage] || 0);
    const enteredStage = moveInto[d.id + "|" + d.stage] || d.updated_at || d.created_at;
    const stageAge = enteredStage ? Math.max(0, Math.floor((now - new Date(enteredStage).getTime()) / 86400000)) : null;
    (columns[d.stage] = columns[d.stage] || []).push({
      donorId: d.id, name: d.name, stage: d.stage,
      // BUILD-83 Part 3.5 — the card says whether a human placed this donor or
      // the giving history merely suggests it.
      stageSuggested: d.stage_suggested === true || d.stage_suggested === "t",
      totalGiving: parseFloat(d.total_giving) || 0,
      lastGiftDate: d.last_gift_date || null,
      assignedTo: d.assigned_to, assignedToName: d.assigned_to_name,
      askAmount: a.ask, openOppCount: a.cnt, stageAge,
      nextTask: taskByDonor[d.id] || null,
      drift: driftBadgeField(driftMap.get(d.id)),
    });
  }

  // Sort each column + cap the payload so a large portfolio never ships (or
  // renders) hundreds of cards. counts[stage] carries the TRUE size so the UI
  // can show "showing N of M". Sorts: value (default), last gift, stage age.
  const sort = ["value", "last_gift", "stage_age"].includes(req.query.sort) ? req.query.sort : "value";
  const cmp = {
    value: (a, b) => (b.totalGiving - a.totalGiving) || (b.askAmount - a.askAmount),
    last_gift: (a, b) => (b.lastGiftDate ? Date.parse(b.lastGiftDate) : 0) - (a.lastGiftDate ? Date.parse(a.lastGiftDate) : 0),
    stage_age: (a, b) => (b.stageAge || 0) - (a.stageAge || 0),
  }[sort];
  const PER_COLUMN_CAP = 200;
  const counts = {};
  for (const s of ALL_PIPELINE_STAGES) {
    counts[s] = columns[s].length;
    columns[s].sort(cmp);
    if (columns[s].length > PER_COLUMN_CAP) columns[s] = columns[s].slice(0, PER_COLUMN_CAP);
  }

  // Won this quarter (period) — a coarse pipeline health figure.
  const { start } = finPeriodBounds("fiscal", 0, await orgTz(req.user.orgId));   // ORG_TZ_SEAM_OK
  const wonAgg = await query(
    `SELECT COALESCE(SUM(gift_amount),0) AS amt, COUNT(*)::int AS cnt FROM opportunities
       WHERE org_id=? AND status='won' AND closed_at >= ?`, [orgId, start]);
  res.json({
    tier, locked, single_user, multiOfficer, stages, scope, sort, canViewAll: isAdmin,
    officers: officers.map(o => ({ id: o.id, name: o.name, color: o.portfolio_color })),
    columns, counts, total: donors.length, cap: PER_COLUMN_CAP,
    forecast: {
      open: Math.round(forecastOpen), weighted: Math.round(forecastWeighted), openCount,
      wonThisPeriod: parseFloat(wonAgg[0].amt) || 0, wonCount: wonAgg[0].cnt,
    },
  });
}));

// POST /pipeline/add — the deliberate act that puts prospects on the working
// board (single or bulk via `ids`). Assignment IS membership (BUILD-30), so
// "add to my pipeline" = assign to the caller (donors nobody owns yet land on
// the caller's own board; already-owned donors stay with their owner). No
// separate flag. Cross-officer assignment stays the admin `/donors/bulk-assign`.
// Team + write-gated.
app.post("/pipeline/add", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const ids = Array.isArray(req.body.ids) ? req.body.ids.filter(Boolean) : [];
  if (!ids.length) return res.status(400).json({ error: "ids array required" });
  const owned = await query(
    "SELECT id FROM donors WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL", [ids, req.user.orgId]);
  if (owned.length !== ids.length) return res.status(404).json({ error: "One or more donors not found in your org" });
  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const myName = userRow[0]?.name || "";
  const result = await run(
    `UPDATE donors
        SET assigned_to      = COALESCE(assigned_to, ?),
            assigned_to_name = COALESCE(assigned_to_name, ?),
            updated_at = NOW()
      WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL`,
    [req.user.userId, myName, ids, req.user.orgId]);
  res.json({ added: result.changes });
}));

// POST /pipeline/remove — take a donor OFF the working board (single or bulk).
// Assignment IS membership (BUILD-30), so removing from the board = unassigning;
// the donor stays in the Directory with its stage label untouched. Team +
// write-gated (a curation write, not a delete).
app.post("/pipeline/remove", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const ids = Array.isArray(req.body.ids) ? req.body.ids.filter(Boolean) : [];
  if (!ids.length) return res.status(400).json({ error: "ids array required" });
  const owned = await query(
    "SELECT id FROM donors WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL", [ids, req.user.orgId]);
  if (owned.length !== ids.length) return res.status(404).json({ error: "One or more donors not found in your org" });
  const result = await run(
    `UPDATE donors SET assigned_to = NULL, assigned_to_name = NULL, updated_at = NOW()
      WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL`,
    [ids, req.user.orgId]);
  res.json({ removed: result.changes });
}));

// POST /pipeline/:donorId/move — the managed stage change. Description REQUIRED.
app.post("/pipeline/:donorId/move", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const { toStage, description } = req.body;
  if (!ALL_PIPELINE_STAGES.includes(toStage)) return res.status(400).json({ error: "Invalid stage" });
  if (!description || !String(description).trim()) return res.status(400).json({ error: "A description of the move is required." });
  const rows = await query("SELECT stage FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.donorId, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Donor not found" });
  const fromStage = rows[0].stage;
  if (fromStage === toStage) return res.status(400).json({ error: "Donor is already in that stage." });

  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const officerName = userRow[0]?.name || "";
  await run("UPDATE donors SET stage=?, updated_at=NOW() WHERE id=? AND org_id=?", [toStage, req.params.donorId, req.user.orgId]);
  const moveId = await recordMove(req.user.orgId, req.params.donorId, req.user.userId, officerName, fromStage, toStage, String(description).trim());
  // Keep the donor timeline consistent with the legacy stage_change path.
  try {
    await run(
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name) VALUES (?,?,?,?,?,?,?,?)",
      ["int_" + uuid().slice(0, 8), req.user.orgId, req.params.donorId, "stage_change",
       `Moved ${fromStage} → ${toStage}: ${String(description).trim()}`,
       new Date().toISOString().split("T")[0], req.user.userId, officerName]);
  } catch (e) { console.error("move interaction log:", e.message); }
  res.status(201).json({ ok: true, moveId, stage: toStage, fromStage });
}));

// GET /donors/:id/move-suggestions — signal-based suggestions (BUILD-22).
// A read: never changes stage. The officer accepts (→ POST /pipeline/:id/move)
// or dismisses. Org-scoped; foreign donor → 404.
app.get("/donors/:id/move-suggestions", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT * FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Donor not found" });
  res.json({ suggestions: computeMoveSuggestions(rows[0]) });
}));

// POST /pipeline/run-auto-lapse — run the auto-lapse sweep for the caller's org
// now (drives the exact scheduled path; for ops + tests). Admin-only, same bar
// as /sequences/process and /recurring/process-dunning.
app.post("/pipeline/run-auto-lapse", requireAuth, requireAdmin, wrap(async (req, res) => {
  const moved = await autoLapseOrg(req.user.orgId);
  res.json({ moved });
}));

// GET /donors/:id/moves — full move history for a constituent.
app.get("/donors/:id/moves", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const rows = await query(
    "SELECT id, officer_id, officer_name, from_stage, to_stage, description, created_at FROM moves WHERE org_id=? AND donor_id=? ORDER BY created_at DESC",
    [req.user.orgId, req.params.id]);
  res.json(rows);
}));

// GET /donors/:id/opportunities — asks on a prospect.
app.get("/donors/:id/opportunities", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const rows = await query(
    "SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE org_id=? AND donor_id=? ORDER BY (status='open') DESC, created_at DESC",
    [req.user.orgId, req.params.id]);
  res.json(rows.map(o => ({ ...o, target_amount: parseFloat(o.target_amount) || 0, gift_amount: o.gift_amount == null ? null : parseFloat(o.gift_amount) })));
}));

app.post("/donors/:id/opportunities", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const { name, targetAmount, expectedClose } = req.body;
  const amt = parseFloat(targetAmount);
  if (!(amt > 0)) return res.status(400).json({ error: "A positive target ask amount is required." });
  const d = await query("SELECT assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!d.length) return res.status(404).json({ error: "Donor not found" });
  // Officer = the donor's relationship owner; falls back to the creating user.
  let officerId = d[0].assigned_to, officerName = d[0].assigned_to_name;
  if (!officerId) { officerId = req.user.userId; const u = await query("SELECT name FROM users WHERE id=?", [req.user.userId]); officerName = u[0]?.name || ""; }
  // BUILD-99 Part 1 — THIS DOOR AND THE PROPOSALS DOOR ARE ONE OBJECT, so they
  // obey one rule. An ask written here is a proposal at stage `asked` (BUILD-15's
  // own word for what target_amount is), its status is DERIVED from that stage by
  // the one derivation, and "one open at a time per fund" applies — because two
  // doors with two rules over the same rows is how a double-ask gets in. This
  // NARROWS BUILD-15, which allowed several open asks on one prospect; the
  // narrowing is the brief's, and `tests/moves.test.js` was updated to match.
  const P99 = await proposalMod();
  const clash = await openProposalConflict(req.user.orgId, req.params.id, null, null);
  if (clash) return res.status(409).json(clash);
  const id = "opp_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO opportunities (id,org_id,donor_id,name,target_amount,status,proposal_stage,officer_id,officer_name,expected_close,created_by,created_by_name) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, req.params.id, (name || "").trim() || "Ask", amt,
     P99.statusForStage("asked"), "asked", officerId, officerName || "", expectedClose || null, actor(req).id, actor(req).name]);
  const rows = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [id]);
  res.status(201).json({ ...rows[0], target_amount: parseFloat(rows[0].target_amount) || 0 });
}));

// PUT /opportunities/:id — edit, or close won/lost. Closing 'won' links the
// real gift and records the actual gift amount (the ask-vs-gift accountability).
app.put("/opportunities/:id", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const existing = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Opportunity not found" });
  const { name, targetAmount, expectedClose, status, giftId, giftAmount } = req.body;
  const sets = [], params = [];
  if (name !== undefined) { sets.push("name=?"); params.push((name || "").trim() || "Ask"); }
  if (targetAmount !== undefined) { const a = parseFloat(targetAmount); if (!(a > 0)) return res.status(400).json({ error: "Target ask amount must be positive." }); sets.push("target_amount=?"); params.push(a); }
  if (expectedClose !== undefined) { sets.push("expected_close=?"); params.push(expectedClose || null); }
  if (status !== undefined) {
    if (!["open", "won", "lost"].includes(status)) return res.status(400).json({ error: "Invalid status" });
    sets.push("status=?"); params.push(status);
    // BUILD-99 Part 1 — THE STAGE MOVES WITH THE STATUS, ALWAYS. A status
    // written here without its stage would leave the Proposals screen showing
    // "Asked" on a row the board calls won: one object, two truths, and the way
    // they disagree is a board report that is wrong. `stageFromLegacyStatus` is
    // the same mapping the migration used, so this door and that one agree.
    const P99 = await proposalMod();
    sets.push("proposal_stage=?"); params.push(P99.stageFromLegacyStatus(status));
    if (status === "won") {
      let amt = giftAmount != null ? parseFloat(giftAmount) : null;
      let gId = giftId || null;
      if (gId) {
        const g = await query("SELECT amount FROM gifts WHERE id=? AND org_id=?", [gId, req.user.orgId]);
        if (!g.length) return res.status(404).json({ error: "Linked gift not found" });
        if (amt == null) amt = parseFloat(g[0].amount) || 0;
      }
      sets.push("gift_id=?", "gift_amount=?", "closed_at=NOW()"); params.push(gId, amt);
    } else if (status === "lost") {
      sets.push("gift_id=NULL", "gift_amount=NULL", "closed_at=NOW()");
    } else { // reopen
      sets.push("gift_id=NULL", "gift_amount=NULL", "closed_at=NULL");
    }
  }
  if (!sets.length) return res.status(400).json({ error: "Nothing to update" });
  params.push(req.params.id, req.user.orgId);
  await run(`UPDATE opportunities SET ${sets.join(",")} WHERE id=? AND org_id=?`, params);
  const rows = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [req.params.id]);
  res.json({ ...rows[0], target_amount: parseFloat(rows[0].target_amount) || 0, gift_amount: rows[0].gift_amount == null ? null : parseFloat(rows[0].gift_amount) });
}));

app.delete("/opportunities/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  res.json({ success: true });
}));

// ── BUILD-99 Part 1 — PROPOSALS ────────────────────────────────────────────
// A proposal is one ask to one person or household: purpose, ask amount,
// expected close, stage, a probability SHE set, the fund it lands in, the
// officer who owns it, notes. shared/proposalShape.js holds every rule; these
// routes are its only writers. Nothing here infers a capacity, a probability or
// an amount — see that module's header for why the probability list is closed.
//
// The rows live in `opportunities` (BUILD-15's table, extended — db.js says
// why), so the pipeline board's ask totals, wonThisPeriod and officer activity
// keep reading THE SAME ROWS. One ask, one place.
async function proposalMod() { return import("../shared/proposalShape.js"); }

// THE DATABASE FORMATS THE DATE, AND NOTHING HERE PARSES ONE.
// A `DATE` column comes back from pg as a JS Date at LOCAL midnight, so
// `String(d).slice(0,10)` is "Sun Nov 15" — which is what this screen showed on
// its first run. The first fix read the Date's LOCAL calendar parts, which is
// right for THIS input and is still the wrong SHAPE: `tests/date-seam.test.js`
// names any helper that reads a process-local date as tainted, and it is right
// to, because the next caller will hand it something built in a different zone.
// So the date is TO_CHAR'd in SQL (BUILD-86's own gotcha says exactly this) and
// read as the string it already is. There is no date helper here to taint.
// The wire shape. Money leaves as dollars (every other money route does) AND as
// integer cents, because the weighted total is computed in cents and a screen
// that re-derives cents from a float is how a total ends up a penny out.
function proposalRow(r, funds) {
  const askCents = toCents(r.target_amount) || 0;
  return {
    id: r.id, donorId: r.donor_id, donorName: r.donor_name || undefined,
    purpose: r.name || "", askAmount: toDollars(askCents), askCents,
    stage: r.proposal_stage, status: r.status,
    probability: r.probability == null ? null : Number(r.probability),
    expectedClose: r.expected_close_civil || null,
    fundId: r.fund_id || null,
    fundName: r.fund_id ? (funds?.get(r.fund_id) || null) : null,
    officerId: r.officer_id || null, officerName: r.officer_name || "",
    notes: r.notes || "",
    declineReason: r.decline_reason || null, declinedOn: r.declined_on || null,
    commitKind: r.commit_kind || null,
    giftId: r.gift_id || null, pledgeId: r.pledge_id || null,
    giftAmount: r.gift_amount == null ? null : toDollars(toCents(r.gift_amount) || 0),
    createdAt: r.created_at, closedAt: r.closed_at,
    createdByName: r.created_by_name || "",
  };
}

async function orgFundNames(orgId) {
  const rows = await query("SELECT id, name FROM fin_funds WHERE org_id=?", [orgId]);
  return new Map(rows.map(r => [r.id, r.name]));
}

// A fund id a caller names is checked against THIS org before anything is
// written — never trusted off a payload (the recordGift rule, same reason).
async function checkProposalFund(orgId, fundId) {
  if (!fundId) return { ok: true, fundId: null };
  const rows = await query("SELECT id, name FROM fin_funds WHERE id=? AND org_id=?", [fundId, orgId]);
  if (!rows.length) return { ok: false };
  return { ok: true, fundId: rows[0].id, fundName: rows[0].name };
}

// THE HOUSEHOLD HALF OF "ONE OPEN AT A TIME PER FUND". The per-person half is a
// unique index (db.js); this is the half a partial index cannot express, and it
// is the half that matters most — asking a husband and a wife separately for
// the capital campaign is exactly the double-ask the rule exists to stop.
async function openProposalConflict(orgId, donorId, fundId, excludeId) {
  const [me] = await query("SELECT id, household_id FROM donors WHERE id=? AND org_id=?", [donorId, orgId]);
  if (!me) return null;
  const P = await proposalMod();
  const rows = await query(
    `SELECT o.id, o.donor_id, d.name AS donor_name, d.household_id
       FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
      WHERE o.org_id = ? AND o.proposal_stage = ANY(?::text[]) AND COALESCE(o.fund_id,'') = ?
        AND (d.id = ? OR (?::text IS NOT NULL AND d.household_id = ?))
        AND d.deleted_at IS NULL`,
    [orgId, P.OPEN_STAGE_KEYS, fundId || "", donorId, me.household_id, me.household_id]);
  const hit = rows.find(r => r.id !== excludeId);
  if (!hit) return null;
  const fundLabel = fundId ? (await orgFundNames(orgId)).get(fundId) || "fund" : "no particular fund";
  return {
    code: "proposal_already_open",
    error: hit.donor_id === donorId
      ? `There is already an open proposal for ${fundLabel}. Close or move that one first.`
      : `${hit.donor_name} in the same household already has an open proposal for ${fundLabel}. Close or move that one first.`,
    conflictId: hit.id,
  };
}

// GET /donors/:id/proposals — the proposals on one person, newest ask first with
// the open ones on top. The profile panel sits ABOVE giving history.
app.get("/donors/:id/proposals", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const P = await proposalMod();
  const funds = await orgFundNames(req.user.orgId);
  const rows = await query(
    `SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE org_id=? AND donor_id=?
      ORDER BY (proposal_stage = ANY(?::text[])) DESC, expected_close NULLS LAST, created_at DESC`,
    [req.user.orgId, req.params.id, P.OPEN_STAGE_KEYS]);
  const proposals = rows.map(r => proposalRow(r, funds));
  const w = P.weightedTotal(proposals);
  res.json({
    proposals,
    weighted: { cents: w.cents, amount: toDollars(w.cents), counted: w.counted, unset: w.unset, openCount: w.openCount,
                sentence: P.weightedSentence(w, money.formatCentsPlain) },
    stages: P.PROPOSAL_STAGES, probabilities: P.PROBABILITIES, declineReasons: P.DECLINE_REASONS,
    // The profile's own form needs the pickers too, or it can only ever offer
    // "no fund" and "the relationship owner" — found by the walk.
    funds: [...funds.entries()].map(([id, name]) => ({ id, name })),
    officers: (await query("SELECT id, name FROM users WHERE org_id=? ORDER BY name", [req.user.orgId]).catch(() => []))
      .map(o => ({ id: o.id, name: o.name })),
  });
}));

// POST /donors/:id/proposals — one ask. Team, because the whole major-gifts
// layer is (the BUILD-19/BUILD-20 split; a Core org sees the panel behind glass).
app.post("/donors/:id/proposals", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [donor] = await query("SELECT id, name, assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });

  // The money seam, never Number(): "$25,000.00" is how a person writes it.
  let askCents;
  try { askCents = parseMoneyOrThrow(req.body.askAmount !== undefined ? req.body.askAmount : req.body.targetAmount, "askAmount"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }

  const stage = String(req.body.stage || "identified").toLowerCase();
  const v = P.validateProposal({
    purpose: req.body.purpose !== undefined ? req.body.purpose : req.body.name,
    askCents, expectedClose: req.body.expectedClose, stage,
    probability: req.body.probability, declineReason: req.body.declineReason,
    declinedOn: req.body.declinedOn,
  }, { mode: "create" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_proposal", errors: v.errors });

  const fund = await checkProposalFund(orgId, req.body.fundId || null);
  if (!fund.ok) return res.status(404).json({ error: "Fund not found" });

  // Officer = the relationship owner (BUILD-30: assignment IS the portfolio),
  // falling back to whoever is typing. An officer id a caller names must belong
  // to this org.
  let officerId = donor.assigned_to, officerName = donor.assigned_to_name;
  if (req.body.officerId) {
    const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [req.body.officerId, orgId]);
    if (!u) return res.status(404).json({ error: "Officer not found" });
    officerId = u.id; officerName = u.name;
  }
  if (!officerId) { officerId = req.user.userId; officerName = (await query("SELECT name FROM users WHERE id=?", [req.user.userId]))[0]?.name || ""; }

  if (P.isOpenStage(stage)) {
    const clash = await openProposalConflict(orgId, donor.id, fund.fundId, null);
    if (clash) return res.status(409).json(clash);
  }

  const id = "opp_" + uuid().slice(0, 8);
  const status = P.statusForStage(stage);
  const prob = P.normalizeProbability(req.body.probability);
  // ONE statement, and the WHERE NOT EXISTS is the race guarantee: two officers
  // saving the same ask at the same second cannot both land. The unique index
  // would catch it too where it exists, but it does not exist on every org
  // (db.js says why), so the rule lives here.
  const ins = await query(
    `INSERT INTO opportunities
       (id,org_id,donor_id,name,target_amount,status,proposal_stage,probability,fund_id,notes,
        officer_id,officer_name,expected_close,created_by,created_by_name,updated_at)
     SELECT ?::text,?::text,?::text,?::text,?::numeric,?::text,?::text,?::integer,?::text,?::text,
            ?::text,?::text,?::date,?::text,?::text,NOW()
      WHERE NOT EXISTS (
        SELECT 1 FROM opportunities x WHERE x.org_id=?::text AND x.donor_id=?::text
          AND COALESCE(x.fund_id,'') = ?::text AND x.proposal_stage = ANY(?::text[]))
     RETURNING id`,
    [id, orgId, donor.id, P.sanitizePurpose(req.body.purpose !== undefined ? req.body.purpose : req.body.name),
     toDollars(askCents), status, stage, prob == null ? null : prob, fund.fundId,
     P.sanitizeNotes(req.body.notes), officerId, officerName || "", req.body.expectedClose,
     actor(req).id, actor(req).name,
     orgId, donor.id, fund.fundId || "", P.isOpenStage(stage) ? P.OPEN_STAGE_KEYS : []]);
  if (!ins.length) {
    const clash = await openProposalConflict(orgId, donor.id, fund.fundId, null);
    return res.status(409).json(clash || { code: "proposal_already_open", error: "There is already an open proposal for that fund." });
  }
  await logProposalLine(orgId, donor.id, req, `Proposal opened: ${P.sanitizePurpose(req.body.purpose !== undefined ? req.body.purpose : req.body.name)} — ${money.formatCentsPlain(askCents)}, ${P.stageLabel(stage)}`);
  const funds = await orgFundNames(orgId);
  const [row] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [id]);
  res.status(201).json(proposalRow(row, funds));
}));

// Every stage change is a line on the person's timeline, because "when did we
// ask, and what happened" has to be answerable from the record and not from
// somebody's memory of a screen.
async function logProposalLine(orgId, donorId, req, note) {
  // THE ORG'S CALENDAR, NOT THE PROCESS'S. `new Date().toISOString().slice(0,10)`
  // is a UTC day, so a proposal moved at 8pm Eastern would be stamped tomorrow
  // — and this row is what "when did we ask" reads off. Found by
  // tests/date-seam.test.js §5, which is what that scan is for.
  const org = await orgTz(orgId);
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,'proposal',?,?,?,?)`,
    ["int_" + uuid().slice(0, 10), orgId, donorId, orgToday(org), note,   // ORG_TZ_SEAM_OK
     actor(req).id, actor(req).name]).catch(e => console.error("[proposal] timeline:", e.message));
}

// PUT /proposals/:id — move it, edit it, or close it.
//
// THE THREE THINGS THIS ROUTE IS FOR:
//   · Committed writes a PLEDGE or a GIFT, never both. Whichever it writes is
//     linked on the row so the money is traceable to the ask, and the other
//     column stays null — a commitment counted twice is the BUILD-98 rule
//     ("a gift is counted once") wearing a different hat.
//   · Declined stores a reason from the list and the date, and does NOT reopen
//     silently: moving it back to an open stage needs `acknowledgeReopen`.
//   · `status` is never sent by a caller. It is derived from the stage, once,
//     by statusForStage — so the twenty BUILD-15/17/85/86 reads that filter on
//     it cannot disagree with what the screen shows.
app.put("/proposals/:id", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [existing] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!existing) return res.status(404).json({ error: "Proposal not found" });

  const patch = {}, sets = [], params = [];
  const put = (col, val) => { sets.push(`${col}=?`); params.push(val); };

  if (req.body.purpose !== undefined) { patch.purpose = req.body.purpose; }
  if (req.body.askAmount !== undefined || req.body.targetAmount !== undefined) {
    try { patch.askCents = parseMoneyOrThrow(req.body.askAmount !== undefined ? req.body.askAmount : req.body.targetAmount, "askAmount"); }
    catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  }
  if (req.body.expectedClose !== undefined) patch.expectedClose = req.body.expectedClose;
  if (req.body.probability !== undefined) patch.probability = req.body.probability;
  if (req.body.stage !== undefined) patch.stage = String(req.body.stage || "").toLowerCase();
  if (req.body.declineReason !== undefined) patch.declineReason = req.body.declineReason;
  if (req.body.declinedOn !== undefined) patch.declinedOn = req.body.declinedOn;
  if (req.body.commitKind !== undefined) patch.commitKind = req.body.commitKind;
  if (Object.keys(patch).length === 0 && req.body.notes === undefined && req.body.fundId === undefined
      && req.body.officerId === undefined) {
    return res.status(400).json({ error: "Nothing to update" });
  }

  const v = P.validateProposal(patch, { mode: "patch" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_proposal", errors: v.errors });

  const toStage = patch.stage || existing.proposal_stage;
  const reopen = P.declineReopenRefusal(existing.proposal_stage, toStage, { acknowledged: req.body.acknowledgeReopen === true });
  if (reopen) return res.status(409).json({ code: reopen.code, error: reopen.message });

  let fundId = existing.fund_id;
  if (req.body.fundId !== undefined) {
    const f = await checkProposalFund(orgId, req.body.fundId || null);
    if (!f.ok) return res.status(404).json({ error: "Fund not found" });
    fundId = f.fundId;
  }
  // Moving INTO an open stage, or onto a different fund while open, re-runs the
  // one-open-per-fund rule. Staying put does not — that would refuse a row
  // because of itself.
  if (P.isOpenStage(toStage)) {
    const clash = await openProposalConflict(orgId, existing.donor_id, fundId, existing.id);
    if (clash) return res.status(409).json(clash);
  }

  if (patch.purpose !== undefined) put("name", P.sanitizePurpose(patch.purpose));
  if (patch.askCents !== undefined) put("target_amount", toDollars(patch.askCents));
  if (patch.expectedClose !== undefined) put("expected_close", patch.expectedClose);
  if (patch.probability !== undefined) put("probability", P.normalizeProbability(patch.probability));
  if (req.body.notes !== undefined) put("notes", P.sanitizeNotes(req.body.notes));
  if (req.body.fundId !== undefined) put("fund_id", fundId);
  if (req.body.officerId !== undefined) {
    const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [req.body.officerId, orgId]);
    if (!u) return res.status(404).json({ error: "Officer not found" });
    put("officer_id", u.id); put("officer_name", u.name);
  }

  let wrote = null;
  if (patch.stage !== undefined && patch.stage !== existing.proposal_stage) {
    put("proposal_stage", patch.stage);
    put("status", P.statusForStage(patch.stage));          // DERIVED, never sent
    const askCents = patch.askCents !== undefined ? patch.askCents : (toCents(existing.target_amount) || 0);

    if (patch.stage === "declined") {
      put("decline_reason", req.body.declineReason);
      // The date a decline is RECORDED is the org's civil today, never UTC's —
      // a no at 8pm Eastern is today's no, and this date is on the record for
      // good (reopening keeps it).
      put("declined_on", req.body.declinedOn || orgToday(await orgTz(orgId)));   // ORG_TZ_SEAM_OK
      sets.push("closed_at=NOW()");
      put("gift_id", null); put("pledge_id", null); put("commit_kind", null);
    } else if (patch.stage === "committed" || patch.stage === "stewarding") {
      // EXACTLY ONE of the two doors, and the caller says which. A commitment
      // with no door named is a pledge: "they said yes" without money in hand
      // is a promise, which is what a pledge is for.
      const kind = P.COMMIT_KINDS.includes(String(req.body.commitKind)) ? String(req.body.commitKind) : P.COMMIT_PLEDGE;
      const already = existing.pledge_id || existing.gift_id;
      if (!already) {
        if (kind === P.COMMIT_GIFT) {
          if (!req.body.giftId) return res.status(400).json({ error: "Name the gift this proposal closed with, or record it as a pledge.", code: "gift_required" });
          const [g] = await query("SELECT id, amount FROM gifts WHERE id=? AND org_id=?", [req.body.giftId, orgId]);
          if (!g) return res.status(404).json({ error: "Gift not found" });
          put("gift_id", g.id); put("gift_amount", g.amount); put("pledge_id", null);
          put("commit_kind", P.COMMIT_GIFT);
          wrote = { kind: P.COMMIT_GIFT, id: g.id };
        } else {
          const committedCents = req.body.committedAmount !== undefined
            ? (() => { try { return parseMoneyOrThrow(req.body.committedAmount, "committedAmount"); } catch { return null; } })()
            : askCents;
          if (!(committedCents > 0)) return res.status(400).json({ error: "A positive committed amount is required." });
          const due = req.body.pledgeDueDate || existing.expected_close_civil || orgToday(await orgTz(orgId));   // ORG_TZ_SEAM_OK
          const pid = "pl_" + uuid().slice(0, 8);
          await run(
            `INSERT INTO pledges (id,org_id,donor_id,amount,due_date,status,notes,created_by,created_by_name)
             VALUES (?,?,?,?,?,'open',?,?,?)`,
            [pid, orgId, existing.donor_id, toDollars(committedCents), String(due).slice(0, 10),
             `Committed from the proposal: ${existing.name || "Ask"}`, actor(req).id, actor(req).name]);
          // THE ONE SCHEDULE WRITER (BUILD-88b). A frequency and a count give a
          // real schedule; neither given leaves one instalment for the whole
          // commitment, so the existing rule in recordGift applies her cheque to
          // it from any door, to the cent.
          await writePledgeInstallments(orgId, pid, {
            amountCents: committedCents, schedule: req.body.installments,
            frequency: req.body.frequency, count: req.body.installmentCount,
            firstDue: String(due).slice(0, 10),
          }).catch(e => console.error("[proposal] instalments:", e.message));
          const [n] = await query("SELECT COUNT(*)::int AS c FROM pledge_installments WHERE pledge_id=?", [pid]);
          if (!n.c) await run(`INSERT INTO pledge_installments (id,org_id,pledge_id,seq,due_date,amount) VALUES (?,?,?,1,?,?)`,
            ["pli_" + uuid().slice(0, 10), orgId, pid, String(due).slice(0, 10), toDollars(committedCents)]);
          put("pledge_id", pid); put("commit_kind", P.COMMIT_PLEDGE); put("gift_id", null); put("gift_amount", null);
          wrote = { kind: P.COMMIT_PLEDGE, id: pid };
        }
      }
      sets.push("closed_at=COALESCE(closed_at, NOW())");
    } else {
      // Back to an open stage: the close is undone, and whatever was written
      // stays written. A pledge is a commitment somebody made; reopening the
      // ask does not un-make it, and deleting it here would lose money.
      sets.push("closed_at=NULL");
    }
    await logProposalLine(orgId, existing.donor_id, req,
      `Proposal ${P.stageLabel(existing.proposal_stage)} → ${P.stageLabel(patch.stage)}: ${existing.name || "Ask"}`
      + (patch.stage === "declined" ? ` — ${P.declineReasonLabel(req.body.declineReason)}` : "")
      + (wrote ? ` — recorded as a ${wrote.kind}` : ""));
  }

  sets.push("updated_at=NOW()");
  params.push(req.params.id, orgId);
  await run(`UPDATE opportunities SET ${sets.join(",")} WHERE id=? AND org_id=?`, params);
  const funds = await orgFundNames(orgId);
  const [row] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [req.params.id]);
  res.json({ ...proposalRow(row, funds), wrote });
}));

app.delete("/proposals/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ success: true });
}));

// GET /proposals — the Proposals screen under Fundraising. Pipeline by stage in
// dollars and count, filter by officer and fund, sort by expected date.
// EVERY FIGURE CARRIES ITS SENTENCE, including the weighted total, which may
// not be rendered without one (shared/proposalShape.js says why).
app.get("/proposals", requireAuth, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const where = ["o.org_id = ?", "d.deleted_at IS NULL"], args = [orgId];
  if (req.query.officerId) { where.push("o.officer_id = ?"); args.push(String(req.query.officerId)); }
  if (req.query.fundId) { where.push("o.fund_id = ?"); args.push(String(req.query.fundId)); }
  if (req.query.stage) {
    const st = String(req.query.stage).split(",").map(s => s.trim().toLowerCase()).filter(s => P.STAGE_KEYS.includes(s));
    if (!st.length) return res.status(400).json({ error: "Unknown stage" });
    where.push("o.proposal_stage = ANY(?::text[])"); args.push(st);
  }
  if (req.query.open === "1") { where.push("o.proposal_stage = ANY(?::text[])"); args.push(P.OPEN_STAGE_KEYS); }
  const rows = await query(
    `SELECT o.*, to_char(o.expected_close,'YYYY-MM-DD') AS expected_close_civil, d.name AS donor_name FROM opportunities o
       JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
      WHERE ${where.join(" AND ")}`, args);
  const funds = await orgFundNames(orgId);
  const all = rows.map(r => proposalRow(r, funds));
  const sort = ["expected", "amount", "stage"].includes(String(req.query.sort)) ? String(req.query.sort) : "expected";
  const proposals = P.sortProposals(all, sort);
  const byStage = P.pipelineByStage(all).map(r => ({
    ...r, amount: toDollars(r.askCents), sentence: P.stageTileSentence(r, money.formatCentsPlain),
  }));
  const w = P.weightedTotal(all);
  const officers = await query(
    `SELECT id, name FROM users WHERE org_id=? ORDER BY name`, [orgId]).catch(() => []);
  res.json({
    proposals, byStage, sort,
    weighted: { cents: w.cents, amount: toDollars(w.cents), counted: w.counted, unset: w.unset,
                openCount: w.openCount, sentence: P.weightedSentence(w, money.formatCentsPlain) },
    openAsk: { cents: w.askCents, amount: toDollars(w.askCents),
               sentence: w.openCount === 0 ? "No open proposals yet."
                 : `${money.formatCentsPlain(w.askCents)} asked for across ${w.openCount} open ${w.openCount === 1 ? "proposal" : "proposals"} — the ask amounts, not what anybody expects to land.` },
    stages: P.PROPOSAL_STAGES, probabilities: P.PROBABILITIES, declineReasons: P.DECLINE_REASONS,
    funds: [...funds.entries()].map(([id, name]) => ({ id, name })),
    officers: officers.map(o => ({ id: o.id, name: o.name })),
  });
}));

// ── BUILD-99 (major gifts) Part 2 — PORTFOLIOS ─────────────────────────────
// `portfolioMembership` above is STILL the one definition of who is in a
// portfolio (BUILD-30, and it cost a build to settle). Nothing here forks it.
// What is new is what she puts AROUND that list: the order she reads it in, the
// target and count cap she typed, and who assigned each person to her.
async function portfolioMod() { return import("../shared/portfolioShape.js"); }

// The org's own word for "major prospect", in cents. A threshold Steward chose
// would be a claim about what a big gift is at an organisation it knows nothing
// about — so the DEFAULT is $1,000 and the answer is the org's.
async function majorProspectCents(orgId) {
  const [o] = await query("SELECT major_prospect_cents FROM orgs WHERE id=?", [orgId]);
  const v = o && o.major_prospect_cents != null ? Number(o.major_prospect_cents) : 100000;
  return Number.isFinite(v) && v > 0 ? Math.round(v) : 100000;
}

// The officer whose portfolio is being read, resolved against THIS org. A
// non-admin may only read their own (the BUILD-31 rule: cross-officer visibility
// is the oversight Team sells, and it is admin-only) — and they are DOWNGRADED
// to their own rather than refused, which is the precedent that route set.
async function resolvePortfolioOfficer(req, wanted) {
  const isAdmin = req.user.role === "admin";
  const want = String(wanted || "").trim();
  const id = (!isAdmin || !want || want === "me") ? req.user.userId : want;
  const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [id, req.user.orgId]);
  if (!u) return null;
  return { id: u.id, name: u.name, downgraded: !isAdmin && want && want !== req.user.userId };
}

// ROUTE ORDER IS PART OF THE CONTRACT: this is declared BEFORE
// `/portfolio/:officerId` or Express matches "unassigned-prospects" as an
// officer id and answers 404 for a screen that is not asking about an officer
// at all. (`/portfolio/officers` sits further up the file for the same reason.)
// GET /portfolio/unassigned-prospects — lifetime over the ORG's threshold, no
// owner. This is the list to assign FROM, which is the only reason it exists.
app.get("/portfolio/unassigned-prospects", requireAuth, wrap(async (req, res) => {
  const PF = await portfolioMod();
  const orgId = req.user.orgId;
  const thresholdCents = await majorProspectCents(orgId);
  const limit = Math.min(Number(req.query.limit) || 50, 200);
  const rows = await query(
    `SELECT id, name, email, kind, total_giving, gift_count, last_gift_date, stage, suggested_stage
       FROM donors
      WHERE org_id=? AND deleted_at IS NULL AND assigned_to IS NULL
        AND pending_assignee_invite_id IS NULL
        AND is_sample IS NOT TRUE AND COALESCE(deceased,false) = false
        AND round(COALESCE(total_giving,0)::numeric * 100) >= ?
      ORDER BY total_giving DESC NULLS LAST, id
      LIMIT ?`, [orgId, thresholdCents, limit]);
  const [c] = await query(
    `SELECT COUNT(*)::int AS n FROM donors
      WHERE org_id=? AND deleted_at IS NULL AND assigned_to IS NULL
        AND pending_assignee_invite_id IS NULL
        AND is_sample IS NOT TRUE AND COALESCE(deceased,false) = false
        AND round(COALESCE(total_giving,0)::numeric * 100) >= ?`, [orgId, thresholdCents]);
  res.json({
    thresholdCents, thresholdAmount: toDollars(thresholdCents),
    count: c.n, shown: rows.length,
    sentence: PF.unassignedSentence({ count: c.n, thresholdCents }, money.formatCentsPlain),
    prospects: rows.map(r => ({
      donorId: r.id, name: r.name, email: r.email, kind: r.kind || "person",
      lifetime: toDollars(toCents(r.total_giving) || 0), giftCount: Number(r.gift_count) || 0,
      lastGiftDate: r.last_gift_date || null, stage: r.stage || r.suggested_stage || null,
    })),
  });
}));

// GET /portfolio/:officerId — her people, in the order the brief asks for.
// ONE batch of reads (the BUILD-54 §1 pattern), never a query per person.
app.get("/portfolio/:officerId", requireAuth, wrap(async (req, res) => {
  const PF = await portfolioMod();
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const officer = await resolvePortfolioOfficer(req, req.params.officerId);
  if (!officer) return res.status(404).json({ error: "Officer not found" });

  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fy = orgPeriodBounds(org, "fiscal_year", 0);
  const fyYear = Number(String(fy.key).replace("fy:", ""));
  const today = orgToday(org);

  // THE MEMBERSHIP IS THE SHARED ONE. Read it, then decorate it.
  const m = portfolioMembership({ orgId, userId: officer.id, scope: "mine", assignedTo: officer.id, alias: "d" });
  const people = await query(
    `SELECT d.id, d.name, d.email, d.kind, d.stage, d.suggested_stage, d.total_giving,
            d.last_gift_date, d.last_gift_amount, d.assigned_by_name, d.assigned_at
       FROM donors d WHERE ${m.where} ORDER BY d.id`, m.params);
  const ids = people.map(p => p.id);

  const openAsk = new Map(), lastConv = new Map(), nextStep = new Map();
  if (ids.length) {
    for (const r of await query(
      `SELECT donor_id, COALESCE(SUM(target_amount),0) AS amt, COUNT(*)::int AS n
         FROM opportunities WHERE org_id=? AND donor_id = ANY(?) AND proposal_stage = ANY(?::text[])
        GROUP BY donor_id`, [orgId, ids, P.OPEN_STAGE_KEYS]))
      openAsk.set(r.donor_id, { cents: toCents(r.amt) || 0, count: r.n });
    // The LAST LOGGED CONVERSATION, which is a fact on the interactions table —
    // one row per donor via DISTINCT ON, not a correlated subquery per person.
    for (const r of await query(
      `SELECT DISTINCT ON (donor_id) donor_id, type, date, note, logged_by_name
         FROM interactions WHERE org_id=? AND donor_id = ANY(?)
          AND type = ANY(ARRAY['call','meeting','email','ask','note','stewardship','gift','event'])
        ORDER BY donor_id, date DESC, created_at DESC`, [orgId, ids]))
      lastConv.set(r.donor_id, { type: r.type, date: r.date, note: (r.note || "").slice(0, 220), by: r.logged_by_name || "" });
    // The NEXT STEP comes from the Thread (BUILD-81) — the one open one per
    // donor, which the partial unique index makes true by construction.
    for (const r of await query(
      `SELECT donor_id, next_step_label, next_step_type, due_date, due_time
         FROM threads WHERE org_id=? AND donor_id = ANY(?) AND closed_at IS NULL`, [orgId, ids]))
      nextStep.set(r.donor_id, { label: r.next_step_label, type: r.next_step_type, due: r.due_date, time: r.due_time });
  }

  const rows = people.map(p => {
    const lc = lastConv.get(p.id) || null;
    const days = lc && /^\d{4}-\d{2}-\d{2}$/.test(String(lc.date))
      ? Math.max(0, orgTime.daysBetween(String(lc.date), today)) : null;
    const ask = openAsk.get(p.id) || { cents: 0, count: 0 };
    return {
      donorId: p.id, name: p.name, email: p.email, kind: p.kind || "person",
      stage: p.stage || p.suggested_stage || null, placed: !!p.stage,
      lifetime: toDollars(toCents(p.total_giving) || 0),
      lifetimeCents: toCents(p.total_giving) || 0,
      openAskCents: ask.cents, openAskAmount: toDollars(ask.cents), openProposals: ask.count,
      daysSinceContact: days,
      contactPhrase: PF.contactPhrase(days), quiet: PF.isQuiet(days),
      lastConversation: lc, nextStep: nextStep.get(p.id) || null,
      assignedByName: p.assigned_by_name || null, assignedAt: p.assigned_at || null,
    };
  });
  const ranked = PF.rankPortfolio(rows);

  // Committed THIS FISCAL YEAR, against the target she typed. Committed, not
  // asked — a target is about money that landed.
  const [won] = await query(
    `SELECT COALESCE(SUM(COALESCE(gift_amount, target_amount)),0) AS amt, COUNT(*)::int AS n
       FROM opportunities WHERE org_id=? AND officer_id=? AND status='won'
        AND closed_at >= ?::date AND closed_at < (?::date + 1)`, [orgId, officer.id, fy.start, fy.end]);
  const [t] = await query("SELECT target_amount, count_cap FROM portfolio_targets WHERE org_id=? AND user_id=? AND fiscal_year=?",
    [orgId, officer.id, fyYear]);
  const prog = PF.targetProgress({
    targetCents: t && t.target_amount != null ? toCents(t.target_amount) : null,
    committedCents: toCents(won.amt) || 0,
    fiscalLabel: `FY ${fyYear}–${String(fyYear + 1).slice(2)}`,
  });
  const cap = PF.capState({ capCount: t ? t.count_cap : null, actualCount: ranked.length });

  res.json({
    officer: { id: officer.id, name: officer.name }, downgraded: !!officer.downgraded,
    fiscalYear: fyYear, fiscalLabel: prog.fiscalLabel,
    people: ranked,
    count: { value: ranked.length, sentence: PF.portfolioCountSentence(ranked.length, officer.name) },
    target: { ...prog, amount: prog.targetCents == null ? null : toDollars(prog.targetCents),
              committedAmount: toDollars(prog.committedCents), committedCount: won.n,
              sentence: PF.targetSentence(prog, money.formatCentsPlain) },
    cap: { ...cap, sentence: PF.capSentence(cap) },
  });
}));

// PUT /portfolio/:officerId/target — the target and the cap, both hers, both
// optional. Sending null CLEARS one, which is how "I have not decided" is said.
app.put("/portfolio/:officerId/target", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const isAdmin = req.user.role === "admin";
  const want = String(req.params.officerId || "").trim();
  // A staff member may set their OWN target and nobody else's; an admin may set
  // anyone's in this org. REFUSED rather than downgraded, because a WRITE
  // silently landing on a different row is worse than an error — and the first
  // cut of this collapsed `want` into the caller's own id BEFORE the check, so
  // the refusal could never fire and a staff member's attempt quietly wrote to
  // her own target instead. Found by this part's own suite.
  if (!isAdmin && want && want !== "me" && want !== req.user.userId) {
    return res.status(403).json({ error: "You can set your own target." });
  }
  const id = (!isAdmin || !want || want === "me") ? req.user.userId : want;
  const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [id, orgId]);
  if (!u) return res.status(404).json({ error: "Officer not found" });

  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fyYear = req.body.fiscalYear != null
    ? Number(req.body.fiscalYear)
    : Number(String(orgPeriodBounds(org, "fiscal_year", 0).key).replace("fy:", ""));
  if (!Number.isInteger(fyYear) || fyYear < 2000 || fyYear > 2100) return res.status(400).json({ error: "A fiscal year is required." });

  let targetCents = null;
  if (req.body.target !== undefined && req.body.target !== null && String(req.body.target).trim() !== "") {
    try { targetCents = parseMoneyOrThrow(req.body.target, "target"); }
    catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
    if (targetCents <= 0) return res.status(400).json({ error: "A target has to be a positive amount, or blank." });
  }
  let cap = null;
  if (req.body.countCap !== undefined && req.body.countCap !== null && String(req.body.countCap).trim() !== "") {
    cap = Number(req.body.countCap);
    if (!Number.isInteger(cap) || cap <= 0) return res.status(400).json({ error: "A count cap has to be a whole number, or blank." });
  }

  await run(
    `INSERT INTO portfolio_targets (id,org_id,user_id,fiscal_year,target_amount,count_cap,created_by,created_by_name,updated_at)
     VALUES (?,?,?,?,?,?,?,?,NOW())
     ON CONFLICT (org_id, user_id, fiscal_year) DO UPDATE
       SET target_amount=EXCLUDED.target_amount, count_cap=EXCLUDED.count_cap, updated_at=NOW()`,
    ["pt_" + uuid().slice(0, 10), orgId, id, fyYear,
     targetCents == null ? null : toDollars(targetCents), cap, actor(req).id, actor(req).name]);
  const [row] = await query("SELECT * FROM portfolio_targets WHERE org_id=? AND user_id=? AND fiscal_year=?", [orgId, id, fyYear]);
  res.json({
    officer: { id: u.id, name: u.name }, fiscalYear: fyYear,
    target: row.target_amount == null ? null : toDollars(toCents(row.target_amount) || 0),
    countCap: row.count_cap == null ? null : Number(row.count_cap),
  });
}));

// PUT /orgs/major-prospect-threshold — the org's own number, in its own money.
app.put("/orgs/major-prospect-threshold", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  let cents;
  try { cents = parseMoneyOrThrow(req.body.threshold, "threshold"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  if (!(cents > 0)) return res.status(400).json({ error: "A positive amount is required." });
  await run("UPDATE orgs SET major_prospect_cents=? WHERE id=?", [cents, req.user.orgId]);
  res.json({ thresholdCents: cents, thresholdAmount: toDollars(cents) });
}));

// ── BUILD-99 (major gifts) Part 3 — CULTIVATION PLANS ──────────────────────
// A plan is a sequence of BUILD-81 threads for one person, authored by the
// officer. It does NOT fork the Thread engine: each step, when its turn comes,
// is a thread, opened through `openThreadTx` like every other, and it closes
// through the paths that already exist. shared/planShape.js holds the rules.
//
// NOTHING IN A PLAN SENDS ANYTHING. There is no email field and no schedule that
// fires; every step is a human action that ends in a logged line. That is what
// keeps a four-step cultivation of a major donor from being a sequence.
async function planMod() { return import("../shared/planShape.js"); }

// THE CHAINING, IN ONE FUNCTION, CALLED FROM EVERY PLACE A THREAD CLOSES.
//
// It is idempotent and it SELF-HEALS, which is the property that matters here
// because production runs with background ticks off (NEEDS-JONATHAN §1) and
// there is no sweep to fall back on. If the next step cannot open — because the
// donor already has an open thread, which the conversation route legitimately
// creates from the officer's own next step — the step stays PENDING and the next
// close calls this again. So a plan can never be stalled by a race; it is only
// ever waiting, and `planSentence` says so out loud.
async function advanceCultivationPlan(orgId, donorId, { actorId, actorName, today } = {}) {
  const PL = await planMod();
  const [plan] = await query(
    "SELECT * FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'", [orgId, donorId]);
  if (!plan) return null;
  const steps = await query("SELECT * FROM cultivation_plan_steps WHERE plan_id=? ORDER BY seq", [plan.id]);

  // A step whose thread has closed is DONE. The thread's own close is the fact;
  // this only reads it back, so the two can never disagree about whether the
  // officer did the thing.
  const open = steps.find(s => s.status === "open");
  if (open && open.thread_id) {
    const [th] = await query("SELECT id, closed_at, close_kind FROM threads WHERE id=? AND org_id=?", [open.thread_id, orgId]);
    if (!th || th.closed_at) {
      await run("UPDATE cultivation_plan_steps SET status='done', closed_at=NOW(), closed_by=?, closed_by_name=? WHERE id=? AND status='open'",
        [actorId || null, actorName || null, open.id]);
      open.status = "done";
    }
  }
  if (steps.some(s => s.status === "open")) return plan.id;   // still working on one

  const nextSeq = PL.nextPendingSeq(steps);
  if (nextSeq == null) {
    // Every step is done or skipped — the plan is finished, and that is a fact
    // about the plan rather than an outcome anybody has to record.
    await run("UPDATE cultivation_plans SET status='done', closed_at=NOW() WHERE id=? AND status='active'", [plan.id]);
    return plan.id;
  }
  const step = steps.find(s => Number(s.seq) === Number(nextSeq));
  const opened = await withTransaction(async client => openThreadTx(client, {
    orgId, donorId,
    step: { type: step.step_type, label: step.label, due: step.due_date },
    openedOn: today || step.due_date,
    ownerId: plan.owner_id, ownerName: plan.owner_name,
    actorId: actorId || plan.created_by, actorName: actorName || plan.created_by_name,
  }));
  // `openThreadTx` returns null when the donor already has an open thread (the
  // ON CONFLICT is the arbiter, never a check-then-insert). The step waits.
  if (!opened) return plan.id;
  await run("UPDATE cultivation_plan_steps SET status='open', thread_id=? WHERE id=? AND status='pending'", [opened.id, step.id]);
  return plan.id;
}

// GET /cultivation-templates — the plans the organisation keeps.
app.get("/cultivation-templates", requireAuth, wrap(async (req, res) => {
  const PL = await planMod();
  const rows = await query(
    "SELECT * FROM cultivation_templates WHERE org_id=? AND archived_at IS NULL ORDER BY name", [req.user.orgId]);
  res.json({
    templates: rows.map(r => ({
      id: r.id, name: r.name, steps: Array.isArray(r.steps) ? r.steps : [],
      createdByName: r.created_by_name || "",
    })),
    stepTypes: PL.PLAN_STEP_TYPES, maxSteps: PL.MAX_STEPS,
  });
}));

app.post("/cultivation-templates", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const v = PL.validateTemplate({ name: req.body.name, steps: req.body.steps });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_template", errors: v.errors });
  const id = "ct_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO cultivation_templates (id,org_id,name,steps,created_by,created_by_name) VALUES (?,?,?,?,?,?)`,
    [id, req.user.orgId, v.name, JSON.stringify(v.steps), actor(req).id, actor(req).name]);
  const [row] = await query("SELECT * FROM cultivation_templates WHERE id=?", [id]);
  res.status(201).json({ id: row.id, name: row.name, steps: row.steps });
}));

app.put("/cultivation-templates/:id", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const [ex] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!ex) return res.status(404).json({ error: "Template not found" });
  const v = PL.validateTemplate({
    name: req.body.name !== undefined ? req.body.name : ex.name,
    steps: req.body.steps !== undefined ? req.body.steps : ex.steps,
  });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_template", errors: v.errors });
  await run("UPDATE cultivation_templates SET name=?, steps=?, updated_at=NOW() WHERE id=? AND org_id=?",
    [v.name, JSON.stringify(v.steps), req.params.id, req.user.orgId]);
  // EDITING A TEMPLATE DOES NOT REWRITE AN APPLIED PLAN. A plan copied its name
  // and its steps at apply time precisely so that what an officer is working
  // through cannot change under her.
  res.json({ id: req.params.id, name: v.name, steps: v.steps });
}));

app.delete("/cultivation-templates/:id", requireAuth, wrap(async (req, res) => {
  // ARCHIVED, not deleted: applied plans point at this id, and a plan whose
  // origin vanished is a record with a hole in it.
  const { changes } = await run("UPDATE cultivation_templates SET archived_at=NOW() WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ success: true, archived: true });
}));

// POST /donors/:id/plan — apply a template, dates offset from today.
app.post("/donors/:id/plan", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const orgId = req.user.orgId;
  const [donor] = await query("SELECT id, name, assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });
  const [tpl] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [req.body.templateId, orgId]);
  if (!tpl) return res.status(404).json({ error: "Template not found" });
  const v = PL.validateTemplate({ name: tpl.name, steps: tpl.steps });
  if (!v.ok) return res.status(400).json({ error: "That template is no longer valid: " + v.errors[0].message, code: "invalid_template" });

  const org = await orgTz(orgId);
  const today = orgToday(org);                                // ORG_TZ_SEAM_OK
  const steps = PL.planFromTemplate({ steps: v.steps, today }, orgTime.addDays);

  const planId = "cp_" + uuid().slice(0, 10);
  // ONE ACTIVE PLAN PER PERSON, decided by the partial unique index rather than
  // by a read-then-write — two officers applying a plan in the same second
  // cannot both land.
  const ins = await query(
    `INSERT INTO cultivation_plans (id,org_id,donor_id,template_id,template_name,applied_on,status,owner_id,owner_name,created_by,created_by_name)
     SELECT ?::text,?::text,?::text,?::text,?::text,?::text,'active',?::text,?::text,?::text,?::text
      WHERE NOT EXISTS (SELECT 1 FROM cultivation_plans x WHERE x.org_id=?::text AND x.donor_id=?::text AND x.status='active')
     RETURNING id`,
    [planId, orgId, donor.id, tpl.id, tpl.name, today,
     donor.assigned_to || req.user.userId, donor.assigned_to_name || actor(req).name,
     actor(req).id, actor(req).name, orgId, donor.id]);
  if (!ins.length) {
    const [cur] = await query("SELECT id, template_name FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'", [orgId, donor.id]);
    return res.status(409).json({ code: "plan_already_active", planId: cur?.id || null,
      error: `${donor.name} is already working through "${cur?.template_name || "a plan"}". Finish or stop that one first.` });
  }
  for (const s of steps) {
    await run(
      `INSERT INTO cultivation_plan_steps (id,org_id,plan_id,seq,step_type,label,due_date,status)
       VALUES (?,?,?,?,?,?,?,'pending')`,
      ["cs_" + uuid().slice(0, 10), orgId, planId, s.seq, s.type, s.label, s.dueDate]);
  }
  // The first step opens now — or waits, if this person already has an open
  // follow-up of their own. Both are correct; the sentence says which.
  await advanceCultivationPlan(orgId, donor.id, { actorId: actor(req).id, actorName: actor(req).name, today });
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,'note',?,?,?,?)`,
    ["int_" + uuid().slice(0, 10), orgId, donor.id, today,
     `Cultivation plan applied: ${tpl.name} (${steps.length} ${steps.length === 1 ? "step" : "steps"})`,
     actor(req).id, actor(req).name]).catch(e => console.error("[plan] timeline:", e.message));
  res.status(201).json(await readPlan(orgId, planId));
}));

// The one reader, so the screen and the suite see the same shape.
async function readPlan(orgId, planId) {
  const PL = await planMod();
  const [plan] = await query("SELECT * FROM cultivation_plans WHERE id=? AND org_id=?", [planId, orgId]);
  if (!plan) return null;
  const steps = await query("SELECT * FROM cultivation_plan_steps WHERE plan_id=? ORDER BY seq", [planId]);
  const shaped = steps.map(s => ({
    id: s.id, seq: Number(s.seq), type: s.step_type, label: s.label,
    dueDate: s.due_date, status: s.status, threadId: s.thread_id || null,
    closedByName: s.closed_by_name || null, closedAt: s.closed_at || null,
  }));
  const prog = PL.planProgress(shaped);
  return {
    id: plan.id, donorId: plan.donor_id, templateId: plan.template_id, templateName: plan.template_name,
    appliedOn: plan.applied_on, status: plan.status,
    ownerName: plan.owner_name || "", appliedByName: plan.created_by_name || "",
    steps: shaped, progress: prog, sentence: PL.planSentence(prog, plan.template_name),
  };
}

// GET /donors/:id/plan — the plan on this person, active or the last one.
app.get("/donors/:id/plan", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const [p] = await query(
    `SELECT id FROM cultivation_plans WHERE org_id=? AND donor_id=?
      ORDER BY (status='active') DESC, created_at DESC LIMIT 1`, [req.user.orgId, req.params.id]);
  if (!p) return res.json({ plan: null });
  res.json({ plan: await readPlan(req.user.orgId, p.id) });
}));

// POST /plan-steps/:id/skip — skipping is RECORDED as skipped, never deleted and
// never quietly marked done. "We decided not to do that" is the fact.
app.post("/plan-steps/:id/skip", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [s] = await query(
    `SELECT st.*, p.donor_id, p.status AS plan_status FROM cultivation_plan_steps st
       JOIN cultivation_plans p ON p.id = st.plan_id
      WHERE st.id=? AND st.org_id=?`, [req.params.id, orgId]);
  if (!s) return res.status(404).json({ error: "Step not found" });
  if (s.status === "done" || s.status === "skipped") return res.status(409).json({ error: "That step is already closed." });
  // Skipping the OPEN step dismisses its thread with a reason — a thread may
  // not close without one (the BUILD-81 CHECK constraint), and "we decided not
  // to" is exactly the kind of reason that rule exists to preserve.
  if (s.status === "open" && s.thread_id) {
    await run("UPDATE threads SET closed_at=NOW(), close_kind='dismissed', close_reason='handled_outside' WHERE id=? AND org_id=? AND closed_at IS NULL",
      [s.thread_id, orgId]);
  }
  await run("UPDATE cultivation_plan_steps SET status='skipped', closed_at=NOW(), closed_by=?, closed_by_name=? WHERE id=? AND org_id=?",
    [actor(req).id, actor(req).name, req.params.id, orgId]);
  await advanceCultivationPlan(orgId, s.donor_id, { actorId: actor(req).id, actorName: actor(req).name });
  const out = await readPlan(orgId, s.plan_id);
  res.json({ plan: out, skipped: req.params.id });
}));

// POST /plans/:id/stop — the officer decides the plan is over. The steps keep
// what they were, so "we got three steps in and stopped" stays readable.
app.post("/plans/:id/stop", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [p] = await query("SELECT * FROM cultivation_plans WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!p) return res.status(404).json({ error: "Plan not found" });
  if (p.status !== "active") return res.status(409).json({ error: "That plan is not active." });
  const [open] = await query("SELECT id, thread_id FROM cultivation_plan_steps WHERE plan_id=? AND status='open'", [p.id]);
  if (open && open.thread_id) {
    await run("UPDATE threads SET closed_at=NOW(), close_kind='dismissed', close_reason='handled_outside' WHERE id=? AND org_id=? AND closed_at IS NULL",
      [open.thread_id, orgId]);
    await run("UPDATE cultivation_plan_steps SET status='skipped', closed_at=NOW(), closed_by=?, closed_by_name=? WHERE id=?",
      [actor(req).id, actor(req).name, open.id]);
  }
  await run("UPDATE cultivation_plans SET status='abandoned', closed_at=NOW() WHERE id=? AND org_id=?", [p.id, orgId]);
  res.json({ plan: await readPlan(orgId, p.id) });
}));

// ── BUILD-99 (major gifts) Part 4 — THE PROSPECT BRIEF ─────────────────────
// "Brief me" on a person: one page an officer reads in the car, written from the
// organisation's own rows, every sentence citing one.
//
// THE GUARANTEE IS THE SCHEMA, NOT THE PROMPT. shared/briefShape.js has no
// numeric field anywhere in it, so a model that wanted to assert a capacity has
// nowhere to put it; every figure on the finished page is rendered HERE from the
// rows. A prompt is a request; this is the absence of a place to say it.
async function briefShapeMod() { return import("../shared/briefShape.js"); }

// WHAT THE MODEL IS HANDED, AND NOTHING ELSE. Each row goes over as a line with
// a `kind:id` reference, and Steward keeps the same reference set to validate the
// citations against — so a cited row it never saw cannot survive.
async function briefRowsFor(orgId, donorId) {
  const P = await proposalMod();
  const V = await import("../shared/vocabulary.js");
  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const t = V.makeT(org && org.vocabulary_json);
  const [donor] = await query(
    `SELECT id, name, email, kind, stage, suggested_stage, total_giving, gift_count, first_gift_date,
            last_gift_date, last_gift_amount, notes, assigned_to_name, household_id, deceased, do_not_contact
       FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL`, [donorId, orgId]);
  if (!donor) return null;

  const refs = new Set([`person:${donor.id}`]);
  const lines = [];
  const money = require("../money");
  const givingWord = t("giver_singular") || "donor";

  lines.push(`person:${donor.id} — ${donor.name}${donor.kind === "organisation" ? " (an organisation)" : ""}, `
    + `${money.formatCentsPlain(toCents(donor.total_giving) || 0)} given in total across ${Number(donor.gift_count) || 0} gifts, `
    + `first on ${donor.first_gift_date || "no recorded date"}, most recently on ${donor.last_gift_date || "no recorded date"}`
    + `${donor.stage ? `, at the stage "${donor.stage}"` : ""}. This organisation calls somebody like this a ${givingWord}.`);

  // GIFTS — the last twelve, each its own row, with its fund and how it came in.
  const gifts = await query(
    `SELECT g.id, g.amount, g.date, g.type, g.payment_method, g.campaign, f.name AS fund_name
       FROM gifts g LEFT JOIN fin_funds f ON f.id = g.fund_id AND f.org_id = g.org_id
      WHERE g.org_id=? AND g.donor_id=? AND g.is_sample IS NOT TRUE
      ORDER BY g.date DESC, g.id LIMIT 12`, [orgId, donorId]);
  for (const g of gifts) {
    refs.add(`gift:${g.id}`);
    lines.push(`gift:${g.id} — ${money.formatCentsPlain(toCents(g.amount) || 0)} on ${g.date}`
      + `${g.fund_name ? ` to ${t("fund_singular") || "fund"} "${g.fund_name}"` : ""}`
      + `${g.campaign ? `, appeal "${g.campaign}"` : ""}${g.payment_method ? `, by ${g.payment_method}` : ""}.`);
  }

  // PLEDGES — a promise is not money, and the brief must not read it as one.
  for (const p of await query(
    `SELECT id, amount, due_date, status FROM pledges WHERE org_id=? AND donor_id=? ORDER BY due_date DESC LIMIT 6`, [orgId, donorId])) {
    refs.add(`pledge:${p.id}`);
    lines.push(`pledge:${p.id} — a pledge of ${money.formatCentsPlain(toCents(p.amount) || 0)} due ${p.due_date}, currently ${p.status}. A pledge is a promise, not money received.`);
  }

  // HOUSEHOLD AND RELATED PEOPLE.
  if (donor.household_id) {
    const [h] = await query("SELECT id, name FROM households WHERE id=? AND org_id=?", [donor.household_id, orgId]);
    if (h) {
      refs.add(`household:${h.id}`);
      const members = await query("SELECT name FROM donors WHERE org_id=? AND household_id=? AND id<>? AND deleted_at IS NULL", [orgId, h.id, donorId]);
      lines.push(`household:${h.id} — in the household "${h.name}"${members.length ? `, with ${members.map(m => m.name).join(" and ")}` : ""}.`);
    }
  }
  // SOFT CREDITS (BUILD-98 Part 1) — gifts that were somebody else's money.
  for (const sc of await query(
    `SELECT sc.id, sc.role, g.id AS gift_id, g.amount, g.date, d.name AS giver
       FROM gift_soft_credits sc
       JOIN gifts g ON g.id = sc.gift_id AND g.org_id = sc.org_id
       JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
      WHERE sc.org_id=? AND sc.donor_id=? ORDER BY g.date DESC LIMIT 6`, [orgId, donorId]).catch(() => [])) {
    refs.add(`softcredit:${sc.id}`);
    lines.push(`softcredit:${sc.id} — soft-credited for ${money.formatCentsPlain(toCents(sc.amount) || 0)} given by ${sc.giver} on ${sc.date}`
      + `${sc.role ? ` as ${sc.role}` : ""}. The money was ${sc.giver}'s; this is recognition, not their own giving.`);
  }

  // THE OPEN PROPOSAL.
  for (const o of await query(
    `SELECT o.id, o.name, o.target_amount, o.proposal_stage, o.probability, o.notes, f.name AS fund_name,
            to_char(o.expected_close,'YYYY-MM-DD') AS expected_close_civil
       FROM opportunities o LEFT JOIN fin_funds f ON f.id = o.fund_id AND f.org_id = o.org_id
      WHERE o.org_id=? AND o.donor_id=? AND o.proposal_stage = ANY(?::text[])
      ORDER BY o.expected_close NULLS LAST LIMIT 3`, [orgId, donorId, P.OPEN_STAGE_KEYS])) {
    refs.add(`proposal:${o.id}`);
    lines.push(`proposal:${o.id} — an open ask of ${money.formatCentsPlain(toCents(o.target_amount) || 0)} for "${o.name}"`
      + `${o.fund_name ? ` (${o.fund_name})` : ""}, at stage "${P.stageLabel(o.proposal_stage)}"`
      + `${o.probability != null ? `, which the officer put at ${o.probability} per cent` : ", with no probability set"}`
      + `${o.expected_close_civil ? `, expected to close ${o.expected_close_civil}` : ""}`
      + `${o.notes ? `. The officer's note on it: "${String(o.notes).slice(0, 400)}"` : "."}`);
  }

  // THE LAST FIVE CONVERSATIONS, QUOTED.
  for (const i of await query(
    `SELECT id, type, date, note, logged_by_name FROM interactions
      WHERE org_id=? AND donor_id=? AND type = ANY(ARRAY['call','meeting','email','ask','note','stewardship'])
        AND COALESCE(note,'') <> '' ORDER BY date DESC, created_at DESC LIMIT 5`, [orgId, donorId])) {
    refs.add(`conversation:${i.id}`);
    lines.push(`conversation:${i.id} — ${i.type} on ${i.date}${i.logged_by_name ? ` logged by ${i.logged_by_name}` : ""}: "${String(i.note).slice(0, 500)}"`);
  }

  // THE PLAN'S NEXT STEP.
  const [plan] = await query("SELECT id, template_name FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'", [orgId, donorId]);
  if (plan) {
    refs.add(`plan:${plan.id}`);
    const [openStep] = await query("SELECT seq, label, due_date FROM cultivation_plan_steps WHERE plan_id=? AND status='open'", [plan.id]);
    const [nextStep] = await query("SELECT seq, label, due_date FROM cultivation_plan_steps WHERE plan_id=? AND status='pending' ORDER BY seq LIMIT 1", [plan.id]);
    const s = openStep || nextStep;
    lines.push(`plan:${plan.id} — on the cultivation plan "${plan.template_name}"`
      + (s ? `; ${openStep ? "the open step" : "the next step"} is "${s.label}", due ${s.due_date}.` : "; every step is closed."));
  }

  // WHAT THE OFFICER WROTE.
  if (String(donor.notes || "").trim()) {
    refs.add(`note:${donor.id}`);
    lines.push(`note:${donor.id} — the note on their record reads: "${String(donor.notes).slice(0, 1200)}"`);
  }

  // The grounded numeric set: every figure that genuinely appears in the rows,
  // so `ungroundedClaims` can tell a fact from an invented rule.
  // THE MONEY SEAM, not Math.round — `tests/money-cents.test.js` is right that a
  // bare `Math.round(Number(x))` on a dollars value is the banned shape wherever
  // it appears, and "it is only feeding a text check" is not an exemption: the
  // next person to copy this line will not be feeding a text check.
  const grounded = [];
  for (const g of gifts) { const c = toCents(g.amount); if (c != null) grounded.push(toDollars(c), c); }
  grounded.push(Number(donor.gift_count) || 0);
  { const c = toCents(donor.total_giving); if (c != null) grounded.push(toDollars(c), c); }
  for (const l of lines) for (const m of String(l).matchAll(/\d+(?:\.\d+)?/g)) grounded.push(Number(m[0]));

  return { donor, org, t, refs, lines, grounded: [...new Set(grounded)], giftCount: gifts.length };
}

// GET /donors/:id/brief-rows — EXACTLY what the model would be handed, and
// nothing else. This is not a test seam: the brief's promise is that every line
// rests on a row you can open, and this is that list. It also means the row
// gathering — which is Steward's code, not a model's — is provable with no key
// configured at all.
app.get("/donors/:id/brief-rows", requireAuth, requirePlan("team"), wrap(async (req, res) => {
  const ctx = await briefRowsFor(req.user.orgId, req.params.id);
  if (!ctx) return res.status(404).json({ error: "Donor not found" });
  res.json({
    donorId: ctx.donor.id, donorName: ctx.donor.name,
    refs: [...ctx.refs], lines: ctx.lines, groundedValues: ctx.grounded,
  });
}));

// POST /donors/:id/brief — write it, validate it, log it as an agent run.
app.post("/donors/:id/brief", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const TH = await thresholdsMod();
  const orgId = req.user.orgId;
  // THE DONOR IS CHECKED FIRST, AND THAT ORDER IS THE POINT. The gate below
  // answers 503 when no key is configured, and running it first meant a probe
  // with ANOTHER ORG's donor id got 503 instead of 404 — breaking "404 is the one
  // answer" for a cross-tenant read and telling the caller both that the route
  // exists and what Steward's key state is. Found by tenant-matrix §3.
  const ctx = await briefRowsFor(orgId, req.params.id);
  if (!ctx) return res.status(404).json({ error: "Donor not found" });

  const gate = await agentGate(orgId);
  // THE ABSENCE HAS A NAME. No key configured is Steward's state, not the org's,
  // and the honest answer is that the control is unavailable — never a 500 and
  // never an invented brief.
  if (!gate.ok) return res.status(503).json({ error: "brief_unavailable", reason: gate.reason });

  const runId = "arun_" + uuid().slice(0, 10);
  await run(`INSERT INTO agent_runs (id,org_id,status,plan,read_summary) VALUES (?,?,?,?,?)`,
    [runId, orgId, "running", JSON.stringify({ kind: "prospect_brief", donorId: ctx.donor.id }),
     `${ctx.refs.size} rows on ${ctx.donor.name}`]);

  const system = [
    "You are writing a one-page brief for a fundraiser who is about to go and see somebody.",
    "",
    "You are given ROWS from this organisation's own records. Each row starts with a reference of the form kind:id.",
    "Write short, plain sentences about what those rows say. Every sentence must cite the references it rests on, exactly as given.",
    "",
    "RULES, and the first one is the whole job:",
    "- You may say NOTHING about this person that is not in the rows. No capacity, no wealth, no means, no guess about what they could give.",
    "- Use no figure that is not in the rows you were handed. Never state a rule about how giving works (no 'donors who give twice usually…').",
    "- A pledge is a promise, not money received. A soft credit is recognition, not their own giving. Say so if you mention them.",
    "- Quote a conversation rather than summarising away the words the officer chose.",
    "- Leave a section out if the rows say nothing about it. Do not pad.",
    "- Use this organisation's own vocabulary where the rows give it.",
    "- The headline names who this is and why she is reading it, and contains no figure.",
  ].join("\n");
  const user = [`The rows, on ${ctx.donor.name}:`, "", ...ctx.lines, "", "Write the brief."].join("\n");

  let raw = null, err = null;
  try {
    const client = new Anthropic();
    const msg = await client.messages.create({
      model: AGENT_MODEL, max_tokens: 2000, system,
      tools: [{ name: "brief", description: "The one-page brief she reads in the car.", strict: true, input_schema: B.BRIEF_SCHEMA }],
      tool_choice: { type: "tool", name: "brief" },
      messages: [{ role: "user", content: user }],
    });
    raw = (msg.content || []).find(b => b.type === "tool_use" && b.name === "brief")?.input || null;
  } catch (e) { err = e.message || String(e); }

  if (!raw) {
    await run("UPDATE agent_runs SET status='failed', finished_at=NOW(), error=? WHERE id=?", [err || "no brief returned", runId]);
    return res.status(502).json({ error: "The brief could not be written just now.", runId });
  }

  const checked = B.validateBrief(raw, {
    rows: ctx.refs,
    ungrounded: (text, opts) => TH.ungroundedClaims(text, opts),
    groundedValues: ctx.grounded,
  });
  await run(
    `UPDATE agent_runs SET status='done', finished_at=NOW(), actions=?, declined=?, withheld=?, withheld_reason=? WHERE id=?`,
    [JSON.stringify({ brief: checked, donorId: ctx.donor.id }), checked.dropped.length, checked.dropped.length,
     checked.dropped.length ? B.droppedSentence(checked.dropped) : null, runId]);

  res.json({
    runId, donorId: ctx.donor.id, donorName: ctx.donor.name,
    headline: checked.headline, sections: checked.sections,
    dropped: checked.dropped, droppedSentence: B.droppedSentence(checked.dropped),
    rowsRead: ctx.refs.size, footer: B.BRIEF_FOOTER,
  });
}));

// GET /briefs/:runId — read one back. It is an agent run, so it is on the
// Activity screen with everything else the agent did.
app.get("/briefs/:runId", requireAuth, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const [r] = await query("SELECT * FROM agent_runs WHERE id=? AND org_id=?", [req.params.runId, req.user.orgId]);
  if (!r || !r.actions || !r.actions.brief) return res.status(404).json({ error: "Brief not found" });
  const [d] = await query("SELECT id, name FROM donors WHERE id=? AND org_id=?", [r.actions.donorId, req.user.orgId]);
  res.json({
    runId: r.id, donorId: r.actions.donorId, donorName: d ? d.name : "",
    ...r.actions.brief, droppedSentence: B.droppedSentence(r.actions.brief.dropped || []),
    writtenAt: r.finished_at, rowsRead: r.read_summary, footer: B.BRIEF_FOOTER,
  });
}));

// GET /briefs/:runId/pdf — the page she prints for the car, on the org's
// letterhead, through the same renderer discipline the acknowledgment letters use.
app.get("/briefs/:runId/pdf", requireAuth, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const [r] = await query("SELECT * FROM agent_runs WHERE id=? AND org_id=?", [req.params.runId, req.user.orgId]);
  if (!r || !r.actions || !r.actions.brief) return res.status(404).json({ error: "Brief not found" });
  const [org] = await query("SELECT name, legal_name, receipt_address, brand_accent, logo_data FROM orgs WHERE id=?", [req.user.orgId]);
  const [d] = await query("SELECT name FROM donors WHERE id=? AND org_id=?", [r.actions.donorId, req.user.orgId]);
  const pdf = await renderBriefPdf({
    org: { display: org.legal_name || org.name, receipt_address: org.receipt_address,
           brand_accent: org.brand_accent, logo_data: org.logo_data },
    donorName: d ? d.name : "",
    brief: r.actions.brief,
    footer: B.BRIEF_FOOTER,
    droppedSentence: B.droppedSentence(r.actions.brief.dropped || []),
    sectionTitle: B.sectionTitle,
  });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="brief-${(d ? d.name : "prospect").replace(/[^A-Za-z0-9]+/g, "-").toLowerCase()}.pdf"`);
  res.send(pdf);
}));

// ONE page, the org's letterhead, and the footer that says what this is. The
// letterhead block is deliberately the same shape as renderLettersPdf's (BUILD-98
// Part 2) rather than a second idea about where an org's name goes.
function renderBriefPdf({ org, donorName, brief, footer, droppedSentence, sectionTitle }) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margins: { top: 50, bottom: 46, left: 72, right: 72 }, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    const INK = "#0f1a12", SUB = "#5a554f";
    const accent = org.brand_accent || "#0d5c3a";
    let logo = null;
    if (org.logo_data && /^data:image\/(png|jpe?g);base64,/.test(org.logo_data)) {
      try { logo = Buffer.from(org.logo_data.split(",")[1], "base64"); } catch { logo = null; }
    }
    doc.addPage();
    const PW = doc.page.width;
    doc.rect(0, 0, PW, 6).fill(accent);
    if (logo) { try { doc.image(logo, PW - 72 - 60, 22, { fit: [60, 44] }); } catch { /* a logo that will not draw costs the logo, not the page */ } }
    doc.font("Helvetica-Bold").fontSize(13).fillColor(INK).text(org.display || "", 72, 26, { width: PW - 220, lineBreak: false });
    if (org.receipt_address) doc.font("Helvetica").fontSize(8.5).fillColor(SUB).text(org.receipt_address, 72, 44, { width: PW - 220 });

    let y = 92;
    doc.font("Times-Bold").fontSize(19).fillColor(INK).text(donorName || "Prospect brief", 72, y, { width: PW - 144 });
    y = doc.y + 4;
    if (brief.headline) {
      doc.font("Times-Italic").fontSize(11.5).fillColor(SUB).text(brief.headline, 72, y, { width: PW - 144 });
      y = doc.y + 10;
    }
    const bottom = doc.page.height - 84;
    for (const sec of (brief.sections || [])) {
      if (y > bottom - 40) break;                 // held to ONE page, never spilled
      doc.font("Helvetica-Bold").fontSize(9).fillColor(accent)
        .text(String(sectionTitle(sec.key) || sec.key).toUpperCase(), 72, y, { width: PW - 144, characterSpacing: 0.8 });
      y = doc.y + 4;
      for (const s of sec.sentences) {
        if (y > bottom - 14) break;
        doc.font("Times-Roman").fontSize(10.5).fillColor(INK)
          .text(s.text, 72, y, { width: PW - 144, lineGap: 2, height: bottom - y, ellipsis: true });
        y = doc.y + 3;
      }
      y += 7;
    }
    let fy = doc.page.height - 74;
    if (droppedSentence) {
      doc.font("Helvetica").fontSize(8).fillColor(SUB).text(droppedSentence, 72, fy, { width: PW - 144, height: 12 });
      fy += 12;
    }
    doc.font("Helvetica").fontSize(8).fillColor(SUB).text(footer, 72, fy, { width: PW - 144, height: 26 });
    doc.end();
  });
}

// ── BUILD-99 (major gifts) Part 5 — THE MAJOR-GIFTS DASHBOARD ──────────────
// Five things a development director asks. shared/majorGiftsDash.js holds the
// definitions, ONE STRING each, and nothing on this screen may appear without
// one — the BUILD-86 C.3 rule, applied again because the reason has not changed.
//
// NO GOAL IS INVENTED. The only target here is the one she typed in Part 2.
async function mgDashMod() { return import("../shared/majorGiftsDash.js"); }

app.get("/major-gifts/dashboard", requireAuth, wrap(async (req, res) => {
  const MG = await mgDashMod();
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fy = orgPeriodBounds(org, "fiscal_year", 0);
  const fyYear = Number(String(fy.key).replace("fy:", ""));
  const qtr = orgPeriodBounds(org, "quarter", 0);
  const mon = orgPeriodBounds(org, "month", 0);
  const today = orgToday(org);

  // ONE BATCH OF READS, not a query per tile (the BUILD-54 §1 pattern). Every
  // figure below is summed in the database over exactly the rows it names.
  const [pipeline, dueQ, askedY, committedY, convs, backlog, officers, counts] = await Promise.all([
    // Pipeline by stage, over the whole org's open proposals.
    query(`SELECT o.proposal_stage AS stage, COUNT(*)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt,
                  COALESCE(SUM(CASE WHEN o.probability IS NOT NULL
                                    THEN round(o.target_amount::numeric * 100) * o.probability / 100 END),0) AS weighted_cents,
                  COUNT(o.probability)::int AS with_prob
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL
            GROUP BY o.proposal_stage`, [orgId]),
    query(`SELECT COUNT(*)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL AND o.proposal_stage = ANY(?::text[])
              AND o.expected_close >= ?::date AND o.expected_close <= ?::date`,
      [orgId, P.OPEN_STAGE_KEYS, qtr.start, qtr.end]),
    // ASKED THIS YEAR is about reaching the stage, so it reads the stage-change
    // line the proposal routes write — `created_at` would count a proposal
    // opened in July as an ask made in July, which it is not.
    query(`SELECT COUNT(DISTINCT o.id)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL
              AND o.proposal_stage IN ('asked','committed','declined','stewarding')
              AND COALESCE(o.updated_at, o.created_at) >= ?::date
              AND COALESCE(o.updated_at, o.created_at) < (?::date + 1)`, [orgId, fy.start, fy.end]),
    query(`SELECT COUNT(*)::int AS n, COALESCE(SUM(COALESCE(o.gift_amount, o.target_amount)),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL AND o.status='won'
              AND o.closed_at >= ?::date AND o.closed_at < (?::date + 1)`, [orgId, fy.start, fy.end]),
    // Conversations logged THIS MONTH, per officer, from who logged them.
    query(`SELECT COALESCE(NULLIF(i.logged_by_name,''),'(not recorded)') AS who, COUNT(*)::int AS n
             FROM interactions i JOIN donors d ON d.id = i.donor_id AND d.org_id = i.org_id
            WHERE i.org_id=? AND d.deleted_at IS NULL AND i.is_sample IS NOT TRUE
              AND i.type = ANY(ARRAY['call','meeting','email','ask','stewardship'])
              AND i.date >= ? AND i.date <= ?
            GROUP BY 1 ORDER BY 2 DESC`, [orgId, mon.start, mon.end]),
    // Thread backlog per officer — open follow-ups on their own people, with the
    // overdue ones counted separately. A snoozed thread is not backlog.
    query(`SELECT COALESCE(NULLIF(t.owner_name,''), COALESCE(NULLIF(d.assigned_to_name,''),'(nobody)')) AS who,
                  COUNT(*)::int AS open_n,
                  COUNT(*) FILTER (WHERE t.due_date < ?)::int AS overdue_n
             FROM threads t JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
            WHERE t.org_id=? AND t.closed_at IS NULL AND d.deleted_at IS NULL
              AND (t.snoozed_until IS NULL OR t.snoozed_until <= ?)
            GROUP BY 1 ORDER BY 2 DESC`, [today, orgId, today]),
    query("SELECT COUNT(*)::int AS n FROM users WHERE org_id=?", [orgId]),
    query(`SELECT COUNT(*)::int AS n FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL`, [orgId]),
  ]);

  const byStage = P.PROPOSAL_STAGES.map(s => {
    const r = pipeline.find(x => x.stage === s.key);
    const askCents = r ? (toCents(r.amt) || 0) : 0;
    return { stage: s.key, label: s.label, kind: s.kind, count: r ? r.n : 0,
             askCents, amount: toDollars(askCents),
             sentence: P.stageTileSentence({ stage: s.key, label: s.label, count: r ? r.n : 0, askCents }, money.formatCentsPlain) };
  });
  const openRows = pipeline.filter(r => P.OPEN_STAGE_KEYS.includes(r.stage));
  const openCents = openRows.reduce((s, r) => s + (toCents(r.amt) || 0), 0);
  const weightedCents = openRows.reduce((s, r) => s + Math.round(Number(r.weighted_cents) || 0), 0);
  const withProb = openRows.reduce((s, r) => s + (Number(r.with_prob) || 0), 0);
  const openCount = openRows.reduce((s, r) => s + (Number(r.n) || 0), 0);

  const askedCents = toCents(askedY[0].amt) || 0;
  const committedCents = toCents(committedY[0].amt) || 0;

  const tile = (id, value) => ({
    id, label: MG.metric(id).label, value,
    definition: MG.definitionFor(id),
    sentence: MG.tileSentence(id, value, money.formatCentsPlain),
  });

  res.json({
    fiscalYear: fyYear, fiscalLabel: `FY ${fyYear}–${String(fyYear + 1).slice(2)}`,
    quarter: { start: qtr.start, end: qtr.end },
    month: { start: mon.start, end: mon.end },
    proposalCount: counts[0].n,
    empty: MG.emptySentence({ proposalCount: counts[0].n, officerCount: officers[0].n }),
    byStage,
    tiles: {
      pipeline: { ...tile("pipeline", openCents), amount: toDollars(openCents), count: openCount },
      weighted: { ...tile("weighted", weightedCents), amount: toDollars(weightedCents), counted: withProb,
                  unset: openCount - withProb,
                  sentence: P.weightedSentence({ cents: weightedCents, counted: withProb, unset: openCount - withProb,
                                                 openCount, askCents: openCents }, money.formatCentsPlain) },
      dueThisQuarter: { ...tile("dueThisQuarter", dueQ[0].n), amount: toDollars(toCents(dueQ[0].amt) || 0) },
      askedThisYear: { ...tile("askedThisYear", askedCents), amount: toDollars(askedCents), count: askedY[0].n },
      committedThisYear: { ...tile("committedThisYear", committedCents), amount: toDollars(committedCents), count: committedY[0].n },
    },
    askedVsCommitted: MG.askedVsCommitted({ askedCents, committedCents }, money.formatCentsPlain),
    officerActivity: {
      definition: MG.definitionFor("conversationsThisMonth"),
      rows: convs.map(r => ({ officerName: r.who, conversations: r.n })),
    },
    threadBacklog: {
      definition: MG.definitionFor("threadBacklog"),
      rows: backlog.map(r => ({ officerName: r.who, open: r.open_n, overdue: r.overdue_n })),
    },
    metrics: MG.METRICS,
  });
}));

// GET /pipeline/officer-activity — per-officer moves/asks/gifts over a period.
// The raw data BUILD-17's per-officer reports read; just recorded cleanly here.
app.get("/pipeline/officer-activity", requireAuth, wrap(async (req, res) => {
  const { orgId } = req.user;
  const from = req.query.from || new Date(Date.now() - 90 * 86400000).toISOString().slice(0, 10);
  const to = req.query.to || new Date().toISOString().slice(0, 10);
  const officers = await query("SELECT id, name, portfolio_color FROM users WHERE org_id=? ORDER BY name", [orgId]);
  const moves = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt FROM moves WHERE org_id=? AND created_at >= ? AND created_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const asks = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt, COALESCE(SUM(target_amount),0) AS amt FROM opportunities WHERE org_id=? AND created_at >= ? AND created_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const won = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt, COALESCE(SUM(gift_amount),0) AS amt FROM opportunities WHERE org_id=? AND status='won' AND closed_at >= ? AND closed_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const mv = Object.fromEntries(moves.map(r => [r.officer_id, r.cnt]));
  const ak = Object.fromEntries(asks.map(r => [r.officer_id, r]));
  const wn = Object.fromEntries(won.map(r => [r.officer_id, r]));
  res.json({
    from, to,
    officers: officers.map(o => ({
      officerId: o.id, name: o.name, color: o.portfolio_color,
      movesMade: mv[o.id] || 0,
      asksMade: ak[o.id]?.cnt || 0, asksAmount: parseFloat(ak[o.id]?.amt) || 0,
      giftsClosed: wn[o.id]?.cnt || 0, giftsAmount: parseFloat(wn[o.id]?.amt) || 0,
    })),
  });
}));

// ── Donor-to-donor relationships (household/spouse/family/employer_match) ──
// Manual linking only — no auto-detection (matching last name, address,
// etc.) in this pass, see CLAUDE.md. One row per pair regardless of which
// donor is A vs B; both directions are queried here so either donor's
// profile shows the same link.
const DONOR_RELATIONSHIP_TYPES = ["spouse", "household", "family", "employer_match"];
// Only these two types pool into a shared "household total" — family and
// employer_match are relationship context, not a shared giving pool.
const HOUSEHOLD_RELATIONSHIP_TYPES = ["spouse", "household"];

app.get("/donors/:id/relationships", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" }); // BUILD-75 B: the parent must be YOURS before children are answered — even an empty list confirms nothing about another tenant
  const { orgId } = req.user;
  const donorId = req.params.id;
  const rows = await query(
    `SELECT dr.id, dr.relationship_type, dr.notes, dr.created_at,
            CASE WHEN dr.donor_id_a = ? THEN dr.donor_id_b ELSE dr.donor_id_a END AS related_donor_id
     FROM donor_relationships dr
     WHERE dr.org_id = ? AND (dr.donor_id_a = ? OR dr.donor_id_b = ?)
     ORDER BY dr.created_at ASC`,
    [donorId, orgId, donorId, donorId]
  );
  if (!rows.length) return res.json({ relationships: [], householdTotal: null });

  const relatedIds = rows.map(r => r.related_donor_id);
  const relatedDonors = await query(
    `SELECT id, name, total_giving FROM donors WHERE org_id = ? AND id = ANY(?)`,
    [orgId, relatedIds]
  );
  const donorMap = Object.fromEntries(relatedDonors.map(d => [d.id, d]));

  const relationships = rows.map(r => ({
    id: r.id,
    relationshipType: r.relationship_type,
    notes: r.notes,
    relatedDonorId: r.related_donor_id,
    relatedDonorName: donorMap[r.related_donor_id]?.name || "(deleted donor)",
    relatedDonorTotalGiving: Number(donorMap[r.related_donor_id]?.total_giving) || 0,
  }));

  let householdTotal = null;
  const householdLinks = relationships.filter(r => HOUSEHOLD_RELATIONSHIP_TYPES.includes(r.relationshipType));
  if (householdLinks.length) {
    const selfRow = await query("SELECT total_giving FROM donors WHERE id = ? AND org_id = ?", [donorId, orgId]);
    const selfTotal = Number(selfRow[0]?.total_giving) || 0;
    householdTotal = selfTotal + householdLinks.reduce((sum, r) => sum + r.relatedDonorTotalGiving, 0);
  }

  res.json({ relationships, householdTotal });
}));

app.post("/donors/:id/relationships", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId } = req.user;
  const donorId = req.params.id;
  const { relatedDonorId, relationshipType, notes } = req.body;
  if (!relatedDonorId || !DONOR_RELATIONSHIP_TYPES.includes(relationshipType)) {
    return res.status(400).json({ error: "relatedDonorId and a valid relationshipType are required" });
  }
  if (relatedDonorId === donorId) return res.status(400).json({ error: "A donor can't be linked to themselves" });

  const bothRows = await query(
    "SELECT id FROM donors WHERE org_id = ? AND id IN (?, ?) AND deleted_at IS NULL",
    [orgId, donorId, relatedDonorId]
  );
  if (bothRows.length < 2) return res.status(404).json({ error: "Donor not found" });

  // Order-agnostic dedup — a link already stored as (B,A) shouldn't allow a
  // second (A,B) row for the same pair.
  const existing = await query(
    `SELECT id FROM donor_relationships WHERE org_id = ?
       AND ((donor_id_a = ? AND donor_id_b = ?) OR (donor_id_a = ? AND donor_id_b = ?))`,
    [orgId, donorId, relatedDonorId, relatedDonorId, donorId]
  );
  if (existing.length) return res.status(409).json({ error: "These donors are already linked" });

  const id = "drel_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO donor_relationships (id, org_id, donor_id_a, donor_id_b, relationship_type, notes) VALUES (?,?,?,?,?,?)",
    [id, orgId, donorId, relatedDonorId, relationshipType, notes || null]
  );
  res.status(201).json({ id });
}));

app.delete("/donor-relationships/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM donor_relationships WHERE id = ? AND org_id = ?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  res.json({ success: true });
}));

// Wealth/capacity scoring is part of the Team major-gifts layer — Core sees a
// stored score read-only (behind glass) but can't compute/recompute it.
app.post("/donors/:id/score", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const result = await calcWealthScore(req.params.id, req.user.orgId);
  if (!result) return res.status(404).json({ error: "Donor not found" });
  res.json(result);
}));

app.get("/donors/:id/fund-affinity", requireAuth, wrap(async (req, res) => {
  const { orgId } = req.user;
  const donorCheck = await query("SELECT * FROM donors WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!donorCheck.length) return res.status(404).json({ error: "Donor not found" });
  const totalGiving = donorCheck[0].total_giving || 0;

  // Gifts with a fund_id
  const fundGifts = await query(
    `SELECT g.fund_id, COALESCE(f.name,'Unknown Fund') as fund_name,
            COALESCE(f.restricted,false) as restricted,
            COUNT(*) as gift_count, SUM(g.amount) as total,
            MAX(g.date) as last_date
     FROM gifts g
     LEFT JOIN fin_funds f ON f.id=g.fund_id
     WHERE g.donor_id=? AND g.org_id=? AND g.fund_id IS NOT NULL AND g.fund_id != ''
     GROUP BY g.fund_id, f.name, f.restricted
     ORDER BY total DESC`,
    [req.params.id, orgId]
  );

  // Unrestricted (no fund_id)
  const unrestrictedGifts = await query(
    `SELECT COALESCE(SUM(amount),0) as total, COUNT(*) as gift_count FROM gifts WHERE donor_id=? AND org_id=? AND (fund_id IS NULL OR fund_id='')`,
    [req.params.id, orgId]
  );
  const unrestrictedTotal = parseFloat(unrestrictedGifts[0]?.total || 0);
  const restrictedTotal = fundGifts.filter(f => f.restricted).reduce((s, f) => s + parseFloat(f.total), 0);

  // Active fin_funds for suggested asks
  const activeFunds = await query("SELECT id, name FROM fin_funds WHERE org_id=? ORDER BY name ASC", [orgId]);

  const affinityRows = fundGifts.map(f => ({
    fundId: f.fund_id,
    fundName: f.fund_name,
    restricted: f.restricted,
    total: parseFloat(f.total),
    giftCount: parseInt(f.gift_count),
    lastDate: f.last_date,
    pct: totalGiving > 0 ? Math.round(parseFloat(f.total) / totalGiving * 100) : 0,
  }));

  res.json({
    affinity: affinityRows,
    unrestrictedTotal,
    restrictedTotal,
    totalGiving,
    activeFunds,
  });
}));

// ── Grants ─────────────────────────────────────────────────────────────────
// Optional ?search= (lower LIKE on funder/program) + ?limit= for the top-bar
// global search; no params → unchanged full list (plain array either way).
app.get("/grants", requireAuth, wrap(async (req, res) => {
  const where = ["org_id = ?"];
  const params = [req.user.orgId];
  if (req.query.search && String(req.query.search).trim()) {
    const s = "%" + String(req.query.search).trim().toLowerCase() + "%";
    where.push("(lower(funder) LIKE ? OR lower(program) LIKE ?)");
    params.push(s, s);
  }
  let sql = `SELECT * FROM grants WHERE ${where.join(" AND ")} ORDER BY deadline ASC`;
  const limit = parseInt(req.query.limit, 10);
  if (limit > 0) { sql += " LIMIT ?"; params.push(Math.min(limit, 50)); }
  const grants = await query(sql, params);
  res.json(grants.map(g => ({ ...g, history: JSON.parse(g.history || "[]") })));
}));

// Finance entity-routing FIX (2026-08-04) — the ONE grant-award → ledger stamp.
// source='grant' (badged in the unified ledger), grant_id + the partial-unique
// uq_fin_txns_grant (db.js) make it idempotent BY CONSTRUCTION: re-award after
// un-award, a redundant awarded→awarded PUT, or a manual row already adopted as
// this grant's stamp (grant_id taken) can never double-insert. Fund matching is
// the original BUILD-09 heuristic (funder/program-named fund, else the first
// unrestricted fund).
async function stampGrantAward(orgId, grantId, funder, program, amount, by = SYS_AUTO) {
  const matchFund = await query(
    "SELECT id FROM fin_funds WHERE org_id=? AND (name ILIKE ? OR name ILIKE ?) LIMIT 1",
    [orgId, `%${funder}%`, `%${program || ""}%`]
  );
  // BUILD-58 W-3: the award stamp resolves its accounts through the ONE
  // ledger helper (grants revenue account, contributions fallback) — a
  // chartless org is provisioned loudly, never a null-account booking.
  const ledgerA = await ensureOrgLedger(orgId, { heal: true });
  const fundId = matchFund[0]?.id || ledgerA.genFundId;
  await run(
    `INSERT INTO fin_transactions (id,org_id,date,description,vendor_donor,amount,type,account_id,fund_id,grant_id,source,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,'income',?,?,?,'grant',?,?)
     ON CONFLICT (grant_id) WHERE grant_id IS NOT NULL DO NOTHING`,
    ["ft_" + uuid().slice(0, 8), orgId, orgToday(await orgTz(orgId)), // ORG_TZ_SEAM_OK (BUILD-75)
     `Grant awarded: ${funder} — ${program || ""}`, funder,
     parseFloat(amount) || 0, ledgerA.grantAcctId, fundId, grantId, by.id, by.name]
  ).catch(e => console.error("[ledger] grant award stamp failed:", e.message));
}

app.post("/grants", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { funder, program, amount, status, deadline, reportDue, officer, notes } = req.body;
  const campaignId = req.body.campaignId || req.body.campaign_id || null;
  if (!funder) return res.status(400).json({ error: "Funder required" });

  // Attribution FIX — optional campaign link (org-scoped; foreign → 404).
  // The awarded amount counts toward the linked campaign's raised once the
  // grant is AWARDED (awarded_at) — general-operating grants stay unattributed.
  if (campaignId) {
    const camp = await query("SELECT id FROM campaigns WHERE id=? AND org_id=?", [campaignId, req.user.orgId]);
    if (!camp.length) return res.status(404).json({ error: "Campaign not found" });
  }

  const id = "gr_" + uuid().slice(0, 8);
  const isAwarded = (status || "prospecting") === "awarded";
  await run(
    "INSERT INTO grants (id,org_id,funder,program,amount,status,deadline,report_due,officer,notes,campaign_id,awarded_at,created_by,created_by_name) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, funder, program || "", amount || 0,
     status || "prospecting", deadline || "", reportDue || "", officer || "", notes || "",
     campaignId, isAwarded ? new Date().toISOString() : null, actor(req).id, actor(req).name]
  );
  // A grant created directly IN 'awarded' books its income too (this path
  // previously never stamped the ledger — only the PUT transition did).
  if (isAwarded) await stampGrantAward(req.user.orgId, id, funder, program, amount, actor(req));
  const rows = await query("SELECT * FROM grants WHERE id = ?", [id]);
  res.status(201).json(rows[0]);
}));

app.put("/grants/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { funder, program, amount, received, status, deadline, reportDue, officer, notes, description, requirements, adoptTxnId } = req.body;
  if (!funder) return res.status(400).json({ error: "Funder required" });
  const orgId = req.user.orgId;

  // Capture previous status/attribution before update
  const prevRows = await query("SELECT status, campaign_id, awarded_at FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!prevRows.length) return res.status(404).json({ error: "Grant not found" });
  const prevStatus = prevRows[0]?.status;

  // Finance entity-routing FIX — the award-side double-count guard's "link,
  // don't double-book" arm. `adoptTxnId` names an EXISTING manual money-in row
  // (org-scoped, source='manual', type='income', not already a grant's stamp)
  // that IS this award's money: instead of inserting a second income row, that
  // row becomes the award stamp (grant_id set, source→'grant'). Validated up
  // front so a foreign/wrong-shaped id 404s before any state changes — never
  // silently double-books.
  if (adoptTxnId !== undefined && adoptTxnId !== null && adoptTxnId !== "") {
    if (status !== "awarded") return res.status(400).json({ error: "adoptTxnId only applies when marking a grant awarded" });
    const adoptRows = await query(
      "SELECT id FROM fin_transactions WHERE id=? AND org_id=? AND source='manual' AND type='income' AND grant_id IS NULL",
      [adoptTxnId, orgId]
    );
    if (!adoptRows.length) return res.status(404).json({ error: "Transaction not found or not adoptable" });
  }

  // Attribution FIX — set / change / clear (campaignId:"" → NULL), org-scoped.
  const campaignIdRaw = req.body.campaignId !== undefined ? req.body.campaignId
    : req.body.campaign_id !== undefined ? req.body.campaign_id : undefined;
  let newCampaignId = prevRows[0]?.campaign_id || null;
  if (campaignIdRaw !== undefined) {
    if (campaignIdRaw) {
      const camp = await query("SELECT id FROM campaigns WHERE id=? AND org_id=?", [campaignIdRaw, orgId]);
      if (!camp.length) return res.status(404).json({ error: "Campaign not found" });
      newCampaignId = campaignIdRaw;
    } else {
      newCampaignId = null;
    }
  }

  // awarded_at is the attribution fact (see db.js): stamped entering
  // 'awarded' (the same moment as the ledger income stamp below), kept while
  // the grant moves through active/closed, cleared if it moves BACK to a
  // still-pursuing or rejected status (an un-award — the thermometer reverses).
  let newAwardedAt = prevRows[0]?.awarded_at || null;
  if (status === "awarded" && prevStatus !== "awarded" && !newAwardedAt) newAwardedAt = new Date().toISOString();
  if (["prospecting", "loi", "applied", "submitted", "draft", "pending", "rejected"].includes(status)) newAwardedAt = null;

  const affected = await run(
    `UPDATE grants
     SET funder=?,program=?,amount=?,received=?,status=?,deadline=?,report_due=?,officer=?,notes=?,description=?,requirements=?,campaign_id=?,awarded_at=?,updated_at=NOW()
     WHERE id=? AND org_id=?`,
    [funder, program || "", amount || 0, received || 0, status, deadline || "",
     reportDue || "", officer || "", notes || "", description || "", requirements || "",
     newCampaignId, newAwardedAt,
     req.params.id, orgId]
  );
  if (!affected.changes) return res.status(404).json({ error: "Grant not found" });

  // Grant awarded → the ledger income books EXACTLY ONCE (uq_fin_txns_grant).
  // Either by adopting the caller-named manual row as the stamp (the money was
  // already logged — link it, don't double-book) or by inserting the auto
  // stamp. Adoption keeps the treasurer's own date/fund/account and re-badges
  // the row source='grant'.
  if (status === 'awarded' && prevStatus !== 'awarded') {
    let adopted = false;
    if (adoptTxnId) {
      // Adoption keeps source='manual' (it stays the treasurer's own entry —
      // un-award UNLINKS it rather than deleting user-entered data); grant_id
      // is what marks it as the award's single ledger booking.
      const upd = await run(
        `UPDATE fin_transactions SET grant_id=?
         WHERE id=? AND org_id=? AND source='manual' AND type='income' AND grant_id IS NULL`,
        [req.params.id, adoptTxnId, orgId]
      ).catch(() => ({ changes: 0 }));
      adopted = !!upd.changes;
      if (adopted) writeAuditLog(orgId, req.user.userId, req.user.email, "updated", "transaction", adoptTxnId, {
        description: `Linked existing manual income to grant award: ${funder} — ${program || ""} (books once, not twice)`,
        new: { grant_id: req.params.id },
      }).catch(() => {});
    }
    if (!adopted) await stampGrantAward(orgId, req.params.id, funder, program, amount, actor(req));
  }

  // Un-award (awarded_at cleared — the grant moved BACK to a pursuing or
  // rejected status): the income reverses out of the ledger too, same
  // discipline as a voided/refunded gift removing its stamp. The AUTO stamp
  // (source='grant') is deleted; an ADOPTED manual row is unlinked back to a
  // plain manual entry (never delete treasurer-entered data on a status move).
  if (newAwardedAt === null && prevRows[0]?.awarded_at) {
    await run("DELETE FROM fin_transactions WHERE org_id=? AND grant_id=? AND source='grant'", [orgId, req.params.id]).catch(() => {});
    await run("UPDATE fin_transactions SET grant_id=NULL WHERE org_id=? AND grant_id=?", [orgId, req.params.id]).catch(() => {});
  }

  // Grant closed/rejected → follow-up task in 6 months
  if ((status === 'closed' || status === 'rejected') && prevStatus !== status) {
    const sixMonths = new Date(Date.now() + 180*24*60*60*1000).toISOString().slice(0, 10);
    await run(
      "INSERT INTO tasks (id,org_id,title,priority,done,due,created_by,created_by_name) VALUES (?,?,?,'medium',0,?,?,?)",
      ["t_"+uuid().slice(0,8), orgId, `Follow up with ${funder} re: next cycle`, sixMonths, actor(req).id, actor(req).name]
    ).catch(() => {});
  }

  const rows = await query("SELECT * FROM grants WHERE id = ?", [req.params.id]);
  const g = rows[0];
  g.history = JSON.parse(g.history || "[]");
  res.json(g);
}));

// Finance entity-routing FIX — award-side double-count guard, the DETECTION
// arm. Before marking a grant awarded, the client asks: is there a recent
// MANUAL money-in already in the ledger that looks like this grant's money
// (funder name in vendor/description, or the exact grant amount)? Read-only,
// org-scoped (foreign grant → 404); the human decides via the prompt whether
// to link (PUT adoptTxnId) or book separately. 180-day window, newest first.

// ── BUILD-100 (grants) Part 1 — FUNDERS AND GRANTS ─────────────────────────
// A funder is an ORGANISATION on file (BUILD-80's `kind`), not a string in a
// column, and a grant is one request to one of them. shared/grantShape.js holds
// every rule; these routes are its writers. The existing `grants` table gains
// the columns rather than being replaced — db.js says why.
async function grantShapeMod() { return import("../shared/grantShape.js"); }

// The wire shape. Money leaves as dollars AND as integer cents, because the
// pipeline is summed in cents and a screen that re-derives cents from a float is
// how a total ends up a penny out.
function grantRow(r, { funds, officers } = {}) {
  const reqC = toCents(r.amount_requested != null ? r.amount_requested : r.amount) || 0;
  const awdC = toCents(r.amount_awarded) || 0;
  const recC = toCents(r.received) || 0;
  return {
    id: r.id,
    funderId: r.funder_donor_id || null,
    funderName: r.funder_name || r.funder || "",
    funderType: r.funder_type || null,
    program: r.program || "",
    amountRequested: toDollars(reqC), amountRequestedCents: reqC,
    amountAwarded: awdC ? toDollars(awdC) : null, amountAwardedCents: awdC,
    received: toDollars(recC), receivedCents: recC,
    status: r.status_canonical || r.status,
    restriction: r.restriction || null,
    restrictedFrom: r.restricted_from || null,
    restrictedUntil: r.restricted_until || null,
    fundId: r.fund_id || null,
    fundName: r.fund_id && funds ? (funds.get(r.fund_id) || null) : null,
    cycleName: r.cycle_name || null,
    officerId: r.officer_id || null,
    officerName: r.officer_id && officers ? (officers.get(r.officer_id) || null) : (r.officer || ""),
    awardPledgeId: r.award_pledge_id || null,
    declineReason: r.decline_reason || null,
    declinedOn: r.declined_on || null,
    reapply: r.reapply === null || r.reapply === undefined ? null : !!r.reapply,
    deadline: r.deadline || null,
    reportDue: r.report_due || null,
    notes: r.notes || "",
    createdByName: r.created_by_name || "",
    awardedAt: r.awarded_at || null,
  };
}

async function orgFundNamesG(orgId) {
  const rows = await query("SELECT id, name FROM fin_funds WHERE org_id=?", [orgId]);
  return new Map(rows.map(r => [r.id, r.name]));
}
async function orgOfficerNames(orgId) {
  const rows = await query("SELECT id, name FROM users WHERE org_id=?", [orgId]);
  return new Map(rows.map(r => [r.id, r.name]));
}

// THE ONE PLACE A FUNDER IS RESOLVED, and the one place a person is refused.
// A grant is an institutional relationship; a cheque from a private individual
// is a GIFT. Calling it a grant puts it in the wrong half of every report an
// auditor reads, which is why this is a refusal and not a warning.
async function resolveFunder(orgId, funderDonorId) {
  const G = await grantShapeMod();
  const [d] = await query(
    "SELECT id, name, kind, funder_type, funder_ein FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [funderDonorId, orgId]);
  const problem = G.funderProblem(d);
  if (problem) return { ok: false, problem };
  return { ok: true, funder: d };
}

// GET /funders — the organisations this org has asked, with what they have
// given and what is open. A funder with no grants yet is still a funder.
app.get("/funders", requireAuth, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const orgId = req.user.orgId;
  const rows = await query(
    `SELECT d.id, d.name, d.funder_type, d.email, d.city, d.state, d.total_giving,
            COUNT(g.id)::int AS grant_count,
            COALESCE(SUM(CASE WHEN g.status = ANY(?::text[]) THEN COALESCE(g.amount_requested, g.amount) END),0) AS open_requested,
            COALESCE(SUM(CASE WHEN g.status='awarded' THEN COALESCE(g.amount_awarded, g.amount) END),0) AS awarded_total
       FROM donors d
       LEFT JOIN grants g ON g.funder_donor_id = d.id AND g.org_id = d.org_id AND g.is_sample IS NOT TRUE
      WHERE d.org_id=? AND d.deleted_at IS NULL AND LOWER(COALESCE(d.kind,'person')) IN ('organisation','organization')
        AND (d.funder_type IS NOT NULL OR g.id IS NOT NULL)
      GROUP BY d.id, d.name, d.funder_type, d.email, d.city, d.state, d.total_giving
      ORDER BY d.name`,
    [G.OPEN_STATUS_KEYS.concat(Object.keys(G.STATUS_ALIASES).filter(a => G.STATUS_ALIASES[a] && G.OPEN_STATUS_KEYS.includes(G.STATUS_ALIASES[a]))), orgId]);
  res.json({
    funders: rows.map(r => ({
      funderId: r.id, name: r.name, funderType: r.funder_type || null,
      funderTypeLabel: G.funderTypeLabel(r.funder_type), email: r.email || null,
      city: r.city || null, state: r.state || null,
      grantCount: r.grant_count,
      openRequested: toDollars(toCents(r.open_requested) || 0),
      awardedTotal: toDollars(toCents(r.awarded_total) || 0),
      lifetimeGiving: toDollars(toCents(r.total_giving) || 0),
    })),
    funderTypes: G.FUNDER_TYPES,
  });
}));

// PUT /funders/:donorId — say what kind of funder an organisation is. It lives
// on the FUNDER because the Sunrise Foundation is a private foundation across
// every grant it ever makes; per-grant storage would let two rows disagree.
app.put("/funders/:donorId", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const r = await resolveFunder(req.user.orgId, req.params.donorId);
  if (!r.ok) {
    const code = r.problem.code === "funder_not_found" ? 404 : 400;
    return res.status(code).json({ error: r.problem.message, code: r.problem.code });
  }
  // BUILD-100 Part 6 FIX — an ABSENT funderType leaves it alone. The first cut
  // read `String(req.body.funderType || "")` whether the key was there or not,
  // so a body carrying only an EIN was refused for a bad funder type: a route
  // that cannot be called with one field is not a route somebody can use.
  const hasType = Object.prototype.hasOwnProperty.call(req.body, "funderType");
  const t = !hasType ? undefined
    : (req.body.funderType === null || req.body.funderType === "" ? null : String(req.body.funderType));
  if (t !== undefined && t !== null && !G.FUNDER_TYPE_KEYS.includes(t)) {
    return res.status(400).json({ error: `Funder type must be one of: ${G.FUNDER_TYPES.map(x => x.label).join(", ")}.`, code: "bad_funder_type" });
  }
  // BUILD-100 Part 6 — the EIN, if they have it. Nine digits or nothing: a
  // half-typed tax id that still matched on a prefix would be worse than none.
  const I = await grantImportMod();
  let ein;
  if (Object.prototype.hasOwnProperty.call(req.body, "ein")) {
    const raw = req.body.ein;
    if (raw === null || String(raw).trim() === "") ein = null;
    else {
      ein = I.normalizeEin(raw);
      if (!ein) return res.status(400).json({ code: "bad_ein",
        error: "An EIN is nine digits, written 12-3456789. Leave it blank if you do not have it." });
    }
  }
  if (t !== undefined) {
    await run("UPDATE donors SET funder_type=?, updated_at=NOW() WHERE id=? AND org_id=?", [t, r.funder.id, req.user.orgId]);
  }
  if (ein !== undefined) {
    // The partial unique index is the arbiter: two records claiming one EIN is a
    // duplicate to merge, and the route says so rather than swallowing 23505.
    try {
      await run("UPDATE donors SET funder_ein=?, updated_at=NOW() WHERE id=? AND org_id=?", [ein, r.funder.id, req.user.orgId]);
    } catch (e) {
      if (String(e.code) === "23505") {
        const [dup] = await query("SELECT name FROM donors WHERE org_id=? AND funder_ein=? AND deleted_at IS NULL",
          [req.user.orgId, ein]);
        return res.status(409).json({ code: "ein_already_on_file",
          error: `${(dup && dup.name) || "Another record"} already carries that EIN. If they are the same funder, merge the two records.` });
      }
      throw e;
    }
  }
  const [after] = await query("SELECT funder_type, funder_ein FROM donors WHERE id=? AND org_id=?", [r.funder.id, req.user.orgId]);
  const type = (after && after.funder_type) || null;
  res.json({ funderId: r.funder.id, name: r.funder.name, funderType: type, funderTypeLabel: G.funderTypeLabel(type),
             ein: (after && after.funder_ein) || null });
}));

// GET /funders/:donorId/grants — a funder's own record: every grant, in order.
app.get("/funders/:donorId/grants", requireAuth, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const r = await resolveFunder(req.user.orgId, req.params.donorId);
  if (!r.ok) {
    const code = r.problem.code === "funder_not_found" ? 404 : 400;
    return res.status(code).json({ error: r.problem.message, code: r.problem.code });
  }
  const funds = await orgFundNamesG(req.user.orgId);
  const officers = await orgOfficerNames(req.user.orgId);
  const rows = await query(
    `SELECT g.*, d.name AS funder_name, d.funder_type
       FROM grants g JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
      WHERE g.org_id=? AND g.funder_donor_id=? ORDER BY g.created_at DESC`,
    [req.user.orgId, r.funder.id]);
  const grants = rows.map(x => grantRow({ ...x, status_canonical: G.normalizeStatus(x.status) }, { funds, officers }));
  res.json({
    funder: { funderId: r.funder.id, name: r.funder.name, funderType: r.funder.funder_type || null,
              funderTypeLabel: G.funderTypeLabel(r.funder.funder_type), ein: r.funder.funder_ein || null },
    grants,
    statuses: G.GRANT_STATUSES, restrictions: G.RESTRICTIONS, declineReasons: G.DECLINE_REASONS,
  });
}));

// POST /funders/:donorId/grants — one request to one funder.
app.post("/funders/:donorId/grants", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const orgId = req.user.orgId;
  const fr = await resolveFunder(orgId, req.params.donorId);
  if (!fr.ok) {
    const code = fr.problem.code === "funder_not_found" ? 404 : 400;
    return res.status(code).json({ error: fr.problem.message, code: fr.problem.code });
  }
  let reqCents;
  try { reqCents = parseMoneyOrThrow(req.body.amountRequested, "amountRequested"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }

  const status = G.normalizeStatus(req.body.status || "researching") || String(req.body.status || "");
  const v = G.validateGrant({
    program: req.body.program, amountRequestedCents: reqCents, status,
    restriction: req.body.restriction, restrictedFrom: req.body.restrictedFrom,
    restrictedUntil: req.body.restrictedUntil,
  }, { mode: "create" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_grant", errors: v.errors });

  const fund = await checkGrantFund(orgId, req.body.fundId || null);
  if (!fund.ok) return res.status(404).json({ error: "Fund not found" });
  const officer = await checkGrantOfficer(orgId, req.body.officerId || null);
  if (!officer.ok) return res.status(404).json({ error: "Officer not found" });

  const id = "gr_" + uuid().slice(0, 8);
  await run(
    `INSERT INTO grants (id,org_id,funder,funder_donor_id,program,amount,amount_requested,status,
                         restriction,restricted_from,restricted_until,fund_id,cycle_name,officer_id,officer,
                         notes,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    [id, orgId, fr.funder.name, fr.funder.id, G.sanitizeProgram(req.body.program),
     toDollars(reqCents), toDollars(reqCents), status,
     req.body.restriction || null, req.body.restrictedFrom || null, req.body.restrictedUntil || null,
     fund.fundId, G.sanitizeCycle(req.body.cycleName), officer.officerId, officer.officerName || "",
     G.sanitizeNotes(req.body.notes), actor(req).id, actor(req).name]);
  const [row] = await query(
    `SELECT g.*, d.name AS funder_name, d.funder_type FROM grants g
       JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id WHERE g.id=?`, [id]);
  res.status(201).json(grantRow({ ...row, status_canonical: G.normalizeStatus(row.status) },
    { funds: await orgFundNamesG(orgId), officers: await orgOfficerNames(orgId) }));
}));

async function checkGrantFund(orgId, fundId) {
  if (!fundId) return { ok: true, fundId: null };
  const [f] = await query("SELECT id FROM fin_funds WHERE id=? AND org_id=?", [fundId, orgId]);
  return f ? { ok: true, fundId: f.id } : { ok: false };
}
async function checkGrantOfficer(orgId, officerId) {
  if (!officerId) return { ok: true, officerId: null, officerName: null };
  const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [officerId, orgId]);
  return u ? { ok: true, officerId: u.id, officerName: u.name } : { ok: false };
}

// PUT /grants/:id/award — AWARDED WRITES THE AWARD AS A PLEDGE ON THE FUNDER.
//
// Not a gift: a foundation saying yes in March and paying in two instalments
// across the year is a COMMITMENT, and Steward already has exactly the right
// object for that (88b's pledge path, with instalments that close themselves
// when the money arrives through any door). Writing a gift here would book money
// that has not arrived; writing nothing would lose the schedule.
//
// It is its own route rather than a branch inside the general PUT because the
// general PUT already carries the ledger stamp, the campaign attribution and the
// adopt-an-existing-row guard, and threading a pledge writer through all of that
// is how one of those stops working.
app.put("/grants/:id/award", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const orgId = req.user.orgId;
  const [g] = await query(
    `SELECT g.*, d.name AS funder_name FROM grants g
       LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
      WHERE g.id=? AND g.org_id=?`, [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });
  if (!g.funder_donor_id) {
    return res.status(400).json({ code: "funder_not_linked",
      error: "Link this grant to the funder's organisation record before awarding it — the pledge has to belong to somebody." });
  }
  let awardedCents;
  try { awardedCents = parseMoneyOrThrow(req.body.amountAwarded, "amountAwarded"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  const v = G.validateGrant({ status: "awarded", amountAwardedCents: awardedCents,
                              restriction: req.body.restriction !== undefined ? req.body.restriction : g.restriction,
                              restrictedFrom: req.body.restrictedFrom !== undefined ? req.body.restrictedFrom : g.restricted_from,
                              restrictedUntil: req.body.restrictedUntil !== undefined ? req.body.restrictedUntil : g.restricted_until },
                            { mode: "patch" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_grant", errors: v.errors });

  const org = await orgTz(orgId);
  const today = orgToday(org);                                  // ORG_TZ_SEAM_OK
  // ALREADY AWARDED WRITES NOTHING NEW. A second press must not produce a second
  // pledge — the commitment exists, and a duplicate would double it in every
  // total the funder appears in.
  let pledgeId = g.award_pledge_id || null;
  if (!pledgeId) {
    pledgeId = "pl_" + uuid().slice(0, 8);
    const due = /^\d{4}-\d{2}-\d{2}$/.test(String(req.body.firstDue || "")) ? String(req.body.firstDue) : today;
    await run(
      `INSERT INTO pledges (id,org_id,donor_id,amount,due_date,status,notes,created_by,created_by_name)
       VALUES (?,?,?,?,?,'open',?,?,?)`,
      [pledgeId, orgId, g.funder_donor_id, toDollars(awardedCents), due,
       `Grant award: ${g.program || "grant"}`, actor(req).id, actor(req).name]);
    // THE ONE SCHEDULE WRITER (BUILD-88b). A frequency and a count give the
    // funder's real payment schedule; neither given leaves one instalment for
    // the whole award, so recordGift applies their cheque to it to the cent from
    // whichever door it arrives through.
    await writePledgeInstallments(orgId, pledgeId, {
      amountCents: awardedCents, schedule: req.body.installments,
      frequency: req.body.frequency, count: req.body.installmentCount, firstDue: due,
    }).catch(e => console.error("[grant] instalments:", e.message));
    const [n] = await query("SELECT COUNT(*)::int AS c FROM pledge_installments WHERE pledge_id=?", [pledgeId]);
    if (!n.c) await run(`INSERT INTO pledge_installments (id,org_id,pledge_id,seq,due_date,amount) VALUES (?,?,?,1,?,?)`,
      ["pli_" + uuid().slice(0, 10), orgId, pledgeId, due, toDollars(awardedCents)]);
  }

  await run(
    `UPDATE grants SET status='awarded', amount_awarded=?, award_pledge_id=?,
       restriction=COALESCE(?, restriction), restricted_from=COALESCE(?, restricted_from),
       restricted_until=COALESCE(?, restricted_until),
       awarded_at=COALESCE(awarded_at, NOW()), updated_at=NOW()
     WHERE id=? AND org_id=?`,
    [toDollars(awardedCents), pledgeId,
     req.body.restriction || null, req.body.restrictedFrom || null, req.body.restrictedUntil || null,
     g.id, orgId]);

  const [row] = await query(
    `SELECT g.*, d.name AS funder_name, d.funder_type FROM grants g
       JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id WHERE g.id=?`, [g.id]);
  const [inst] = await query("SELECT COUNT(*)::int AS c FROM pledge_installments WHERE pledge_id=?", [pledgeId]);
  res.json({ ...grantRow({ ...row, status_canonical: "awarded" },
                         { funds: await orgFundNamesG(orgId), officers: await orgOfficerNames(orgId) }),
             pledgeId, installments: inst.c });
}));

// PUT /grants/:id/decline — a no, with its reason, its date, and whether to try
// again. Declining does NOT touch the award pledge if one somehow exists: money
// already committed is a fact, and a status is not a reason to delete it.
app.put("/grants/:id/decline", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id, status FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });
  const v = G.validateGrant({ status: "declined", declineReason: req.body.declineReason,
                              declinedOn: req.body.declinedOn, reapply: req.body.reapply }, { mode: "patch" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_grant", errors: v.errors });
  const org = await orgTz(orgId);
  await run(
    `UPDATE grants SET status='declined', decline_reason=?, declined_on=?, reapply=?, updated_at=NOW()
      WHERE id=? AND org_id=?`,
    [req.body.declineReason, req.body.declinedOn || orgToday(org),    // ORG_TZ_SEAM_OK
     req.body.reapply === undefined ? null : !!req.body.reapply, g.id, orgId]);
  const [row] = await query(
    `SELECT g.*, d.name AS funder_name, d.funder_type FROM grants g
       LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id WHERE g.id=?`, [g.id]);
  res.json(grantRow({ ...row, status_canonical: "declined" },
    { funds: await orgFundNamesG(orgId), officers: await orgOfficerNames(orgId) }));
}));

// GET /grants/pipeline — the Grants screen under Fundraising. By status in
// dollars and count, filtered by program, officer and cycle, sorted by the next
// deadline. EVERY FIGURE CARRIES ITS SENTENCE.
app.get("/grants/pipeline", requireAuth, wrap(async (req, res) => {
  const G = await grantShapeMod();
  const orgId = req.user.orgId;
  const where = ["g.org_id = ?", "g.is_sample IS NOT TRUE"], args = [orgId];
  if (req.query.officerId) { where.push("g.officer_id = ?"); args.push(String(req.query.officerId)); }
  if (req.query.cycle) { where.push("LOWER(COALESCE(g.cycle_name,'')) = LOWER(?)"); args.push(String(req.query.cycle)); }
  if (req.query.program) { where.push("LOWER(COALESCE(g.program,'')) LIKE LOWER(?)"); args.push("%" + String(req.query.program) + "%"); }
  if (req.query.status) {
    const want = String(req.query.status).split(",").map(x => G.normalizeStatus(x)).filter(Boolean);
    if (!want.length) return res.status(400).json({ error: "Unknown status" });
    // Match the canonical status AND every legacy spelling of it, so a filter
    // does not silently hide rows written before this build.
    const spellings = [...want];
    for (const [alias, canon] of Object.entries(G.STATUS_ALIASES)) if (want.includes(canon)) spellings.push(alias);
    where.push("LOWER(g.status) = ANY(?::text[])"); args.push(spellings);
  }
  const rows = await query(
    `SELECT g.*, d.name AS funder_name, d.funder_type FROM grants g
       LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
      WHERE ${where.join(" AND ")}`, args);
  const funds = await orgFundNamesG(orgId), officers = await orgOfficerNames(orgId);
  const all = rows.map(r => ({
    ...grantRow({ ...r, status_canonical: G.normalizeStatus(r.status) }, { funds, officers }),
    // The next dated thing on this grant, whichever it is. Part 2 replaces this
    // with the milestone table; until then the two dates the row already has are
    // the honest answer rather than a blank column.
    nextDeadline: [r.deadline, r.report_due].filter(x => /^\d{4}-\d{2}-\d{2}$/.test(String(x || ""))).sort()[0] || null,
  }));
  const sort = ["deadline", "amount", "funder", "status"].includes(String(req.query.sort)) ? String(req.query.sort) : "deadline";
  const grants = G.sortGrants(all, sort);
  const byStatus = G.pipelineByStatus(all).map(r => ({
    ...r, amount: toDollars(r.cents), sentence: G.statusTileSentence(r, money.formatCentsPlain),
  }));
  const open = all.filter(x => G.isOpenStatus(x.status));
  const openCents = open.reduce((s, x) => s + G.pipelineCentsFor(x), 0);
  const cycles = [...new Set(all.map(x => x.cycleName).filter(Boolean))].sort();
  res.json({
    grants, byStatus, sort,
    openPipeline: { cents: openCents, amount: toDollars(openCents), count: open.length,
                    sentence: G.openPipelineSentence({ cents: openCents, count: open.length }, money.formatCentsPlain) },
    statuses: G.GRANT_STATUSES, restrictions: G.RESTRICTIONS, declineReasons: G.DECLINE_REASONS,
    funderTypes: G.FUNDER_TYPES, cycles,
    funds: [...funds.entries()].map(([id, name]) => ({ id, name })),
    officers: [...officers.entries()].map(([id, name]) => ({ id, name })),
  });
}));

function milestoneRow(r, M, today, leadDays) {
  const m = {
    id: r.id, grantId: r.grant_id, kind: r.kind, kindLabel: M.milestoneLabel(r.kind),
    dueDate: r.due_date, state: r.state, threadId: r.thread_id || null,
    funderName: r.funder_name || r.funder || "", program: r.program || "",
    grantStatus: r.status || null, notes: r.notes || "",
    completedAt: r.completed_at || null, completedByName: r.completed_by_name || null,
  };
  const t = M.milestoneTiming(m, today);
  m.band = t.band; m.overdueDays = t.overdueDays; m.daysUntil = t.days; m.sentence = t.sentence;
  m.leadDays = M.leadDaysFor(r.kind, leadDays);
  if (r.state === "waiting") m.waitingSentence = M.waitingSentence(m);
  return m;
}

// POST /grants/:id/milestones — add a dated thing owed on this grant.
app.post("/grants/:id/milestones", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const M = await grantMsMod();
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id, status FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });
  const kind = String(req.body.kind || "");
  if (!M.MILESTONE_KEYS.includes(kind)) {
    return res.status(400).json({ code: "bad_milestone_kind",
      error: `A milestone is one of: ${M.MILESTONE_TYPES.map(t => t.label).join(", ")}.` });
  }
  const due = String(req.body.dueDate || "");
  if (!M.isCivilDate(due)) return res.status(400).json({ code: "bad_due_date", error: "The date must be YYYY-MM-DD." });
  const type = M.milestoneType(kind);
  if (!type.repeatable) {
    const [dupe] = await query(
      "SELECT id, due_date FROM grant_milestones WHERE grant_id=? AND kind=? AND state <> 'skipped'",
      [g.id, kind]);
    if (dupe) {
      return res.status(400).json({ code: "milestone_exists",
        error: `This grant already has a ${type.label} on ${dupe.due_date}. Move that date rather than adding a second one.` });
    }
  }
  const id = "gms_" + uuid().slice(0, 10);
  await run(`INSERT INTO grant_milestones (id,org_id,grant_id,kind,due_date,state,notes,created_by,created_by_name)
             VALUES (?,?,?,?,?, 'pending', ?,?,?)`,
    [id, orgId, g.id, kind, due, String(req.body.notes || "").slice(0, 2000),
     actor(req).id, actor(req).name]);

  // Raise it NOW if its lead time has already arrived — a report due next week
  // typed in today must not wait for a sweep to notice.
  const org = await orgTz(orgId);
  const today = orgToday(org);                                  // ORG_TZ_SEAM_OK
  const leadDays = await orgLeadDays(orgId);
  if (M.dueWithinLead({ kind, dueDate: due }, today, leadDays)) {
    await raiseGrantMilestone(orgId, { id, grant_id: g.id, kind, due_date: due }, { today });
  }
  const [row] = await query(
    `SELECT m.*, g.program, g.status, g.funder, d.name AS funder_name
       FROM grant_milestones m JOIN grants g ON g.id=m.grant_id AND g.org_id=m.org_id
       LEFT JOIN donors d ON d.id=g.funder_donor_id AND d.org_id=g.org_id
      WHERE m.id=?`, [id]);
  res.status(201).json(milestoneRow(row, M, today, leadDays));
}));

// PUT /grants/milestones/:msId — MOVING THE DATE MOVES THE THREAD.
// A date that moves and leaves a thread pointing at the old one is how an
// officer ends up chasing a deadline that no longer exists.
app.put("/grants/milestones/:msId", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const M = await grantMsMod();
  const orgId = req.user.orgId;
  const [ms] = await query("SELECT * FROM grant_milestones WHERE id=? AND org_id=?", [req.params.msId, orgId]);
  if (!ms) return res.status(404).json({ error: "Milestone not found" });
  const due = req.body.dueDate === undefined ? ms.due_date : String(req.body.dueDate || "");
  if (!M.isCivilDate(due)) return res.status(400).json({ code: "bad_due_date", error: "The date must be YYYY-MM-DD." });

  const org = await orgTz(orgId);
  const today = orgToday(org);                                  // ORG_TZ_SEAM_OK
  const leadDays = await orgLeadDays(orgId);

  await run(`UPDATE grant_milestones SET due_date=?, notes=COALESCE(?, notes), updated_at=NOW()
              WHERE id=? AND org_id=?`,
    [due, req.body.notes === undefined ? null : String(req.body.notes).slice(0, 2000), ms.id, orgId]);

  if (due !== ms.due_date && ms.thread_id) {
    // The thread's own due date follows, through the threads table the Thread
    // engine reads — the label is unchanged because the work is unchanged.
    // `original_due_date` is preserved the way BUILD-81's snooze preserves it
    // (COALESCE, so the FIRST date survives every later move): "we said the
    // 14th" is a fact about the relationship, not a stale value.
    // NB `threads` has no `updated_at` column — naming one 500'd this route
    // and left the thread pointing at a deadline that had moved.
    await run(`UPDATE threads
                  SET due_date = ?,
                      original_due_date = COALESCE(original_due_date, due_date)
                WHERE id=? AND org_id=? AND closed_at IS NULL`, [due, ms.thread_id, orgId]);
  }
  // A date moved OUT beyond its lead time with no thread yet goes back to
  // pending, so a waiting milestone that is no longer urgent stops queueing.
  if (!ms.thread_id && ms.state === "waiting"
      && !M.dueWithinLead({ kind: ms.kind, dueDate: due }, today, leadDays)) {
    await run("UPDATE grant_milestones SET state='pending', updated_at=NOW() WHERE id=? AND org_id=?", [ms.id, orgId]);
  }
  if (!ms.thread_id && M.dueWithinLead({ kind: ms.kind, dueDate: due }, today, leadDays)) {
    await raiseGrantMilestone(orgId, { ...ms, due_date: due }, { today });
  }
  const [row] = await query(
    `SELECT m.*, g.program, g.status, g.funder, d.name AS funder_name
       FROM grant_milestones m JOIN grants g ON g.id=m.grant_id AND g.org_id=m.org_id
       LEFT JOIN donors d ON d.id=g.funder_donor_id AND d.org_id=g.org_id
      WHERE m.id=?`, [ms.id]);
  res.json(milestoneRow(row, M, today, leadDays));
}));

// POST /grants/milestones/:msId/done — somebody did it.
// It does NOT close the thread: the Thread engine's own close is honest
// (BUILD-81's CHECK), and closing it from here would write a close with no
// interaction behind it. The milestone is marked and the thread is the
// officer's to log a line against.
app.post("/grants/milestones/:msId/done", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const M = await grantMsMod();
  const orgId = req.user.orgId;
  const [ms] = await query("SELECT * FROM grant_milestones WHERE id=? AND org_id=?", [req.params.msId, orgId]);
  if (!ms) return res.status(404).json({ error: "Milestone not found" });
  const [u] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [actor(req).id, orgId]);
  await run(`UPDATE grant_milestones SET state='done', completed_at=NOW(),
               completed_by=?, completed_by_name=?, updated_at=NOW()
              WHERE id=? AND org_id=?`,
    [actor(req).id, (u && u.name) || actor(req).name, ms.id, orgId]);
  const org = await orgTz(orgId);
  res.json({ ok: true, id: ms.id, state: "done",
    nextDeadlineSentence: M.milestoneTiming({ kind: ms.kind, dueDate: ms.due_date }, orgToday(org)).sentence });  // ORG_TZ_SEAM_OK
}));

// GET /grants/deadlines — the calendar, the list, and the Home line.
app.get("/grants/deadlines", requireAuth, wrap(async (req, res) => {
  const M = await grantMsMod();
  const orgId = req.user.orgId;
  const org = await orgTz(orgId);
  const today = req.query.today && testMode() && M.isCivilDate(String(req.query.today))
    ? String(req.query.today) : orgToday(org);                   // ORG_TZ_SEAM_OK
  const leadDays = await orgLeadDays(orgId);
  const rows = await query(
    `SELECT m.*, g.program, g.status, g.funder, g.officer_id, d.name AS funder_name
       FROM grant_milestones m
       JOIN grants g ON g.id = m.grant_id AND g.org_id = m.org_id
       LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
      WHERE m.org_id=? AND g.is_sample IS NOT TRUE AND m.state <> 'skipped'
      ORDER BY m.due_date ASC`, [orgId]);
  const all = rows.map(r => milestoneRow(r, M, today, leadDays));
  const open = all.filter(m => m.state !== "done");

  // BUILD-100 Part 4 — A REPORT-DUE MILESTONE CARRIES ITS GRANT'S BALANCE,
  // because the balance is what the report is about. Only for `report_due`: the
  // figure is not relevant to an LOI deadline and a number on a row that does
  // not need it is a number somebody has to decide to ignore. One batched read,
  // never a query per row.
  const reportGrantIds = [...new Set(open.filter(m => m.kind === "report_due").map(m => m.grantId))];
  if (reportGrantIds.length) {
    const R = await restrictedMod();
    const moneyRows = await grantMoneyRows(orgId, `AND g.id = ANY(?::text[])`, [reportGrantIds]);
    const byGrant = new Map(moneyRows.map(r => [r.id, grantBalanceFrom(R, r, today)]));
    for (const m of open) {
      if (m.kind !== "report_due") continue;
      const b = byGrant.get(m.grantId);
      if (b) m.balance = { restricted: b.restricted, remaining: b.remaining, remainingCents: b.remainingCents,
                           spent: b.spent, received: b.received, sentence: b.sentence };
    }
  }
  res.json({
    today,
    milestones: M.sortMilestones(open),
    done: all.filter(m => m.state === "done").length,
    overdue: open.filter(m => m.band === "overdue").length,
    calendar: M.calendarFromMilestones(open, today),
    homeLine: M.homeDeadlineLine(open, today),
    leadDays,
    milestoneTypes: M.MILESTONE_TYPES,
  });
}));

// PUT /org/grant-lead-days — the org's own lead times (admins).
app.put("/org/grant-lead-days", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const M = await grantMsMod();
  // MERGE OVER WHAT THE ORG ALREADY CHOSE, never over the defaults. Sending
  // one key used to reset the other four to their defaults — an org that set
  // the report lead to 45 in September lost it the moment it touched the
  // decision lead in October, and nothing on the screen would have said so.
  const stored = await orgLeadDays(req.user.orgId);
  // pickLeadDays, NOT normalizeLeadDays: the latter fills from the DEFAULTS, so
  // merging an invalid value in took the key back to its default instead of
  // leaving the org's own choice standing. The patch contributes only the keys
  // it actually got right.
  const clean = M.normalizeLeadDays({ ...stored, ...M.pickLeadDays(req.body && req.body.leadDays) });
  await run("UPDATE orgs SET grant_lead_days=?::jsonb WHERE id=?", [JSON.stringify(clean), req.user.orgId]);
  res.json({ leadDays: clean, defaults: M.DEFAULT_LEAD_DAYS });
}));

// POST /grants/milestones/run — the ops/test door onto the sweep (the
// /photos/run, /nudges/run convention). Caller's org only.
app.post("/grants/milestones/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const summary = await processGrantMilestones(req.user.orgId, { today: req.body && req.body.today });
  res.json(summary);
}));

function grantDocUrl(orgId, assetId) {
  return grantDocs.signDocUrl({ orgId, assetId });
}

function grantDocRow(r, orgId) {
  return {
    id: r.id, grantId: r.grant_id,
    docType: r.doc_type, docTypeLabel: grantDocs.docTypeLabel(r.doc_type),
    fileName: r.file_name, contentType: r.content_type || null, bytes: r.bytes || null,
    notes: r.notes || "",
    // ISO, ALWAYS. `uploaded_at` is a timestamptz and pg hands it back as a JS
    // Date; `String(date)` is "Thu Sep 25 2026 …", which sorts lexically by
    // WEEKDAY NAME. Both the version numbering and the funder list sort on this
    // value, so a Date here silently numbered "proposal #1" and "#2" by the day
    // of the week they were uploaded. Same class as BUILD-86's TO_CHAR lesson.
    uploadedAt: r.uploaded_at instanceof Date ? r.uploaded_at.toISOString() : r.uploaded_at,
    uploadedByName: r.uploaded_by_name || "",
    // The link is minted PER READ and lives thirty minutes. A stored URL is a
    // URL that outlives the reason it was made.
    url: grantDocUrl(orgId, r.asset_id),
    funderName: r.funder_name || r.funder || "", program: r.program || "",
  };
}

// POST /grants/:id/documents — one file, on a grant that already exists.
app.post("/grants/:id/documents", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });

  const docType = String(req.body.docType || "");
  if (!grantDocs.DOC_TYPE_KEYS.includes(docType)) {
    return res.status(400).json({ code: "bad_doc_type",
      error: `A document is one of: ${grantDocs.DOC_TYPES.map(t => t.label).join(", ")}.` });
  }

  // A data URI, the shape every other upload in this product takes.
  const m = /^data:([a-zA-Z0-9.+/-]+);base64,(.+)$/s.exec(String(req.body.file || ""));
  if (!m) return res.status(400).json({ code: "no_file", error: "Attach a file." });
  const mime = m[1].toLowerCase();
  if (!grantDocs.mimeAllowed(mime)) {
    return res.status(400).json({ code: "bad_file_type",
      error: "Steward stores PDFs, Word documents, images and plain text. It deliberately refuses anything that can carry a script." });
  }
  let buffer;
  try { buffer = Buffer.from(m[2], "base64"); }
  catch { return res.status(400).json({ code: "no_file", error: "That file could not be read." }); }
  if (!buffer.length) return res.status(400).json({ code: "no_file", error: "That file is empty." });
  if (buffer.length > grantDocs.DOC_MAX_BYTES) {
    return res.status(400).json({ code: "file_too_large",
      error: `That file is ${Math.round(buffer.length / 1024 / 1024)} MB. The limit is ${grantDocs.DOC_MAX_BYTES / 1024 / 1024} MB.` });
  }
  // THE BYTES DECIDE. A caller declaring application/pdf over an HTML payload
  // is the hole this closes, and it is checked BEFORE anything is stored.
  if (!grantDocs.bytesMatchMime(buffer, mime)) {
    return res.status(400).json({ code: "file_type_mismatch",
      error: `That file does not look like a ${grantDocs.extensionFor(mime) || mime}. Check you attached what you meant to.` });
  }

  const asset = await putThemeAsset({
    orgId, kind: grantDocs.DOC_ASSET_KIND, buffer, contentType: mime,
  });
  const id = "gdoc_" + uuid().slice(0, 10);
  const fileName = grantDocs.sanitizeFilename(req.body.fileName, mime);
  // The SAME bytes under the SAME type on one grant is a double-click, not two
  // documents — the unique index says so and this answers it as success rather
  // than an error, because from the user's side the file IS on the grant.
  const ins = await query(
    `INSERT INTO grant_documents (id,org_id,grant_id,doc_type,asset_id,file_name,content_type,bytes,notes,uploaded_by,uploaded_by_name)
     VALUES (?,?,?,?,?,?,?,?,?,?,?)
     ON CONFLICT (grant_id, doc_type, asset_id) DO NOTHING
     RETURNING id`,
    [id, orgId, g.id, docType, asset.id, fileName, mime, buffer.length,
     String(req.body.notes || "").slice(0, 2000), actor(req).id,
     (await query("SELECT name FROM users WHERE id=? AND org_id=?", [actor(req).id, orgId]))[0]?.name || actor(req).name]);
  const finalId = ins.length ? ins[0].id
    : (await query("SELECT id FROM grant_documents WHERE grant_id=? AND doc_type=? AND asset_id=?",
        [g.id, docType, asset.id]))[0].id;
  await recordAssetPointerHistory(orgId, "grant.document", finalId, null, asset.id, req.user);

  const [row] = await query(
    `SELECT d.*, g.program, g.funder, f.name AS funder_name
       FROM grant_documents d JOIN grants g ON g.id=d.grant_id AND g.org_id=d.org_id
       LEFT JOIN donors f ON f.id=g.funder_donor_id AND f.org_id=g.org_id
      WHERE d.id=?`, [finalId]);
  res.status(201).json({ ...grantDocRow(row, orgId), duplicate: ins.length === 0 });
}));

// GET /grants/:id/documents — the grant's own file list, versioned by date.
app.get("/grants/:id/documents", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });
  const rows = await query(
    `SELECT d.*, g.program, g.funder, f.name AS funder_name
       FROM grant_documents d JOIN grants g ON g.id=d.grant_id AND g.org_id=d.org_id
       LEFT JOIN donors f ON f.id=g.funder_donor_id AND f.org_id=g.org_id
      WHERE d.grant_id=? AND d.org_id=? ORDER BY d.uploaded_at ASC`, [g.id, orgId]);
  const docs = grantDocs.withVersions(rows.map(r => grantDocRow(r, orgId)));
  res.json({ documents: docs, sentence: grantDocs.documentSentence(docs), docTypes: grantDocs.DOC_TYPES });
}));

// DELETE /grants/documents/:docId — ungated, per the DELETE convention. The
// asset is NOT destroyed here: it is soft-deleted by the retention sweep once
// nothing points at it (BUILD-56's one destruction seam), so a mistaken delete
// is recoverable for ninety days.
app.delete("/grants/documents/:docId", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [d] = await query("SELECT id, asset_id FROM grant_documents WHERE id=? AND org_id=?",
    [req.params.docId, orgId]);
  if (!d) return res.status(404).json({ error: "Document not found" });
  await run("DELETE FROM grant_documents WHERE id=? AND org_id=?", [d.id, orgId]);
  await recordAssetPointerHistory(orgId, "grant.document", d.id, d.asset_id, null, req.user);
  res.json({ ok: true, id: d.id });
}));

// GET /funders/:donorId/documents — EVERY document across a funder's grants.
// The brief asks for this because the question is "have we ever signed
// anything with these people", and that question spans grants.
app.get("/funders/:donorId/documents", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const fr = await resolveFunder(orgId, req.params.donorId);
  if (!fr.ok) {
    const code = fr.problem.code === "funder_not_found" ? 404 : 400;
    return res.status(code).json({ error: fr.problem.message, code: fr.problem.code });
  }
  const rows = await query(
    `SELECT d.*, g.program, g.funder, g.status AS grant_status, f.name AS funder_name
       FROM grant_documents d
       JOIN grants g ON g.id = d.grant_id AND g.org_id = d.org_id
       LEFT JOIN donors f ON f.id = g.funder_donor_id AND f.org_id = g.org_id
      WHERE d.org_id=? AND g.funder_donor_id=? ORDER BY d.uploaded_at ASC`, [orgId, fr.funder.id]);
  // Versions are PER GRANT, not per funder — "proposal #2" means the second
  // proposal on that grant, and numbering across grants would be a figure
  // nobody could reconcile against anything.
  const byGrant = new Map();
  for (const r of rows) {
    if (!byGrant.has(r.grant_id)) byGrant.set(r.grant_id, []);
    byGrant.get(r.grant_id).push(grantDocRow(r, orgId));
  }
  const documents = [];
  for (const [, list] of byGrant) documents.push(...grantDocs.withVersions(list));
  documents.sort((a, b) => String(b.uploadedAt).localeCompare(String(a.uploadedAt)));
  res.json({
    funder: { funderId: fr.funder.id, name: fr.funder.name },
    documents, sentence: grantDocs.documentSentence(documents), docTypes: grantDocs.DOC_TYPES,
  });
}));

// GET /grant-documents/:id — the signed, expiring, PRIVATE door.
// Unauthenticated by design (a browser fetches a file with no auth header);
// the URL carries its own signature and the org comes from the STORED ROW.
app.get("/grant-documents/:id", wrap(async (req, res) => {
  const id = String(req.params.id || "");
  if (!ASSET_ID_RE.test(id)) return res.status(404).json({ error: "not_found" });
  const [row] = await query(
    `SELECT org_id FROM portal_assets WHERE id = ? AND kind = ? AND deleted_at IS NULL`,
    [id, grantDocs.DOC_ASSET_KIND]);
  if (!row) return res.status(404).json({ error: "not_found" });
  const v = grantDocs.verifyDocUrl({ orgId: row.org_id, assetId: id, e: req.query.e, s: req.query.s });
  // ONE answer for expired and for wrong-org alike, so a probe cannot tell
  // "this agreement exists in another tenant" from "this link is old".
  if (!v.ok) return res.status(403).json({ error: "link_expired" });
  const asset = await getThemeAsset(id);
  if (!asset) return res.status(404).json({ error: "not_found" });
  // The stored filename is looked up for the download name; the bytes are
  // addressed by asset id, so the name is only ever a label.
  const [meta] = await query(
    "SELECT file_name FROM grant_documents WHERE asset_id=? AND org_id=? LIMIT 1", [id, row.org_id]);
  res.set("Content-Type", asset.contentType);
  // A document is never rendered inline: a PDF viewer in our own origin is a
  // parser we did not choose running on a file a funder sent.
  const safeName = grantDocs.sanitizeFilename((meta && meta.file_name) || "document", asset.contentType);
  res.set("Content-Disposition", `attachment; filename="${safeName.replace(/"/g, "")}"`);
  res.set("X-Content-Type-Options", "nosniff");
  res.set("Cache-Control", `private, max-age=${Math.max(0, Math.floor((v.expiresAt - Date.now()) / 1000))}`);
  res.set("ETag", `"${asset.id}"`);
  res.send(asset.buffer);
}));

// POST /grants/:id/spend — one line of spending against a restricted award.
app.post("/grants/:id/spend", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const R = await restrictedMod();
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id, restriction FROM grants WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Grant not found" });
  let cents;
  try { cents = parseMoneyOrThrow(req.body.amount, "amount"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  const v = R.validateSpend({ amountCents: cents, spentOn: req.body.spentOn, description: req.body.description });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_spend", errors: v.errors });
  const [u] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [actor(req).id, orgId]);
  const id = "gsp_" + uuid().slice(0, 10);
  await run(`INSERT INTO grant_spend (id,org_id,grant_id,amount,spent_on,description,created_by,created_by_name)
             VALUES (?,?,?,?,?,?,?,?)`,
    [id, orgId, g.id, toDollars(cents), String(req.body.spentOn),
     String(req.body.description).trim().slice(0, 500), actor(req).id, (u && u.name) || actor(req).name]);
  const [row] = (await grantMoneyRows(orgId, "AND g.id = ?", [g.id]));
  const org = await orgTz(orgId);
  res.status(201).json({
    id, grantId: g.id, amount: toDollars(cents), amountCents: cents,
    balance: grantBalanceFrom(R, row, orgToday(org)),                   // ORG_TZ_SEAM_OK
    note: R.SPEND_SOURCE_NOTE,
  });
}));

app.delete("/grants/spend/:spendId", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [s] = await query("SELECT id FROM grant_spend WHERE id=? AND org_id=?", [req.params.spendId, orgId]);
  if (!s) return res.status(404).json({ error: "Not found" });
  await run("DELETE FROM grant_spend WHERE id=? AND org_id=?", [s.id, orgId]);
  res.json({ ok: true, id: s.id });
}));

// GET /grants/:id/restricted — one grant's restricted position, with the
// spending lines behind it so a figure can always be taken apart.
app.get("/grants/:id/restricted", requireAuth, wrap(async (req, res) => {
  const R = await restrictedMod();
  const orgId = req.user.orgId;
  const rows = await grantMoneyRows(orgId, "AND g.id = ?", [req.params.id]);
  if (!rows.length) return res.status(404).json({ error: "Grant not found" });
  const org = await orgTz(orgId);
  const today = orgToday(org);                                          // ORG_TZ_SEAM_OK
  const balance = grantBalanceFrom(R, rows[0], today);
  const spend = await query(
    `SELECT id, amount, spent_on, description, created_by_name, created_at
       FROM grant_spend WHERE org_id=? AND grant_id=? ORDER BY spent_on DESC, created_at DESC`,
    [orgId, req.params.id]);
  const payments = rows[0].award_pledge_id ? await query(
    `SELECT id, amount, date FROM gifts WHERE org_id=? AND pledge_id=? ORDER BY date ASC`,
    [orgId, rows[0].award_pledge_id]) : [];
  res.json({
    balance,
    // EVERY FIGURE CARRIES ITS DEFINITION, one string from the registry.
    definitions: Object.fromEntries(R.RESTRICTED_METRICS.map(m => [m.key, m.definition])),
    metrics: R.RESTRICTED_METRICS,
    spend: spend.map(s => ({
      id: s.id, amount: toDollars(toCents(s.amount) || 0), amountCents: toCents(s.amount) || 0,
      spentOn: s.spent_on, description: s.description, byName: s.created_by_name || "",
    })),
    payments: payments.map(p => ({
      id: p.id, amount: toDollars(toCents(p.amount) || 0), amountCents: toCents(p.amount) || 0, date: p.date,
    })),
    spendSourceNote: R.SPEND_SOURCE_NOTE,
  });
}));

// ── BUILD-100 (grants) Part 6 — READING SOMEBODY ELSE'S GRANT SPREADSHEET ───
// shared/grantImport.js is the preset — a preset on the mapper, never a second
// importer (the 89d rule, fourth application). This is the ONE write path it
// lands through, and it writes grants and funders and NOTHING ELSE: no gift, no
// pledge, no milestone, no thread. An imported file is history (BUILD-83), and a
// report that was due last March is not a follow-up somebody has to close this
// morning.
async function grantImportMod() { return import("../shared/grantImport.js"); }

// GET /grants/import/preview — what Steward makes of a file, before it writes
// anything. It reads and returns; it changes nothing, which is what makes the
// four-state deposit-sheet discipline available here too.
app.post("/grants/import/preview", requireAuth, wrap(async (req, res) => {
  const out = await planGrantImport(req.user.orgId, req.body || {});
  if (out.error) return res.status(400).json(out);
  res.json({ ...out, wrote: false });
}));

// THE PLAN, shared by the preview and the commit, so the screen can never be
// shown one thing and the database given another (the BUILD-95 rule: the commit
// RE-PLANS server-side and writes from the plan, never from the client's copy).
async function planGrantImport(orgId, body) {
  const I = await grantImportMod();
  const G = await grantShapeMod();
  const headers = Array.isArray(body.headers) ? body.headers.map(h => String(h == null ? "" : h)) : [];
  const rawRows = Array.isArray(body.rows) ? body.rows : [];
  if (!headers.length) return { error: "That file has no header row.", code: "no_headers" };
  if (!rawRows.length) return { error: "That file has no rows.", code: "no_rows" };
  if (rawRows.length > 5000) {
    return { error: "That file has more than 5,000 rows. Split it and import in two passes.", code: "too_many_rows" };
  }

  const detected = I.detectGrantSource(headers);
  // A SOURCE THE PERSON STATES WINS over what Steward detected — they have the
  // file open and Steward has a header row.
  const source = I.GRANT_SOURCE_KEYS.includes(String(body.source || "")) ? String(body.source) : detected.source;
  const { mapping, spellings, unrecognised } = I.grantMapping(headers);
  // A MAPPING THE PERSON CORRECTED wins too, field by field, and only for a
  // field this module knows — an unknown key cannot smuggle a column in.
  if (body.mapping && typeof body.mapping === "object") {
    for (const [f, h] of Object.entries(body.mapping)) {
      if (I.GRANT_FIELD_KEYS.includes(f) && (h === null || headers.includes(String(h)))) {
        if (h === null) delete mapping[f]; else mapping[f] = String(h);
      }
    }
  }
  if (!mapping.funderName && !mapping.funderEin) {
    return { error: "Steward could not find the funder's name in that file. Point it at the column that holds it.",
             code: "no_funder_column", headers, mapping, unrecognised, source, detected };
  }

  const built = I.buildGrantRows(rawRows, {
    mapping, spellings, source, money,
    cell: (row, header) => Array.isArray(row) ? row[headers.indexOf(header)] : (row || {})[header],
  });

  // ── RESOLVING THE FUNDERS ────────────────────────────────────────────────
  // Every candidate the file could be talking about, read ONCE. A per-row query
  // would be forty round trips on a forty-row file and 25,000 on a real one.
  const candidates = (await query(
    `SELECT id, name, kind, funder_ein FROM donors WHERE org_id=? AND deleted_at IS NULL`, [orgId]))
    .map(d => ({ id: d.id, name: d.name, kind: d.kind, funderEin: d.funder_ein }));

  const byKey = new Map();               // one decision per distinct funder in the file
  for (const g of built.grants) {
    const key = (I.normalizeEin(g.funderEin) ? "e:" + I.normalizeEin(g.funderEin) : "n:" + I.funderNameKey(g.funderName));
    if (!byKey.has(key)) {
      byKey.set(key, { key, name: g.funderName, ein: I.normalizeEin(g.funderEin), lines: [],
                       ...I.matchFunder({ name: g.funderName, ein: g.funderEin }, candidates) });
    }
    byKey.get(key).lines.push(g.line);
  }

  // Already on file, by the same key the write path will use.
  const existingKeys = new Set();
  for (const r of await query(
    `SELECT g.id, g.program, g.deadline, g.external_id, d.name AS funder_name
       FROM grants g LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
      WHERE g.org_id=?`, [orgId])) {
    existingKeys.add(I.grantDedupeKey({ externalId: r.external_id, funderName: r.funder_name || "",
                                        program: r.program || "", deadline: r.deadline || null }));
  }

  const refused = [...built.refused];
  const plan = [], seen = new Set();
  let skipped = 0;
  for (const g of built.grants) {
    const key = (I.normalizeEin(g.funderEin) ? "e:" + I.normalizeEin(g.funderEin) : "n:" + I.funderNameKey(g.funderName));
    const f = byKey.get(key);
    if (f.refused === "funder_is_a_person") {
      refused.push({ line: g.line, funderName: g.funderName, program: g.program,
                     why: I.FUNDER_IS_A_PERSON, code: "funder_is_a_person", person: f.person });
      continue;
    }
    if (f.refused === "funder_not_named") {
      refused.push({ line: g.line, why: "no funder named", code: "funder_not_named" });
      continue;
    }
    const dk = I.grantDedupeKey(g);
    // THE SAME FILE TWICE ADDS NOTHING, and the same row twice INSIDE one file
    // is the same thing — both are skipped and counted, never silently folded.
    if (existingKeys.has(dk) || seen.has(dk)) { skipped++; continue; }
    seen.add(dk);
    plan.push({ ...g, funderKey: key, dedupeKey: dk });
  }

  const pipelineCents = plan.reduce((sum, g) =>
    sum + (G.isOpenStatus(g.status) ? (g.amountRequestedCents || 0) : 0), 0);
  const funders = [...byKey.values()].filter(f => !f.refused);
  return {
    source, detected, mapping, unrecognised,
    grants: plan.map(g => ({ ...g, amountRequested: toDollars(g.amountRequestedCents),
                             amountAwarded: g.amountAwardedCents == null ? null : toDollars(g.amountAwardedCents) })),
    funders: funders.map(f => ({ name: f.name, ein: f.ein, donorId: f.donorId || null,
                                 how: f.how || null, willCreate: !!f.create, grants: f.lines.length })),
    counts: {
      rows: rawRows.length, grants: plan.length, funders: funders.length,
      willCreateFunders: funders.filter(f => f.create).length,
      matchedByEin: funders.filter(f => f.how === "ein").length,
      matchedByName: funders.filter(f => f.how === "name").length,
      skipped, refused: refused.length, ...built.counted,
    },
    refused,
    pipelineCents, pipeline: toDollars(pipelineCents),
    // NOTHING IS INVENTED HERE AND THE PLAN SAYS SO, so nobody has to read the
    // route to know what an import will and will not touch.
    writes: ["grants", "funder organisations that were not on file"],
    doesNotWrite: ["gifts", "pledges", "deadlines Steward watches", "follow-ups"],
    plan_: plan,
  };
}

// POST /grants/import — the ONE write path. Everything lands inside one
// transaction, so a file that fails halfway leaves no half-imported pipeline.
app.post("/grants/import", requireAuth, requirePlan("team"), checkWriteAccess, wrap(async (req, res) => {
  const I = await grantImportMod();
  const orgId = req.user.orgId;
  const plan = await planGrantImport(orgId, req.body || {});
  if (plan.error) return res.status(400).json(plan);

  const who = actor(req);
  const [u] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [who.id, orgId]);
  const byName = (u && u.name) || who.name;
  const created = [], written = [];

  await withTransaction(async (client) => {
    const trun = (sql, args) => runTx(client, sql, args);
    const tquery = (sql, args) => queryTx(client, sql, args);
    // 1 — THE FUNDERS FIRST, and every one created as an ORGANISATION. A funder
    // created as a person would be refused by Part 1's own door the next time
    // anybody touched it, which is the shape of a bug that looks like data.
    const resolved = new Map();
    for (const f of plan.funders) {
      if (f.donorId) { resolved.set(f.name, f.donorId); continue; }
      const id = "dn_" + uuid().slice(0, 10);
      await trun(
        `INSERT INTO donors (id,org_id,name,kind,stage,status,total_giving,gift_count,funder_ein,
                             person_types,created_by,created_by_name)
         VALUES (?,?,?,'organisation','prospect','new',0,0,?,?,?,?)`,
        [id, orgId, f.name, f.ein || null, JSON.stringify(["donor"]), who.id, byName]);
      resolved.set(f.name, id);
      created.push({ id, name: f.name, ein: f.ein || null });
    }
    // An EIN we now hold for a funder already on file is worth keeping, but it
    // NEVER overwrites one somebody already typed.
    for (const f of plan.funders) {
      if (f.donorId && f.ein) {
        await trun("UPDATE donors SET funder_ein=COALESCE(funder_ein, ?) WHERE id=? AND org_id=?",
          [f.ein, f.donorId, orgId]).catch(() => {});
      }
    }

    // 2 — THE FUND AND THE OFFICER, matched by name to what the org already has.
    // NOTHING IS CREATED on either: a fund is a board decision (BUILD-88a's rule)
    // and a user is a login. An unmatched name is carried into the notes so it is
    // not lost, and counted.
    const funds = new Map((await tquery("SELECT id, name FROM fin_funds WHERE org_id=?", [orgId]))
      .map(f => [String(f.name).trim().toLowerCase(), f.id]));
    const officers = new Map((await tquery("SELECT id, name FROM users WHERE org_id=?", [orgId]))
      .map(o => [String(o.name || "").trim().toLowerCase(), o.id]));

    for (const g of plan.plan_) {
      const funderId = resolved.get(g.funderName);
      const fundId = g.fundName ? funds.get(String(g.fundName).trim().toLowerCase()) || null : null;
      const officerId = g.officerName ? officers.get(String(g.officerName).trim().toLowerCase()) || null : null;
      const unmatched = [
        g.fundName && !fundId ? `The file named the fund "${g.fundName}", which is not on the chart of accounts.` : null,
        g.officerName && !officerId ? `The file named "${g.officerName}" as the officer, who is not a user here.` : null,
      ].filter(Boolean);
      const notes = [g.notes, ...unmatched].filter(Boolean).join(" ").slice(0, 4000) || null;
      const id = "gr_" + uuid().slice(0, 10);
      await trun(
        `INSERT INTO grants (id,org_id,funder,funder_donor_id,program,amount,amount_requested,amount_awarded,
                             status,deadline,restriction,fund_id,officer_id,cycle_name,decline_reason,declined_on,
                             external_id,notes,is_sample,created_by,created_by_name)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,FALSE,?,?)`,
        [id, orgId, g.funderName, funderId, g.program,
         toDollars(g.amountAwardedCents || g.amountRequestedCents),
         toDollars(g.amountRequestedCents),
         g.amountAwardedCents == null ? null : toDollars(g.amountAwardedCents),
         g.status, g.deadline, g.restriction, fundId, officerId, g.cycleName,
         g.declineReason, g.declinedOn, g.externalId, notes, who.id, byName]);
      // AN AWARDED GRANT IMPORTED FROM A FILE GETS NO PLEDGE. Part 1's award door
      // writes one because a live award is money now promised; a historical award
      // in a spreadsheet already had its cheques, and minting instalments for it
      // would put money on the books twice — once as the file's history and once
      // as a promise nobody is waiting for.
      if (g.status === "awarded") {
        await trun("UPDATE grants SET awarded_at=COALESCE(awarded_at, NOW()) WHERE id=? AND org_id=?", [id, orgId]);
      }
      written.push({ id, line: g.line, funderName: g.funderName, program: g.program, status: g.status });
    }
  });

  const pipelineCents = plan.pipelineCents;
  res.status(201).json({
    source: plan.source, mapping: plan.mapping, unrecognised: plan.unrecognised,
    counts: { ...plan.counts, created: created.length },
    created, grants: written, refused: plan.refused,
    pipelineCents, pipeline: toDollars(pipelineCents),
    sentence: I.importSentence({ grants: written.length, funders: plan.counts.funders,
      created: created.length, skipped: plan.counts.skipped, refused: plan.refused.length,
      pipelineCents }, money.formatCentsPlain),
    writes: plan.writes, doesNotWrite: plan.doesNotWrite,
    wrote: true,
  });
}));

// GET /grants/import/sources — what Steward can read, and how sure it is of each.
app.get("/grants/import/sources", requireAuth, wrap(async (req, res) => {
  const I = await grantImportMod();
  res.json({ sources: I.GRANT_SOURCES, fields: I.GRANT_FIELD_KEYS,
             columns: I.GRANT_COLUMNS, statusVocabulary: I.SOURCE_STATUS });
}));

// ── BUILD-100 (grants) Part 5 — THE AGENT DRAFTS A REPORT OUTLINE ───────────
// "Draft the report outline for the Sunrise grant." What comes back is built
// ONLY from that grant's own rows: what was promised, what the funder paid, what
// was spent, and the programme's giving and people in the period.
//
// shared/grantOutline.js is the guarantee — no numeric field anywhere in the
// schema, so every figure a reader sees is rendered HERE from the rows. And the
// rule this part adds: an OUTCOME claim with no citation is dropped and counted,
// because Steward holds no programme outcomes and a grant report is precisely
// where a fluent model will invent one.
async function grantOutlineMod() { return import("../shared/grantOutline.js"); }

// WHAT THE MODEL IS HANDED, AND NOTHING ELSE — the same shape as the prospect
// brief's row gathering, so there is one idea in this product about how a model
// is grounded rather than two.
async function grantOutlineRowsFor(orgId, grantId, { from = null, to = null } = {}) {
  const R = await restrictedMod();
  const M = await grantMsMod();
  const V = await import("../shared/vocabulary.js");
  const org = await orgTz(orgId);
  const [orgRow] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const t = V.makeT(orgRow && orgRow.vocabulary_json);
  const today = orgToday(org);                                          // ORG_TZ_SEAM_OK

  const rows = await grantMoneyRows(orgId, "AND g.id = ?", [grantId]);
  if (!rows.length) return null;
  const [g] = await query(
    `SELECT g.*, d.name AS funder_name, u.name AS officer_name, f.name AS fund_name
       FROM grants g
       LEFT JOIN donors d ON d.id = g.funder_donor_id AND d.org_id = g.org_id
       LEFT JOIN users u ON u.id = g.officer_id AND u.org_id = g.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id AND f.org_id = g.org_id
      WHERE g.id=? AND g.org_id=?`, [grantId, orgId]);
  const balance = grantBalanceFrom(R, rows[0], today);

  // THE PERIOD. Default is the whole life of the award — from the day it was
  // awarded (else the day the grant was opened) to today. A report period the
  // caller states wins, because a funder names its own.
  const CIVIL = /^\d{4}-\d{2}-\d{2}$/;
  const start = CIVIL.test(String(from || "")) ? String(from)
    : (g.awarded_at ? orgToday(org, g.awarded_at)                       // ORG_TZ_SEAM_OK
       : (g.created_at ? orgToday(org, g.created_at) : today));         // ORG_TZ_SEAM_OK
  const end = CIVIL.test(String(to || "")) ? String(to) : today;

  const refs = new Set([`grant:${g.id}`]);
  const lines = [];
  const fundWord = t("fund_singular") || "fund";

  // 1 — THE GRANT ITSELF: what was promised, in the proposal's own fields.
  lines.push(`grant:${g.id} — a grant from ${g.funder_name || "a funder"} for "${g.program || "no programme named"}", `
    + `requested ${money.formatCentsPlain(toCents(g.amount_requested) || 0)}, `
    + `awarded ${money.formatCentsPlain(balance.awardedCents)}, currently ${g.status}`
    + `${g.fund_name ? `, designated to the ${fundWord} "${g.fund_name}"` : ""}`
    + `${g.restriction ? `, restriction "${g.restriction}"` : ""}`
    + `${g.officer_name ? `, on ${g.officer_name}'s desk` : ""}`
    + `${g.cycle_name ? `, cycle "${g.cycle_name}"` : ""}. `
    + `The reporting period here is ${start} to ${end}.`
    + (g.notes ? ` The note on the grant reads: "${String(g.notes).slice(0, 800)}"` : ""));

  // 2 — THE DOCUMENTS. NOTHING IS PARSED: Steward stores a file, types it and
  // dates it, so the row says a proposal EXISTS — never what it said. A model
  // handed a filename must not be able to quote a document nobody read.
  for (const d of await query(
    `SELECT id, doc_type, file_name, uploaded_at FROM grant_documents
      WHERE org_id=? AND grant_id=? ORDER BY uploaded_at ASC`, [orgId, g.id])) {
    refs.add(`document:${d.id}`);
    // THE ORG'S OWN CALENDAR, not UTC. `toISOString().slice(0,10)` on a
    // timestamptz is a day out for every org west of Greenwich after 7pm, and
    // `date-seam` is right to count it as an unrouted site (BUILD-89S's gotcha).
    const storedOn = d.uploaded_at ? orgToday(org, d.uploaded_at) : null;     // ORG_TZ_SEAM_OK
    lines.push(`document:${d.id} — a ${grantDocs.docTypeLabel(d.doc_type).toLowerCase()} on file, "${d.file_name}", `
      + `stored ${storedOn || "on a date the record does not carry"}. `
      + `Steward has NOT read this file; only that it exists is known.`);
  }

  // 3 — WHAT THE FUNDER PAID: payments applied to the award, each its own row.
  for (const p of g.award_pledge_id ? await query(
    `SELECT id, amount, date FROM gifts WHERE org_id=? AND pledge_id=? ORDER BY date ASC`,
    [orgId, g.award_pledge_id]) : []) {
    refs.add(`payment:${p.id}`);
    lines.push(`payment:${p.id} — ${money.formatCentsPlain(toCents(p.amount) || 0)} received on ${p.date}, applied to this award.`);
  }
  lines.push(`grant:${g.id} — of the award, ${money.formatCentsPlain(balance.receivedCents)} has been received and `
    + `${money.formatCentsPlain(balance.outstandingCents)} is still owed by the funder.`);

  // 4 — WHAT WAS SPENT AGAINST IT. Entered by hand; the row says so, because a
  // report that implies a bank feed is a report claiming more than it can.
  for (const s of await query(
    `SELECT id, amount, spent_on, description FROM grant_spend
      WHERE org_id=? AND grant_id=? ORDER BY spent_on ASC`, [orgId, g.id])) {
    refs.add(`spend:${s.id}`);
    lines.push(`spend:${s.id} — ${money.formatCentsPlain(toCents(s.amount) || 0)} spent on ${s.spent_on}: "${s.description}". Entered by hand, not read from a bank.`);
  }
  lines.push(`grant:${g.id} — ${money.formatCentsPlain(balance.spentCents)} has been recorded as spent against this award, `
    + `leaving ${money.formatCentsPlain(balance.remainingCents)} of the money received still to spend.`);

  // 5 — THE PROGRAMME'S OWN GIVING IN THE PERIOD. Only gifts to THIS grant's
  // fund: a gift to another fund is not evidence about this programme.
  let fundGifts = [], givers = [];
  if (g.fund_id) {
    fundGifts = await query(
      `SELECT gi.id, gi.amount, gi.date, gi.donor_id, d.name AS donor_name
         FROM gifts gi LEFT JOIN donors d ON d.id = gi.donor_id AND d.org_id = gi.org_id
        WHERE gi.org_id=? AND gi.fund_id=? AND gi.is_sample IS NOT TRUE
          AND gi.date >= ? AND gi.date <= ?
        ORDER BY gi.amount DESC NULLS LAST, gi.id LIMIT 25`, [orgId, g.fund_id, start, end]);
    for (const gi of fundGifts) {
      refs.add(`gift:${gi.id}`);
      lines.push(`gift:${gi.id} — ${money.formatCentsPlain(toCents(gi.amount) || 0)} to the ${fundWord} "${g.fund_name}" on ${gi.date}`
        + `${gi.donor_name ? ` from ${gi.donor_name}` : ""}.`);
    }
    givers = await query(
      `SELECT d.id, d.name, COUNT(gi.id) AS gifts, SUM(gi.amount) AS total
         FROM gifts gi JOIN donors d ON d.id = gi.donor_id AND d.org_id = gi.org_id
        WHERE gi.org_id=? AND gi.fund_id=? AND gi.is_sample IS NOT TRUE
          AND gi.date >= ? AND gi.date <= ? AND d.deleted_at IS NULL
        GROUP BY d.id, d.name ORDER BY SUM(gi.amount) DESC NULLS LAST, d.id LIMIT 12`,
      [orgId, g.fund_id, start, end]);
    for (const p of givers) {
      refs.add(`person:${p.id}`);
      lines.push(`person:${p.id} — ${p.name} gave ${Number(p.gifts)} ${Number(p.gifts) === 1 ? "gift" : "gifts"} `
        + `totalling ${money.formatCentsPlain(toCents(p.total) || 0)} to this ${fundWord} in the period.`);
    }
  }

  // 6 — THE DEADLINES ON IT, so the outline can say what is due and when.
  for (const ms of await query(
    `SELECT id, kind, due_date, state, notes FROM grant_milestones
      WHERE org_id=? AND grant_id=? ORDER BY due_date ASC`, [orgId, g.id])) {
    refs.add(`milestone:${ms.id}`);
    lines.push(`milestone:${ms.id} — ${M.milestoneStepLabel({ kind: ms.kind, funderName: g.funder_name, program: g.program })}, `
      + `due ${ms.due_date}, currently ${ms.state}`
      + `${String(ms.notes || "").trim() ? `. The note on it: "${String(ms.notes).slice(0, 300)}"` : "."}`);
  }

  // 7 — CONVERSATIONS WITH THE FUNDER, quoted rather than summarised away.
  if (g.funder_donor_id) {
    for (const i of await query(
      `SELECT id, type, date, note, logged_by_name FROM interactions
        WHERE org_id=? AND donor_id=? AND COALESCE(note,'') <> ''
        ORDER BY date DESC, created_at DESC LIMIT 5`, [orgId, g.funder_donor_id])) {
      refs.add(`conversation:${i.id}`);
      lines.push(`conversation:${i.id} — ${i.type} on ${i.date}${i.logged_by_name ? ` logged by ${i.logged_by_name}` : ""}: "${String(i.note).slice(0, 500)}"`);
    }
  }

  // THE GROUNDED NUMERIC SET, through the money seam (never a bare Math.round on
  // a dollars value — `tests/money-cents.test.js` is right about that shape
  // wherever it appears, and a text check is not an exemption).
  const grounded = [];
  const push = v => { const c = toCents(v); if (c != null) { grounded.push(toDollars(c), c); } };
  push(g.amount_requested); push(g.amount_awarded);
  for (const k of ["awardedCents", "receivedCents", "spentCents", "outstandingCents", "remainingCents"]) {
    grounded.push(balance[k], toDollars(balance[k]));
  }
  for (const gi of fundGifts) push(gi.amount);
  for (const p of givers) { push(p.total); grounded.push(Number(p.gifts) || 0); }
  grounded.push(fundGifts.length, givers.length);
  for (const l of lines) for (const m of String(l).matchAll(/\d+(?:\.\d+)?/g)) grounded.push(Number(m[0]));

  return {
    grant: g, org: orgRow, t, balance, refs, lines,
    grounded: [...new Set(grounded.filter(Number.isFinite))],
    period: { from: start, to: end },
    counts: { documents: refs.size, fundGifts: fundGifts.length, people: givers.length },
  };
}

// GET /grants/:id/outline-rows — EXACTLY what the model would be handed. Like
// the brief's, this is not a test seam: the outline's promise is that every
// sentence rests on a row you can open, and this is that list — provable with no
// API key configured at all.
app.get("/grants/:id/outline-rows", requireAuth, wrap(async (req, res) => {
  const ctx = await grantOutlineRowsFor(req.user.orgId, req.params.id,
    { from: req.query.from, to: req.query.to });
  if (!ctx) return res.status(404).json({ error: "Grant not found" });
  res.json({
    grantId: ctx.grant.id, funderName: ctx.grant.funder_name || "", program: ctx.grant.program || "",
    period: ctx.period, refs: [...ctx.refs], lines: ctx.lines, groundedValues: ctx.grounded,
  });
}));

// POST /grants/:id/report-outline — draft it, validate it, log it as an agent run.
app.post("/grants/:id/report-outline", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const O = await grantOutlineMod();
  const TH = await thresholdsMod();
  const orgId = req.user.orgId;
  // THE GRANT IS CHECKED FIRST, and that order is the point — the same defect
  // the prospect brief paid for (BUILD-99): running the key gate first answers
  // 503 to a cross-tenant probe instead of 404, telling the caller both that the
  // route exists and what Steward's key state is.
  const ctx = await grantOutlineRowsFor(orgId, req.params.id, { from: req.body.from, to: req.body.to });
  if (!ctx) return res.status(404).json({ error: "Grant not found" });

  const gate = await agentGate(orgId);
  if (!gate.ok) return res.status(503).json({ error: "outline_unavailable", reason: gate.reason });

  const runId = "arun_" + uuid().slice(0, 10);
  await run(`INSERT INTO agent_runs (id,org_id,status,plan,read_summary) VALUES (?,?,?,?,?)`,
    [runId, orgId, "running", JSON.stringify({ kind: "grant_report_outline", grantId: ctx.grant.id }),
     `${ctx.refs.size} rows on the ${ctx.grant.funder_name || "funder"} grant`]);

  const system = [
    "You are drafting the OUTLINE of a report to a funder about a grant. A human will write the report from it and send it.",
    "",
    "You are given ROWS from this organisation's own records. Each row starts with a reference of the form kind:id.",
    "Write short, plain sentences about what those rows say. Every sentence must cite the references it rests on, exactly as given.",
    "",
    "RULES, and the first one is the whole job:",
    "- YOU MAY NOT STATE AN OUTCOME. This organisation's records hold money, dates, documents and people — they do not hold",
    "  attendance, results, or what changed for anybody. Do not write that anyone was served, reached, helped or improved.",
    "  The outcomes section is a PROMPT to the human who knows; say plainly that the records cannot supply it.",
    "- Use no figure that is not in the rows you were handed, and state no rule about how grants or giving work.",
    "- A document row means a file EXISTS. You have not read it. Never say what a proposal or report said.",
    "- Money still owed by the funder is not money received, and money received is not money spent. Keep them apart.",
    "- Quote a conversation rather than summarising away the words the officer chose.",
    "- Leave a section out if the rows say nothing about it. Do not pad.",
    "- The headline names the grant and the period, and contains no figure.",
    "",
    "The sections you may use, and what each rests on:",
    ...O.OUTLINE_SECTIONS.map(s => `- ${s.heading} — ${s.source || "NOTHING IN THE RECORDS. Say so; do not invent it."}`),
  ].join("\n");
  const user = [
    `The rows, on the ${ctx.grant.funder_name || "funder"} grant for "${ctx.grant.program || "no programme named"}", `
      + `period ${ctx.period.from} to ${ctx.period.to}:`,
    "", ...ctx.lines, "", "Draft the outline.",
  ].join("\n");

  let raw = null, err = null;
  try {
    const client = new Anthropic();
    const msg = await client.messages.create({
      model: AGENT_MODEL, max_tokens: 2000, system,
      tools: [{ name: "outline", description: "The report outline a human writes the report from.", strict: true, input_schema: O.OUTLINE_SCHEMA }],
      tool_choice: { type: "tool", name: "outline" },
      messages: [{ role: "user", content: user }],
    });
    raw = (msg.content || []).find(b => b.type === "tool_use" && b.name === "outline")?.input || null;
  } catch (e) { err = e.message || String(e); }

  if (!raw) {
    await run("UPDATE agent_runs SET status='failed', finished_at=NOW(), error=? WHERE id=?", [err || "no outline returned", runId]);
    return res.status(502).json({ error: "The outline could not be drafted just now.", runId });
  }

  const checked = O.validateOutline(raw, {
    rows: ctx.refs,
    ungrounded: text => TH.ungroundedClaims(text, { groundedValues: ctx.grounded }).map(c => c.raw),
  });
  const payload = grantOutlinePayload(ctx, checked);
  // THE FIGURES ARE STORED, NOT RECOMPUTED (the BUILD-87 Part 1 rule). A payment
  // arriving next week must not silently change what an outline drafted today
  // says the funder had paid — a draft somebody is working from is evidence of a
  // moment, and one that edits itself is worth less than none.
  await run(
    `UPDATE agent_runs SET status='done', finished_at=NOW(), actions=?, declined=?, withheld=?, withheld_reason=? WHERE id=?`,
    [JSON.stringify({ outline: checked, grantId: ctx.grant.id, period: ctx.period, payload }),
     checked.droppedCount, checked.droppedCount, checked.droppedSentence, runId]);

  res.json({ runId, ...payload });
}));

// ONE shape for the outline, read by the POST and by the read-back — a second
// assembly is a second place for the figures to disagree with the rows.
function grantOutlinePayload(ctx, checked) {
  return {
    grantId: ctx.grant.id, funderName: ctx.grant.funder_name || "", program: ctx.grant.program || "",
    period: ctx.period,
    headline: checked.headline, sections: checked.sections,
    // EVERY FIGURE IS STEWARD'S, rendered from the rows the model was handed.
    figures: {
      awarded: ctx.balance.awarded, received: ctx.balance.received,
      spent: ctx.balance.spent, outstanding: ctx.balance.outstanding, remaining: ctx.balance.remaining,
      awardedCents: ctx.balance.awardedCents, receivedCents: ctx.balance.receivedCents,
      spentCents: ctx.balance.spentCents, outstandingCents: ctx.balance.outstandingCents,
      remainingCents: ctx.balance.remainingCents,
      programmeGifts: ctx.counts.fundGifts, programmePeople: ctx.counts.people,
    },
    balanceSentence: ctx.balance.sentence,
    dropped: checked.dropped, droppedSentence: checked.droppedSentence,
    outcomesPrompt: checked.outcomesPrompt,
    rowsRead: ctx.refs.size, footer: checked.footer,
  };
}

// GET /grant-outlines/:runId — read one back. It is an agent run, so it is on
// the Activity screen with everything else the agent did.
app.get("/grant-outlines/:runId", requireAuth, wrap(async (req, res) => {
  const [r] = await query("SELECT * FROM agent_runs WHERE id=? AND org_id=?", [req.params.runId, req.user.orgId]);
  if (!r || !r.actions || !r.actions.payload) return res.status(404).json({ error: "Outline not found" });
  res.json({ runId: r.id, writtenAt: r.finished_at, ...r.actions.payload });
}));

app.get("/grants/:id/manual-match", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT id, funder, program, amount, status FROM grants WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Grant not found" });
  const g = rows[0];
  const cutoff = new Date(Date.now() - 180 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const funder = String(g.funder || "").trim().toLowerCase();
  const amt = parseFloat(g.amount) || 0;
  const matches = await query(
    `SELECT id, date, description, vendor_donor, amount, fund_id
     FROM fin_transactions
     WHERE org_id=? AND source='manual' AND type='income' AND grant_id IS NULL AND date >= ?
       AND (
         (vendor_donor <> '' AND (lower(vendor_donor) LIKE ? OR ? LIKE '%' || lower(vendor_donor) || '%'))
         OR lower(description) LIKE ?
         OR (? > 0 AND amount = ?)
       )
     ORDER BY date DESC LIMIT 5`,
    [req.user.orgId, cutoff, `%${funder}%`, funder, `%${funder}%`, amt, amt]
  );
  res.json({ grantId: g.id, funder: g.funder, program: g.program || "", amount: amt, matches: matches.map(m => ({ ...m, amount: parseFloat(m.amount) })) });
}));

