// BUILD-54 §2 — the donor-facing fields ride the SAME create/edit routes the
// CRM campaign form uses (setup happens where the campaign is created — no
// separate configuration screen to forget). Shared validator for both routes;
// returns { sets, params } column assignments or { status, body } to reject.
async function parseDonorFacingCampaignFields(b, orgId) {
  const sets = [], params = [];
  if (b.donorFacingName !== undefined) { sets.push("donor_facing_name = ?"); params.push(String(b.donorFacingName || "").trim().slice(0, 120) || null); }
  if (b.donorDescription !== undefined) { sets.push("donor_description = ?"); params.push(String(b.donorDescription || "").trim().slice(0, 600) || null); }
  if (b.donorStory !== undefined) {
    const v = validateStoryBlocks(b.donorStory);
    if (v.error) return { status: 400, body: { error: v.error, message: "The story must be paragraphs, headings, and lists — no HTML or embeds." } };
    sets.push("donor_story = ?"); params.push(v.blocks && v.blocks.length ? JSON.stringify(v.blocks) : null);
  }
  if (b.heroImageData !== undefined) {
    const h = await storeCampaignHero(orgId, b.heroImageData);
    if (h.error) return { status: 400, body: { error: h.error, message: h.message } };
    if (h.url !== undefined) { sets.push("hero_image_url = ?"); params.push(h.url); }
  }
  // BUILD-65 Part 3 — non-destructive crop + focal for the hero (same library
  // and validation as the banner: parseCrop; a crop wins, focal is the fallback).
  if (b.heroCrop !== undefined) {
    if (b.heroCrop === "" || b.heroCrop == null) { sets.push("hero_crop = NULL"); }
    else {
      const c = parseCrop(b.heroCrop);
      if (!c) return { status: 400, body: { error: "bad_crop", message: "Crop must be a rectangle {x,y,w,h} within the image." } };
      sets.push("hero_crop = ?"); params.push(JSON.stringify(c));
    }
  }
  for (const [key, col] of [["heroFocalX", "hero_focal_x"], ["heroFocalY", "hero_focal_y"]]) {
    if (b[key] === undefined) continue;
    const nn = Number(b[key]);
    if (!Number.isFinite(nn)) return { status: 400, body: { error: "bad_focal", message: "Focal point must be a number between 0 and 1." } };
    sets.push(`${col} = ?`); params.push(Math.min(1, Math.max(0, nn)));
  }
  if (b.goalProgressPublic !== undefined) { sets.push("goal_progress_public = ?"); params.push(b.goalProgressPublic === true); }
  return { sets, params };
}

app.post("/fundraising/campaigns", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, goalAmount, startDate, endDate, goalCategory, parentGoalId } = req.body;
  if (!name || !name.trim()) return res.status(400).json({ error: "Name required" });
  const goal = parseFloat(goalAmount);
  if (!Number.isFinite(goal) || goal <= 0) return res.status(400).json({ error: "Goal amount must be a positive number" });
  const category = GOAL_CATEGORIES.includes(goalCategory) ? goalCategory : "project";
  // A parent goal, if given, must be another goal'd campaign in this org.
  let parent = null;
  if (parentGoalId) {
    const p = await query("SELECT id FROM campaigns WHERE id=? AND org_id=? AND goal_amount IS NOT NULL AND goal_amount > 0", [parentGoalId, req.user.orgId]);
    if (!p.length) return res.status(400).json({ error: "parentGoalId must be an existing goal in this org" });
    parent = parentGoalId;
  }
  const df = await parseDonorFacingCampaignFields(req.body, req.user.orgId);
  if (df.status) return res.status(df.status).json(df.body);
  const id = "cmp_" + uuid().slice(0, 8);
  await run(
    `INSERT INTO campaigns (id,org_id,name,type,subject,body,status,segment,goal_amount,start_date,end_date,goal_category,parent_goal_id,recipient_count,open_count,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)`,
    [id, req.user.orgId, name.trim(), "appeal", "", "", "draft", JSON.stringify({}), goal, startDate || null, endDate || null, category, parent, actor(req).id, actor(req).name]
  );
  if (df.sets.length) {
    await run(`UPDATE campaigns SET ${df.sets.join(", ")} WHERE id = ? AND org_id = ?`, [...df.params, id, req.user.orgId]);
  }
  if (req.body.heroImageData !== undefined) {
    const [c] = await query(`SELECT hero_image_url FROM campaigns WHERE id = ?`, [id]);
    await recordAssetPointerHistory(req.user.orgId, "campaign.hero", id, null, c?.hero_image_url || null, req.user);
  }
  const rows = await fundraisingCampaignRows(req.user.orgId);
  res.status(201).json(rows.find(r => r.id === id) || { id });
}));

app.put("/fundraising/campaigns/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, goalAmount, startDate, endDate, goalCategory, parentGoalId } = req.body;
  const existing = await query("SELECT id, hero_image_url FROM campaigns WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Campaign not found" });
  if (goalAmount !== undefined) {
    const goal = parseFloat(goalAmount);
    if (!Number.isFinite(goal) || goal <= 0) return res.status(400).json({ error: "Goal amount must be a positive number" });
  }
  if (goalCategory !== undefined && !GOAL_CATEGORIES.includes(goalCategory)) {
    return res.status(400).json({ error: "goalCategory must be annual, project, or capital" });
  }
  // A goal can't be its own parent, and the parent must exist in this org.
  let parentUpdate = null, parentProvided = parentGoalId !== undefined;
  if (parentProvided && parentGoalId) {
    if (parentGoalId === req.params.id) return res.status(400).json({ error: "A goal cannot be its own parent" });
    const p = await query("SELECT id FROM campaigns WHERE id=? AND org_id=? AND goal_amount IS NOT NULL AND goal_amount > 0", [parentGoalId, req.user.orgId]);
    if (!p.length) return res.status(400).json({ error: "parentGoalId must be an existing goal in this org" });
    parentUpdate = parentGoalId;
  }
  const df = await parseDonorFacingCampaignFields(req.body, req.user.orgId);
  if (df.status) return res.status(df.status).json(df.body);
  await run(
    `UPDATE campaigns SET name=COALESCE(?,name), goal_amount=COALESCE(?,goal_amount),
       start_date=?, end_date=?, goal_category=COALESCE(?,goal_category),
       parent_goal_id=CASE WHEN ? THEN ? ELSE parent_goal_id END, updated_at=NOW() WHERE id=? AND org_id=?`,
    [name || null, goalAmount !== undefined ? parseFloat(goalAmount) : null,
     startDate || null, endDate || null, goalCategory || null,
     parentProvided, parentUpdate, req.params.id, req.user.orgId]
  );
  if (df.sets.length) {
    await run(`UPDATE campaigns SET ${df.sets.join(", ")} WHERE id = ? AND org_id = ?`, [...df.params, req.params.id, req.user.orgId]);
    // A replaced/cleared hero leaves no orphaned asset (content addressing —
    // one photo may back several campaigns; reference-counted like impact).
    // BUILD-56: prune = soft delete + a pointer-history row.
    if (req.body.heroImageData !== undefined) {
      await pruneCampaignAssets(req.user.orgId);
      const [c] = await query(`SELECT hero_image_url FROM campaigns WHERE id = ?`, [req.params.id]);
      await recordAssetPointerHistory(req.user.orgId, "campaign.hero", req.params.id,
        existing[0].hero_image_url || null, c?.hero_image_url || null, req.user);
    }
  }
  const rows = await fundraisingCampaignRows(req.user.orgId);
  res.json(rows.find(r => r.id === req.params.id) || { id: req.params.id });
}));

// Segment → recipient list. Shared by the manual send route and the
// scheduled-campaign job (BUILD-06 Phase C) so both resolve audiences
// identically. Note the predicates read d.stage — the DB column — matching
// what the client's SegmentPicker previews (fixed same pass; it read a
// nonexistent d.pipeline_stage and showed 0 for stage segments).
// ── BUILD-97 — AUDIENCES: THE THINGS WITH NAMES ───────────────────────────
// The registry is shared/audiences.js so the rail and the resolver cannot
// disagree about what exists. Loaded through the depositMod() convention
// rather than a top-level .then that assigns a module-scope binding — that
// leaves a window at boot where the list is empty and every audience is
// unknown (the BUILD-95 §5B part 1 lesson).
let _audMod = null;
async function audienceMod() {
  if (!_audMod) _audMod = await import("../shared/audiences.js");
  return _audMod;
}

// ONE donor query, every audience counted off it. See filterBySegment.
async function audienceRoster(orgId) {
  const A = await audienceMod();
  const donors = await query(
    "SELECT * FROM donors WHERE org_id = ? AND email IS NOT NULL AND email != '' AND deleted_at IS NULL",
    [orgId]);
  const saved = await query(
    "SELECT id, name, description, segment, created_at FROM audiences WHERE org_id=? ORDER BY LOWER(name)",
    [orgId]).catch(() => []);

  const builtins = A.BUILT_IN_AUDIENCES.map(a => ({
    id: a.id, name: a.name, description: a.description, kind: "builtin", tone: a.tone,
    mode: a.mode,
    count: filterBySegment(donors, { mode: a.mode }).length,
    // WHERE THESE PEOPLE LIVE. Allie should never have to wonder where her
    // volunteers are kept — an audience names the screen its people are on.
    // FIX-1 D/C — Donors shows donors now, so volunteers live in the
    // Volunteers hub and staff and board under Settings; nobody is on one
    // list any more, so "everyone" names the three places.
    livesOn: a.mode === "everyone" ? { tab: "donors", filter: null, label: "Donors, Volunteers, and Settings for staff and board" }
           : a.mode === "donors" ? { tab: "donors", filter: "donor", label: "Donors" }
           : a.mode === "volunteers" ? { tab: "volunteers", filter: null, label: "Volunteers" }
           : a.mode === "staff_board" ? { tab: "settings", filter: null, label: "Settings, under Organization" }
           : { tab: "donors", filter: a.mode, label: "Donors, filtered to " + a.name.toLowerCase() },
  }));

  const custom = saved.map(r => {
    const seg = typeof r.segment === "string" ? JSON.parse(r.segment || "{}") : (r.segment || {});
    return {
      id: r.id, name: r.name, description: r.description || "", kind: "saved", tone: "greenMid",
      mode: seg.mode, segment: seg, created_at: r.created_at,
      count: filterBySegment(donors, seg).length,
      livesOn: { tab: "donors", filter: seg.mode, label: "Donors" },
    };
  });

  return {
    audiences: [...builtins, ...custom],
    // The reach line. DISTINCT people, not the sum of the audiences — a
    // volunteer who gives is in two of them and must be one person here.
    reach: donors.length,
  };
}

app.get("/audiences", requireAuth, wrap(async (req, res) => {
  res.json(await audienceRoster(req.user.orgId));
}));

app.post("/audiences", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const A = await audienceMod();
  const v = A.validateAudience(req.body || {});
  if (!v.ok) return res.status(400).json({ error: v.errors[0], errors: v.errors });
  const seg = A.segmentFor({ mode: v.mode, stages: req.body.stages, tiers: req.body.tiers });
  const id = "aud_" + uuid().slice(0, 8);
  try {
    await run(`INSERT INTO audiences (id, org_id, name, description, segment, created_by, created_by_name)
               VALUES (?,?,?,?,?,?,?)`,
      [id, req.user.orgId, v.name, v.description || null, JSON.stringify(seg),
       req.user.userId, req.user.name || req.user.email || null]);
  } catch (err) {
    if (err.code === "23505") return res.status(409).json({ error: "You already have an audience called that." });
    throw err;
  }
  const [row] = await query("SELECT * FROM audiences WHERE id=?", [id]);
  res.status(201).json(row);
}));

app.patch("/audiences/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const A = await audienceMod();
  const [existing] = await query("SELECT * FROM audiences WHERE id=? AND org_id=?",
    [req.params.id, req.user.orgId]);
  if (!existing) return res.status(404).json({ error: "Not found" });
  const prev = typeof existing.segment === "string" ? JSON.parse(existing.segment || "{}") : existing.segment;
  const v = A.validateAudience({
    name: req.body.name !== undefined ? req.body.name : existing.name,
    description: req.body.description !== undefined ? req.body.description : existing.description,
    mode: req.body.mode !== undefined ? req.body.mode : prev.mode,
    stages: req.body.stages !== undefined ? req.body.stages : prev.stages,
    tiers: req.body.tiers !== undefined ? req.body.tiers : prev.tiers,
  });
  if (!v.ok) return res.status(400).json({ error: v.errors[0], errors: v.errors });
  const seg = A.segmentFor({ mode: v.mode,
    stages: req.body.stages !== undefined ? req.body.stages : prev.stages,
    tiers: req.body.tiers !== undefined ? req.body.tiers : prev.tiers });
  try {
    await run("UPDATE audiences SET name=?, description=?, segment=?, updated_at=NOW() WHERE id=? AND org_id=?",
      [v.name, v.description || null, JSON.stringify(seg), req.params.id, req.user.orgId]);
  } catch (err) {
    if (err.code === "23505") return res.status(409).json({ error: "You already have an audience called that." });
    throw err;
  }
  const [row] = await query("SELECT * FROM audiences WHERE id=?", [req.params.id]);
  res.json(row);
}));

app.delete("/audiences/:id", requireAuth, wrap(async (req, res) => {
  const r = await run("DELETE FROM audiences WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!r.changes) return res.status(404).json({ error: "Not found" });
  // A campaign already sent keeps its recipient rows, so history is intact.
  // A DRAFT pointing at this audience now resolves to nobody rather than to
  // everybody — resolveSegmentSpec returns an empty manual list for a missing
  // audience, which is the BUILD-88c rule held at the one place it matters.
  res.json({ deleted: true });
}));

// The hub's single read. One payload so the landing screen is one request
// rather than five that arrive in a different order every time.
app.get("/communications/hub", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [roster, campaigns, seqs] = await Promise.all([
    audienceRoster(orgId),
    query(`SELECT id, name, subject, status, recipient_count, open_count, sent_at, created_at
             FROM campaigns WHERE org_id=? ORDER BY COALESCE(sent_at, created_at) DESC LIMIT 6`, [orgId]),
    query(`SELECT s.id, s.name, s.status,
                  (SELECT COUNT(*) FROM sequence_enrollments e WHERE e.sequence_id=s.id AND e.status='active') AS active
             FROM sequences s WHERE s.org_id=? AND s.trigger <> 'onboarding'
            ORDER BY s.created_at DESC LIMIT 5`, [orgId]).catch(() => []),
  ]);
  const sent = campaigns.filter(c => c.status === "sent");
  const totalSent = sent.reduce((n, c) => n + (c.recipient_count || 0), 0);
  const totalOpen = sent.reduce((n, c) => n + (c.open_count || 0), 0);
  res.json({
    ...roster,
    campaigns,
    sequences: seqs.map(s => ({ ...s, active: parseInt(s.active, 10) || 0 })),
    stats: {
      totalSent,
      openRate: totalSent > 0 ? Math.round(totalOpen / totalSent * 100) : null,
      activeSequences: seqs.filter(s => s.status === "active").length,
    },
  });
}));

app.post("/campaigns/:id/send", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const campaigns = await query(
    "SELECT * FROM campaigns WHERE id = ? AND org_id = ?",
    [req.params.id, req.user.orgId]
  );
  if (!campaigns.length) return res.status(404).json({ error: "Campaign not found" });
  const campaign = campaigns[0];
  if (campaign.status === "sent") return res.status(400).json({ error: "Campaign already sent" });
  // BUILD-94 Part 4 — NO ADDRESS, NO SEND. Before the recipients are resolved,
  // before anything is marked sending: nothing in bulk leaves without one.
  const addrGate = await bulkSendAddressGate(req.user.orgId);
  if (!addrGate.ok) return res.status(400).json({ error: addrGate.reason, message: addrGate.message });

  const orgs = await query("SELECT * FROM orgs WHERE id = ?", [req.user.orgId]);
  const org = orgs[0];
  const donors = await resolveCampaignRecipients(campaign, req.user.orgId);

  // Mark as sending and respond immediately (non-blocking)
  await run("UPDATE campaigns SET status='sending', updated_at=NOW() WHERE id=?", [campaign.id]);
  res.json({ queued: true, recipientCount: donors.length });

  setImmediate(() => runCampaignSend(campaign, org, donors));
}));

