// markDonorsForGeocoding(orgId, opts) — recompute every affected donor's
// address key and set the status the key implies. A row whose key is unchanged
// AND already `ok` is left alone: that is the caching requirement, enforced in
// SQL rather than trusted to a caller.
//   · no address at all      → 'no_address', coordinates cleared
//   · key changed / new      → 'pending'
//   · key same and 'ok'      → untouched, never looked up twice
// `donorIds` scopes it to one write; omitted, it sweeps the org (used after an
// import, where naming every id would be a 25,000-element array).
async function markDonorsForGeocoding(orgId, { donorIds = null } = {}) {
  const scope = donorIds && donorIds.length ? " AND id = ANY(?)" : "";
  const params = donorIds && donorIds.length ? [orgId, donorIds] : [orgId];
  const rows = await query(
    `SELECT id, address, address2, city, state, zip, country, geocode_key, geocode_status
       FROM donors WHERE org_id = ? AND deleted_at IS NULL${scope}`, params);
  const toPending = [], toNoAddress = [];
  const keyById = new Map();
  for (const d of rows) {
    const key = geocode.addressKey(d);
    if (!key) {
      if (d.geocode_status !== "no_address") toNoAddress.push(d.id);
      continue;
    }
    if (d.geocode_status === "ok" && d.geocode_key === key) continue;   // never twice
    if (d.geocode_status === "pending" && d.geocode_key === key) continue;
    toPending.push(d.id);
    keyById.set(d.id, key);
  }
  const CH = 1000;
  for (let i = 0; i < toNoAddress.length; i += CH)
    await run(`UPDATE donors SET geocode_status='no_address', geocode_key=NULL, latitude=NULL, longitude=NULL,
                 geocoded_at=NOW(), geocode_provider=NULL WHERE org_id=? AND id = ANY(?)`,
              [orgId, toNoAddress.slice(i, i + CH)]);
  for (let i = 0; i < toPending.length; i += CH) {
    const slice = toPending.slice(i, i + CH);
    // One statement per chunk, key per row via an unnested pair list.
    await run(`UPDATE donors SET geocode_status='pending', geocode_key=v.key, latitude=NULL, longitude=NULL
                 FROM (SELECT * FROM UNNEST(?::text[], ?::text[]) AS t(id, key)) AS v
                WHERE donors.id = v.id AND donors.org_id = ?`,
              [slice, slice.map(id => keyById.get(id)), orgId]);
  }
  return { pending: toPending.length, noAddress: toNoAddress.length, scanned: rows.length };
}

// Only the mapped column, and only a string. Anything else is not a URL and
// the row is left alone rather than queued to fail.
function photoImportUrl(d) {
  const v = d && d.photo;
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

// POST /photos/run — drive the queue for the caller's org NOW. The ops/test
// hook, same bar as /geocode/run: admin, org-scoped, and the only way a suite
// gets a deterministic drain without waiting on a tick.
app.post("/photos/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  res.json(await processPhotoQueue({ orgId: req.user.orgId, limit: Math.min(parseInt(req.body?.limit, 10) || PHOTO_FETCH_BUDGET, 1000) }));
}));

// POST /geocode/run — drive the queue for the caller's org NOW. The ops/test
// hook, same bar as POST /nudges/run. {mark:true} re-derives every donor's
// key first (what an import does); {limit} caps the spend.
app.post("/geocode/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const marked = req.body && req.body.mark ? await markDonorsForGeocoding(req.user.orgId) : null;
  const limit = Math.min(Math.max(parseInt(req.body?.limit, 10) || GEOCODE_TICK_BUDGET, 1), 5000);
  const out = await processGeocodeQueue({ limit, orgId: req.user.orgId });
  res.json({ marked, ...out });
}));

// GET /geocode/status — what the map needs to describe itself in a sentence:
// the counts by status and whether a provider is configured at all. A read
// path, and it makes NO provider call.
app.get("/geocode/status", requireAuth, wrap(async (req, res) => {
  const cfg = geocode.providerConfig();
  const rows = await query(
    `SELECT COALESCE(geocode_status, 'pending') AS s, COUNT(*)::int AS c
       FROM donors WHERE org_id = ? AND deleted_at IS NULL GROUP BY 1`, [req.user.orgId]);
  const counts = Object.fromEntries(geocode.GEOCODE_STATUSES.map(s => [s, 0]));
  for (const r of rows) counts[r.s] = (counts[r.s] || 0) + r.c;
  res.json({ provider: cfg.name, reason: cfg.reason || null, counts,
             total: Object.values(counts).reduce((a, b) => a + b, 0) });
}));

// POST /nudges/run (requireAuth + requireAdmin) — drive the thread nudge for
// the caller's org NOW (ops/test hook, /digests/run-daily's bar). {today?}
// pins the date; the WEEKDAY rule still applies to the pinned date (that is
// how the schedule is testable) unless {force:true}; the wall-clock morning
// window deliberately does not (it would make the hook time-of-day flaky).
app.post("/nudges/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [org] = await query("SELECT id, name, legal_name, timezone, receipt_address, thread_nudge_weekends FROM orgs WHERE id=?", [req.user.orgId]);
  if (!org) return res.status(404).json({ error: "Org not found" });
  const today = (req.body && req.body.today) || orgToday(org);   // ORG_TZ_SEAM_OK
  if (!req.body?.force && !threadNudgeDayOk(org, today)) {
    return res.json({ today, skippedWeekend: true, sent: [], skipped: [] });
  }
  const out = await runThreadNudgesForOrg(org, { today, send: !(req.body && req.body.dryRun) });
  res.json({ today, ...out });
}));

// POST /step-reminders/run — the ops/test hook, same bar as POST /nudges/run.
// {today, now} pin the org's date and wall clock so the SCHEDULE is testable;
// {force:true} ignores the delivery window; {dryRun:true} composes only.
app.post("/step-reminders/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [org] = await query("SELECT id, name, legal_name, timezone, receipt_address FROM orgs WHERE id=?", [req.user.orgId]);
  if (!org) return res.status(404).json({ error: "Org not found" });
  const clock = orgTime.orgClock(org);                  // ORG_TZ_SEAM_OK
  const today = (req.body && req.body.today) || clock.date;
  const nowHHMM = (req.body && req.body.now)
    || `${String(clock.hour).padStart(2, "0")}:${String(clock.minute).padStart(2, "0")}`;
  const out = await runStepRemindersForOrg(org, {
    today, nowHHMM, force: !!req.body?.force, send: !(req.body && req.body.dryRun) });
  res.json({ today, now: nowHHMM, ...out });
}));

// GET /digests/preview — compose (never send) the caller's current digest, for
// the in-app "Week in Review" view. Scope follows the caller's role/plan.
app.get("/digests/preview", requireAuth, wrap(async (req, res) => {
  const type = req.query.type === "monthly" ? "monthly" : "weekly";
  const orgRows = await query("SELECT id, name, plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const org = orgRows[0];
  if (!org) return res.status(404).json({ error: "Org not found" });
  const tier = orgPlanTier(org);
  const [me] = await query("SELECT id, name, role FROM users WHERE id=?", [req.user.userId]);
  // Preview the most-recently-completed period (what actually gets emailed),
  // matching the tick — offset -1.
  if (type === "monthly") {
    // Core: return the caller's own monthly report as a READ-only locked
    // preview (their own gifts/portfolio — a pure read), flagged locked so the
    // client dims it behind LockedFeature instead of a bare 403 card.
    const mo = monthBounds(-1, await orgTz(org.id));   // ORG_TZ_SEAM_OK
    const report = await composeOfficerMonthly(org.id, mo, { id: me.id, name: me.name });
    return res.json({ type, window: mo, report, locked: tier !== "team" });
  }
  const wk = weekBounds(-1, await orgTz(org.id));   // ORG_TZ_SEAM_OK
  const isOfficerScope = tier === "team" && me.role !== "admin";
  const sections = await composeWeekInReview(org.id, wk, isOfficerScope ? me.id : null);
  const teamRollup = isOfficerScope ? (await composeWeekInReview(org.id, wk, null)).totals : null;
  res.json({ type, window: wk, scope: isOfficerScope ? "officer" : "org", tier, sections, teamRollup });
}));

// POST /digests/run — actually reserve + send the caller's org digests now
// (requireAuth + requireAdmin). Drives the same path the tick uses, for ops
// and for the committed test suite. Optional window overrides pin the period
// (so tests can seed a specific week/month); dryRun composes without sending.
app.post("/digests/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const orgRows = await query("SELECT id, name, plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const org = orgRows[0];
  if (!org) return res.status(404).json({ error: "Org not found" });
  const { weekStart, monthStart, type, dryRun } = req.body || {};
  const types = type === "weekly" || type === "monthly" ? [type] : ["weekly", "monthly"];
  // Build windows: explicit override (a Monday / month-start date) or the
  // most-recently-completed period.
  // ORG_TZ_SEAM_OK — an explicit override pins the window to a civil date the
  // caller supplied; otherwise the org's own most-recently-completed period.
  const _tz = await orgTz(org.id);
  const wk = weekStart ? weekBounds(0, _tz, new Date(weekStart + "T12:00:00Z")) : weekBounds(-1, _tz);
  const mo = monthStart ? monthBounds(0, _tz, new Date(monthStart + "T12:00:00Z")) : monthBounds(-1, _tz);
  const result = await runDigestsForOrg(org, { wk, mo, types, send: !dryRun });
  res.json({ windows: { weekly: wk, monthly: mo }, ...result });
}));

// The badge's read of the assessment — minimal, and null unless the donor is
// actually DRIFTING (an excluded/ok/lapsed/not-eligible donor gets no badge
// by construction; the Part 1 exclusion assertions ride on this being the
// only shape any list payload carries).
function driftBadgeField(a) {
  return a && a.state === "drifting"
    ? { state: "drifting", confidence: a.confidence, reason: a.reason }
    : null;
}

// One-page printable/mailable "Impact Summary" for a single donor — cumulative
// giving, milestones reached, and org-configured impact translations. Reuses
// the pdfkit pattern from POST /reports/board (same require, buffer-to-Promise
// approach, page-footer loop) rather than a new rendering system.
app.get("/donors/:id/impact-summary/pdf", requireAuth, wrap(async (req, res) => {
  let PDFDocument;
  try {
    PDFDocument = require("pdfkit");
  } catch (e) {
    return res.status(500).json({ error: "pdfkit module missing: " + e.message });
  }

  const { orgId } = req.user;
  const [donor] = await query("SELECT * FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL", [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });
  // BUILD-64: a donor-facing document (printable/mailable) — carries the org's
  // OWN identity from the shared resolver, never a hardcoded Steward-green band
  // and never the staff-side "(Demo)" name (white-label).
  const brand = await resolveOrgBrandTheme(orgId).catch(() => null);
  const org = { name: brand ? brand.displayName : "" };

  const totalGiving = Number(donor.total_giving) || 0;
  const giftCount = Number(donor.gift_count) || 0;
  const now = new Date();

  const thresholdsReached = MILESTONE_THRESHOLDS.filter(t => totalGiving >= t).sort((a, b) => a - b);

  let yearsGiving = null;
  let firstGiftLabel = null;
  if (donor.first_gift_date) {
    const first = new Date(donor.first_gift_date);
    if (!isNaN(first.getTime())) {
      yearsGiving = now.getFullYear() - first.getFullYear() - ((now.getMonth() < first.getMonth() || (now.getMonth() === first.getMonth() && now.getDate() < first.getDate())) ? 1 : 0);
      firstGiftLabel = first.toLocaleDateString("en-US", { month: "long", year: "numeric" });
    }
  }

  const metricRows = await query(
    "SELECT * FROM impact_metrics WHERE org_id = ? AND active = true AND dollar_threshold <= ? ORDER BY dollar_threshold ASC",
    [orgId, totalGiving]
  );
  const impactLines = metricRows.map(m => {
    const n = Math.max(1, Math.floor(totalGiving / Number(m.dollar_threshold)));
    return String(m.outcome_template || "")
      .replace(/\{amount\}/g, totalGiving.toLocaleString())
      .replace(/\{n\}/g, n);
  });

  const recentGifts = await query(
    "SELECT amount, date, campaign FROM gifts WHERE donor_id = ? AND org_id = ? ORDER BY date DESC LIMIT 5",
    [donor.id, orgId]
  );

  const doc = new PDFDocument({ margin: 50, size: "LETTER", bufferPages: true });
  const pdfBuffer = await new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);

    // BUILD-64: header band + accent = the org's OWN theme (shared resolver);
    // GREEN stays only as the money-figure color (money = green semantics, same
    // as the receipt PDF), never the band.
    const BAND   = brand ? brand.band : "#1a6b4a";
    const BANDFG = brand ? brand.bandFg : "#ffffff";
    const BANDSUB = BANDFG === "#ffffff" ? "#ffffffcc" : "#0f1a12aa";
    const GREEN = "#1a6b4a";
    const INK   = "#1a1a1a";
    const INK3  = "#6b7280";
    const BG    = "#f5f5f0";
    const PW    = doc.page.width;
    const fmtD  = n => "$" + (parseFloat(n) || 0).toLocaleString("en-US", { maximumFractionDigits: 0 });
    const genDate = now.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });

    doc.rect(0, 0, PW, 96).fill(BAND);
    doc.font("Helvetica").fontSize(9).fillColor(BANDSUB).text("I M P A C T   S U M M A R Y", 50, 22);
    doc.font("Helvetica-Bold").fontSize(24).fillColor(BANDFG).text(donor.name || "Valued Donor", 50, 38);
    doc.font("Helvetica").fontSize(10).fillColor(BANDSUB).text(org.name, 50, 70);

    let y = 128;
    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Giving Summary", 50, y); y += 20;
    const boxes = [
      ["Total Given", fmtD(totalGiving)],
      ["Gifts Given", String(giftCount)],
      ["Donor Since", firstGiftLabel || "—"],
      ["Years Giving", yearsGiving != null ? String(Math.max(yearsGiving, 0)) : "—"],
    ];
    const bw = (PW - 100) / boxes.length;
    boxes.forEach(([label, value], i) => {
      const x = 50 + i * bw;
      doc.rect(x, y, bw - 8, 56).fill(BG);
      doc.font("Helvetica").fontSize(7).fillColor(INK3).text(label.toUpperCase(), x + 10, y + 10, { width: bw - 26 });
      doc.font("Helvetica-Bold").fontSize(15).fillColor(GREEN).text(value, x + 10, y + 26, { width: bw - 26 });
    });
    y += 76;

    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Milestones Reached", 50, y); y += 18;
    const milestoneLabels = [
      ...thresholdsReached.map(t => `Crossed $${t.toLocaleString()} in lifetime giving`),
      ...(yearsGiving != null && yearsGiving >= 1 ? [`${yearsGiving} year${yearsGiving === 1 ? "" : "s"} of continuous giving`] : []),
    ];
    if (milestoneLabels.length === 0) {
      doc.font("Helvetica").fontSize(10).fillColor(INK3).text("No milestones reached yet.", 50, y); y = doc.y + 10;
    } else {
      milestoneLabels.forEach(label => {
        doc.font("Helvetica").fontSize(10).fillColor(INK).text("•  " + label, 50, y, { width: PW - 100 });
        y = doc.y + 4;
      });
      y += 8;
    }

    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Your Impact", 50, y); y += 18;
    if (impactLines.length === 0) {
      doc.font("Helvetica").fontSize(10).fillColor(INK3).text("Impact translations will appear here once configured for this organization.", 50, y, { width: PW - 100 }); y = doc.y + 10;
    } else {
      impactLines.forEach(line => {
        doc.font("Helvetica").fontSize(10).fillColor(INK).text("•  " + line, 50, y, { width: PW - 100, lineGap: 2 });
        y = doc.y + 6;
      });
      y += 8;
    }

    if (recentGifts.length > 0) {
      doc.moveTo(50, y).lineTo(PW - 50, y).strokeColor("#e5e7eb").lineWidth(0.5).stroke(); y += 16;
      doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Recent Gifts", 50, y); y += 18;
      recentGifts.forEach((g, i) => {
        const d = g.date ? new Date(g.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "—";
        doc.rect(50, y, PW - 100, 19).fill(i % 2 === 0 ? "#ffffff" : BG);
        doc.font("Helvetica").fontSize(8).fillColor(INK).text(d, 58, y + 5, { width: 90 });
        doc.fillColor(INK3).text(g.campaign || "General", 155, y + 5, { width: 250 });
        doc.font("Helvetica-Bold").fillColor(GREEN).text(fmtD(g.amount), PW - 150, y + 5, { width: 100, align: "right" });
        y += 19;
      });
    }

    const range = doc.bufferedPageRange();
    for (let i = range.start; i < range.start + range.count; i++) {
      doc.switchToPage(i);
      doc.font("Helvetica").fontSize(7).fillColor("#9ca3af")
        .text(`${org.name}  ·  Impact Summary  ·  Generated ${genDate}`, 50, doc.page.height - 28, { width: PW - 130, height: 20, align: "left" })
        .text(`${i - range.start + 1} / ${range.count}`, PW - 80, doc.page.height - 28, { width: 30, height: 20, align: "right" });
    }

    doc.end();
  });

  const safeDonor = (donor.name || "donor").replace(/[^a-z0-9]/gi, "-").replace(/-+/g, "-").toLowerCase();
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="${safeDonor}-impact-summary.pdf"`);
  res.setHeader("Content-Length", pdfBuffer.length);
  res.end(pdfBuffer);
}));

