// Fire-and-forget wrapper for the task routes: load the org + fire the
// assignment email. actorUserId = who triggered the assignment (null = workflow).
async function queueTaskAssignmentEmail(task, actorUserId, eventKey = null) {
  if (!task || !task.assigned_to) return;
  const [org] = await query("SELECT id, name FROM orgs WHERE id=?", [task.org_id]);
  if (!org) return;
  await notifyTaskAssignment(task, { org, actorUserId, eventKey });
}

// GET /impact — the honest "what Steward has done for you" number, for
// retention (the subscription visibly pays for itself) and the sales demo.
// NON-NEGOTIABLE: only ATTRIBUTABLE amounts. We never present total giving as
// "Steward raised" — that would betray the whole honest-design brand. Two real
// figures + one clearly-labeled estimate:
//
//   (1) recoveredAmount — the hero, a HARD number: dollars the failed-card
//       recovery workflow actually won back, computed ONLY from the
//       payment_recovery_events the workflow itself recorded (type=
//       'payment_recovered', summing the tracked per-event amount). These are
//       recurring gifts that were in a failed/dunning state and then charged
//       successfully — money that, at most orgs, would have silently lapsed.
//       100% attributable, never estimated. Reconciles with the recovery log.
//   (2) platformFeesPaid — FACTUAL, 0 by construction: Steward processes
//       donations on the org's OWN Stripe account at a 0% platform fee, so the
//       org kept 100% of every gift. Not an assumption.
//   (3) estimatedFeesElsewhere — OPTIONAL, secondary, ALWAYS carries its
//       assumption inline (feeAssumptionPct): what a typical platform charging
//       ~3% would have skimmed off that same online giving. An estimate about
//       the counterfactual, clearly labeled — never a claim about Steward.
//
// Org-scoped. New org with nothing recovered yet → recoveredAmount 0 +
// watchingRecurringCount, so the client can show a forward-looking line
// ("watching N recurring donors for failed cards") instead of a fake number.
app.get("/impact", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;

  // (1) Recovered recurring giving — tracked recoveries ONLY, never total gifts.
  // Sum the per-event amount recorded by the recovery workflow. Each
  // payment_recovered event is one real gift won back from a failed state; a
  // subscription can appear across multiple failure/recovery cycles over time,
  // and every one of those is genuinely-recovered money, so we sum all of them
  // (not COUNT DISTINCT subscription like the recovery-RATE math).
  const pRec = query(
    `SELECT COUNT(*)::int AS c,
            COALESCE(SUM((detail->>'amount')::numeric), 0) AS amt
       FROM payment_recovery_events
      WHERE org_id=? AND type='payment_recovered' AND (detail->>'amount') IS NOT NULL`,
    [orgId]
  );


  // (1b) BUILD-32 Part 2 — RE-ENGAGED giving: gifts from donors who were LAPSED
  // and gave again. This is a SEPARATE, precisely-labelled number — it is NOT
  // "recovered" (that word is reserved for the failed-card recovery workflow
  // above; overclaiming it would betray the honest-design brand). "Re-engaged"
  // is a gift that followed a >365-day gap since the donor's prior gift — the
  // SAME lapse definition (LAPSE_DAYS) as inferStage / the auto-lapse sweep /
  // the win-back goal, so it's a real, measurable event, not an estimate. We
  // count EVERY such re-engagement gift (not only a donor's current last gift),
  // so a donor who lapsed, came back, then lapsed and came back again is counted
  // for each genuine return. reengagedDonorCount = distinct donors who came back.
  const pReeng = query(
    `SELECT COALESCE(SUM(g.amount),0) AS amt, COUNT(DISTINCT g.donor_id)::int AS donors
       FROM gifts g
      WHERE g.org_id = ?
        AND (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = g.donor_id AND g2.date < g.date) IS NOT NULL
        AND g.date::date - (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = g.donor_id AND g2.date < g.date)::date > 365`,
    [orgId]
  );


  // (1c) The donors BEHIND the re-engaged number — the Home hero chip drills
  // into exactly these rows (every aggregate drills into its source; the
  // destination must show the same count/amount the chip claimed). Same
  // >365-day-gap predicate as (1b), grouped per donor, capped at 50.
  const pReengDonors = query(
    `SELECT g.donor_id AS id, d.name, COALESCE(SUM(g.amount),0) AS amount,
            COUNT(*)::int AS gift_count, MAX(g.date) AS last_return_date
       FROM gifts g JOIN donors d ON d.id = g.donor_id
      WHERE g.org_id = ?
        AND (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = g.donor_id AND g2.date < g.date) IS NOT NULL
        AND g.date::date - (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = g.donor_id AND g2.date < g.date)::date > 365
      GROUP BY g.donor_id, d.name
      ORDER BY amount DESC
      LIMIT 50`,
    [orgId]
  );

  // (2) Fees kept — factual. Base = online giving processed through Steward
  // (own-Stripe donations, stripe_payment_id set), which the org kept 100% of.
  const pGiving = query(
    `SELECT COALESCE(SUM(amount), 0) AS total
       FROM gifts WHERE org_id=? AND stripe_payment_id IS NOT NULL`,
    [orgId]
  );

  // Forward-looking honest empty state: how many recurring donors Steward is
  // actively watching for failed cards (so a new org sees a real promise, not
  // a fabricated $0-dressed-as-something number).
  const pWatch = query(
    `SELECT COUNT(*)::int AS c FROM recurring_subscriptions
      WHERE org_id=? AND status IN ('active', 'recovering', 'past_due')`,
    [orgId]
  );
  // (1d) BUILD-73 Part 3 — MONEY AT RISK. This is the figure the product leads
  // with now, and the reason is a positioning defect, not a data one.
  //
  // The hero used to read "Steward has recovered $X … and re-engaged $Y from N
  // lapsed donors." Nobody parses that as a description of the ORG's history —
  // it reads as money STEWARD brought in, on the first screen a prospect sees,
  // which is invented social proof. The standing rule is that the value math
  // describes the SIZE OF THE PROBLEM and never Steward's results.
  //
  // So the lead figure is the lifetime giving of donors who have gone QUIET —
  // no gift in QUIET_DAYS — which is money genuinely at risk today, is a fact
  // about the organization's own file, and claims nothing about what Steward
  // did.
  //
  // QUIET_DAYS (180), not LAPSE_DAYS (365), and that choice is the product
  // thesis. A donor who has not given in six months is drifting; a donor at
  // twelve months has already gone. Leading with the 365-day set would tell the
  // LAPSED-RECAPTURE story — four hundred small donors who left — which is the
  // story every other tool tells. Leading at 180 days surfaces the mid-level
  // donors who are quietly slipping while every lifetime-total report still
  // shows them as fine. That difference is the entire differentiator, and it is
  // the same threshold computeMoveSuggestions already fires `going_quiet` on.
  // The quiet cutoff is a CIVIL DATE in the ORGANIZATION'S timezone, resolved
  // through the seam (BUILD-72 Part 4). `gifts.date` is a civil date — a gift
  // given on March 15 was given on March 15 in every timezone on earth — so
  // comparing it to CURRENT_DATE would ask Postgres's UTC clock a question only
  // the org's calendar can answer, and the at-risk figure would flip for
  // everyone west of UTC for part of each day. One cutoff, computed once.
  const _quietCutoff = orgTime.addDays(orgToday(await orgTz(orgId)), -QUIET_DAYS);
  const pAtRisk = query(
    `SELECT COALESCE(SUM(d.total_giving), 0) AS amt, COUNT(*)::int AS donors
       FROM donors d
      WHERE d.org_id = ?
        AND d.deleted_at IS NULL
        AND d.total_giving > 0
        AND (SELECT MAX(g.date) FROM gifts g WHERE g.donor_id = d.id) IS NOT NULL
        AND (SELECT MAX(g.date) FROM gifts g WHERE g.donor_id = d.id) < ?`,
    [orgId, _quietCutoff]
  );
  // The donors BEHIND the at-risk number — every aggregate drills into its
  // source, and the destination shows the same count and amount the chip claimed.
  const pAtRiskDonors = query(
    `SELECT d.id, d.name, COALESCE(d.total_giving, 0) AS amount,
            (SELECT MAX(g.date) FROM gifts g WHERE g.donor_id = d.id) AS last_gift_date
       FROM donors d
      WHERE d.org_id = ?
        AND d.deleted_at IS NULL
        AND d.total_giving > 0
        AND (SELECT MAX(g.date) FROM gifts g WHERE g.donor_id = d.id) IS NOT NULL
        AND (SELECT MAX(g.date) FROM gifts g WHERE g.donor_id = d.id) < ?
      ORDER BY d.total_giving DESC
      LIMIT 50`,
    [orgId, _quietCutoff]
  );
  const pOrg = query("SELECT plan FROM orgs WHERE id=?", [orgId]);

  // BUILD-54 §1 — the six reads above are independent; one parallel batch.
  const [recRows, reengRows, reengagedDonors, givingRows, watchRows, atRiskRows, atRiskDonors, orgRows] =
    await Promise.all([pRec, pReeng, pReengDonors, pGiving, pWatch, pAtRisk, pAtRiskDonors, pOrg]);
  const recoveredCount = recRows[0]?.c || 0;
  const recoveredAmount = parseFloat(recRows[0]?.amt) || 0;
  const reengagedAmount = parseFloat(reengRows[0]?.amt) || 0;
  const reengagedDonorCount = reengRows[0]?.donors || 0;
  const onlineGivingProcessed = parseFloat(givingRows[0]?.total) || 0;
  // (3) Optional labeled estimate — assumption shown inline, secondary.
  const FEE_ASSUMPTION_PCT = 3;
  const estimatedFeesElsewhere =
    Math.round(onlineGivingProcessed * (FEE_ASSUMPTION_PCT / 100) * 100) / 100;
  const watchingRecurringCount = watchRows[0]?.c || 0;
  const plan = orgRows[0]?.plan || "trial";
  const planMonthlyCost = PLAN_MONTHLY_COST[plan] ?? null;

  // ── BUILD-83 Part 3.3 — THE "QUIET DONORS" COHORT IS DELETED. ────────────
  // It was Σ LIFETIME giving of every donor with no gift in six months, which
  // on a real file is most of the file: "$38,748,624.17 at risk across 19,855
  // quiet donors" is 79% of a 25,000-donor import, and it is the number that
  // makes an ED close the laptop. At risk is the NEXT gift, not the lifetime,
  // and the donors at risk are the ones past their OWN pattern — which is
  // exactly what Drift already computes, donor by donor, with a sentence.
  // Home reads Drift; nothing reads this any more. `atRiskDonors` stays (it is
  // the re-engagement LIST, not a headline dollar figure) but is renamed on the
  // response to say what it is.
  void atRiskRows;

  res.json({
    quietSinceDays: QUIET_DAYS,
    reengageCandidates: atRiskDonors.map(r => ({
      id: r.id, name: r.name, amount: parseFloat(r.amount) || 0, lastGiftDate: r.last_gift_date,
    })),
    recoveredAmount,               // internal: the failed-card retry workflow's tracked total
    recoveredCount,
    reengagedAmount,               // SURFACED, separate — lapsed donors who came back
    reengagedDonorCount,
    reengagedDonors: reengagedDonors.map(r => ({
      id: r.id, name: r.name, amount: parseFloat(r.amount) || 0,
      giftCount: r.gift_count, lastReturnDate: r.last_return_date,
    })),
    platformFeesPaid: 0,           // factual — 0% platform fee, own Stripe
    onlineGivingProcessed,         // base for the fee estimate
    estimatedFeesElsewhere,        // ESTIMATE — see feeAssumptionPct
    feeAssumptionPct: FEE_ASSUMPTION_PCT,
    watchingRecurringCount,        // forward-looking empty state
    plan,
    planMonthlyCost,
  });
}));

// Per-donor health record for the DonorProfile status chip (Active/Payment
// failed/Recovering/Recovered/Canceled) — null if this donor never had a
// recurring gift that's failed a payment (donors.stripe_subscription_status
// alone can't distinguish "recovering" from "past_due").
app.get("/donors/:id/recurring-subscription", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" }); // BUILD-75 B: the parent must be YOURS before children are answered — even an empty list confirms nothing about another tenant
  const rows = await query(
    `SELECT stripe_subscription_id, amount, interval, status, failure_count, first_failed_at, last_failed_at, recovered_at, canceled_at
     FROM recurring_subscriptions WHERE donor_id=? AND org_id=? ORDER BY created_at DESC LIMIT 1`,
    [req.params.id, req.user.orgId]
  );
  res.json(rows[0] || null);
}));

app.post("/pledges/process-reminders", requireAuth, requireAdmin, wrap(async (req, res) => {
  await processPledgeReminders();
  res.json({ success: true });
}));

// Everyday staff action, matching POST /recurring/:donorId/resend — resends
// the current step's reminder on demand without touching reminder_step/
// next_reminder_at, so a manual nudge never interferes with the automatic
// cadence.
app.post("/pledges/:id/resend", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT p.*, d.name AS donor_name, d.email AS donor_email
     FROM pledges p JOIN donors d ON d.id = p.donor_id
     WHERE p.id=? AND p.org_id=? AND p.status='open'`,
    [req.params.id, req.user.orgId]
  );
  if (!rows.length) return res.status(404).json({ error: "This pledge is not open." });
  const p = rows[0];
  if (!p.donor_email) return res.status(400).json({ error: "This donor has no email on file." });

  const decision = await donorMailDecision("pledge_reminder", p.donor_email, req.user.orgId);
  if (!decision.send) return res.status(400).json({ error: `Cannot send — ${decision.reason === "deceased" ? "this donor is marked deceased" : decision.reason === "do_not_contact" ? "this donor is marked do-not-contact" : `this donor's email is suppressed (${decision.reason})`}.` });

  const orgRows = await query(
    "SELECT id, name, org_slug, pledge_reminder_subject, pledge_reminder_body FROM orgs WHERE id=?", [req.user.orgId]
  );
  await sendPledgeReminderEmail(orgRows[0], { name: p.donor_name, email: p.donor_email }, p);
  res.json({ sent: true });
}));

// Published monthly price per plan (USD) — mirrors pages/Pricing.jsx's
// CHECKOUT_PLANS/BILLING_PLANS. Used ONLY to render the ROI comparison
// ("your plan is $249/mo") next to Steward's recovered-dollars figure; not a
// billing source of truth. trial → null (nothing charged yet).
const PLAN_MONTHLY_COST = {
  core: 249, team: 499, founding: 199, seed: 99, growth: 249, impact: 499,
};

// POST /gmail/auth-url — returns OAuth URL for frontend to redirect to
app.post("/gmail/auth-url", requireAuth, wrap(async (req, res) => {
  if (!process.env.GOOGLE_CLIENT_ID) return res.status(503).json({ error: "Gmail not configured" });
  const oauth2Client = makeOAuth2Client();
  const url = oauth2Client.generateAuthUrl({
    access_type: "offline",
    scope: [
      "https://www.googleapis.com/auth/gmail.readonly",
      "https://www.googleapis.com/auth/gmail.send",
    ],
    state: req.user.userId,
    prompt: "consent",
  });
  res.json({ url });
}));

// GET /gmail/callback — OAuth callback from Google (public)
app.get("/gmail/callback", wrap(async (req, res) => {
  const { code, state: userId, error } = req.query;
  const frontendUrl = publicAppUrl();
  if (error || !code) return res.redirect(`${frontendUrl}/dashboard?gmailError=access_denied`);

  try {
    const oauth2Client = makeOAuth2Client();
    const { tokens } = await oauth2Client.getToken(code);
    oauth2Client.setCredentials(tokens);

    const gmail   = google.gmail({ version: "v1", auth: oauth2Client });
    const profile = await gmail.users.getProfile({ userId: "me" });
    const email   = profile.data.emailAddress;

    // Look up the user to get their org
    const users = await query("SELECT id, org_id FROM users WHERE id=?", [userId]);
    if (!users.length) return res.redirect(`${frontendUrl}/dashboard?gmailError=user_not_found`);
    const orgId = users[0].org_id;

    await run(
      `INSERT INTO gmail_connections (id, org_id, user_id, email, access_token, refresh_token, token_expiry, status)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'active')
       ON CONFLICT (user_id) DO UPDATE SET
         email=EXCLUDED.email, access_token=EXCLUDED.access_token,
         refresh_token=EXCLUDED.refresh_token, token_expiry=EXCLUDED.token_expiry,
         status='active'`,
      [
        `gc_${uuid().slice(0, 8)}`,
        orgId,
        userId,
        email,
        tokens.access_token,
        tokens.refresh_token || "",
        tokens.expiry_date ? new Date(tokens.expiry_date).toISOString() : null,
      ]
    );

    // Kick off an initial sync in the background
    syncGmail(userId, orgId).catch(e => console.error("[gmail-connect-sync]", e.message));

    res.redirect(`${frontendUrl}/dashboard?gmailConnected=true`);
  } catch (e) {
    console.error("[gmail-callback]", e.message);
    res.redirect(`${frontendUrl}/dashboard?gmailError=callback_failed`);
  }
}));

// GET /gmail/status — returns connection info for current user
app.get("/gmail/status", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    "SELECT email, status, last_synced_at FROM gmail_connections WHERE user_id=?",
    [req.user.userId]
  );
  if (!rows.length) return res.json({ connected: false });
  const c = rows[0];
  res.json({
    connected: c.status === "active",
    disconnected: c.status === "disconnected",
    email: c.email,
    lastSyncedAt: c.last_synced_at,
  });
}));

// DELETE /gmail/disconnect — revokes token and removes connection
app.delete("/gmail/disconnect", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT * FROM gmail_connections WHERE user_id=?", [req.user.userId]);
  if (!rows.length) return res.json({ ok: true });
  const conn = rows[0];
  try {
    const oauth2Client = makeOAuth2Client();
    await oauth2Client.revokeToken(conn.access_token);
  } catch { /* ignore revocation errors */ }
  await run("DELETE FROM gmail_connections WHERE user_id=?", [req.user.userId]);
  res.json({ ok: true });
}));

// POST /gmail/sync — manually trigger sync for current user
app.post("/gmail/sync", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT status FROM gmail_connections WHERE user_id=?", [req.user.userId]);
  if (!rows.length) return res.status(404).json({ error: "No Gmail connection found" });
  if (rows[0].status !== "active") return res.status(400).json({ error: "Gmail connection is not active" });
  // Run sync async — respond immediately
  syncGmail(req.user.userId, req.user.orgId).catch(e => console.error("[gmail-manual-sync]", e.message));
  res.json({ ok: true, message: "Sync started" });
}));

// POST /gmail/send — send email via user's connected Gmail and log to interactions
app.post("/gmail/send", requireAuth, wrap(async (req, res) => {
  const { donorId, to, subject, body } = req.body;
  if (donorId) {
    const donorCheck = await query("SELECT id FROM donors WHERE id=? AND org_id=?", [donorId, req.user.orgId]);
    if (!donorCheck.length) return res.status(404).json({ error: "Donor not found" });
  }
  const conns = await query("SELECT * FROM gmail_connections WHERE user_id=? AND status='active'", [req.user.userId]);
  if (!conns.length) return res.status(400).json({ error: "Gmail not connected" });
  const conn = conns[0];

  const oauth2Client = makeOAuth2Client();
  oauth2Client.setCredentials({
    access_token: conn.access_token,
    refresh_token: conn.refresh_token,
    expiry_date: conn.token_expiry ? new Date(conn.token_expiry).getTime() : undefined,
  });
  oauth2Client.on("tokens", async (tokens) => {
    const sets = [], vals = [];
    if (tokens.access_token) { sets.push("access_token=?"); vals.push(tokens.access_token); }
    if (tokens.expiry_date) { sets.push("token_expiry=?"); vals.push(new Date(tokens.expiry_date).toISOString()); }
    if (sets.length) { vals.push(conn.id); await run(`UPDATE gmail_connections SET ${sets.join(",")} WHERE id=?`, vals); }
  });

  const emailLines = [`To: ${to}`, `Subject: ${subject}`, `Content-Type: text/plain; charset=utf-8`, ``, body];
  const raw = Buffer.from(emailLines.join("\r\n")).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  const gmail = google.gmail({ version: "v1", auth: oauth2Client });

  let sendResp;
  try {
    sendResp = await gmail.users.messages.send({ userId: "me", requestBody: { raw } });
  } catch (e) {
    if (e.code === 401) {
      try {
        await oauth2Client.refreshAccessToken();
        sendResp = await gmail.users.messages.send({ userId: "me", requestBody: { raw } });
      } catch {
        await run("UPDATE gmail_connections SET status='disconnected' WHERE id=?", [conn.id]);
        return res.status(401).json({ error: "Failed to send — reconnect Gmail in Settings" });
      }
    } else throw e;
  }

  const msgId = sendResp.data.id;
  if (donorId) {
    const id = Math.random().toString(36).slice(2);
    const note = `Subject: ${subject}\n\n${body.slice(0, 500)}`;
    const metadata = JSON.stringify({ gmail_message_id: msgId, from: conn.email, to, subject, direction: "outbound" });
    await run(
      `INSERT INTO interactions (id, org_id, donor_id, type, note, date, metadata, created_at) VALUES (?, ?, ?, 'email', ?, ?, ?, NOW())`,
      [id, req.user.orgId, donorId, note, new Date().toISOString().split("T")[0], metadata]
    );
  }
  res.json({ success: true, messageId: msgId });
}));

// GET /gmail/thread/:donorId — last 20 email interactions for AI context
app.get("/gmail/thread/:donorId", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.donorId, req.user.orgId))) return res.status(404).json({ error: "Donor not found" }); // BUILD-75 B
  const rows = await query(
    `SELECT id, type, note, date, created_at, metadata FROM interactions WHERE org_id=? AND donor_id=? AND type='email' ORDER BY created_at DESC LIMIT 20`,
    [req.user.orgId, req.params.donorId]
  );
  res.json(rows.map(r => {
    const meta = r.metadata ? (typeof r.metadata === "string" ? JSON.parse(r.metadata) : r.metadata) : {};
    const m = (r.note || "").match(/^Subject: (.+?)(?:\n\n([\s\S]*))?$/);
    return {
      id: r.id,
      date: r.date,
      created_at: r.created_at,
      subject: m ? m[1] : "",
      snippet: m ? (m[2] || "").slice(0, 200) : (r.note || "").slice(0, 200),
      direction: meta.direction || "inbound",
      note: r.note || "",
    };
  }));
}));

function eventLevelPayload(l, taken = 0) {
  return { id: l.id, kind: l.kind, name: l.name, price: Number(l.price), fmv: Number(l.fmv),
    deductible: (rbCentsEv(l.price) - rbCentsEv(l.fmv)) / 100, capacity: l.capacity, taken,
    remaining: l.capacity == null ? null : Math.max(0, l.capacity - taken), recognition: l.recognition };
}

// Find the person by id, or by email, or create them — the same shape a
// staff member registering a walk-up guest needs.
async function eventDonorFor(orgId, body, who) {
  if (body?.donorId) {
    const [d] = await query("SELECT id FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [String(body.donorId), orgId]);
    return d ? d.id : null;
  }
  const name = String(body?.name || "").trim().slice(0, 200);
  const email = String(body?.email || "").trim().toLowerCase().slice(0, 200);
  if (!name && !email) return null;
  if (email) {
    const found = await query("SELECT id FROM donors WHERE org_id=? AND deleted_at IS NULL AND LOWER(email)=? LIMIT 2", [orgId, email]);
    if (found.length === 1) return found[0].id;
  }
  const id = "d_" + uuid().slice(0, 10);
  await run(`INSERT INTO donors (id,org_id,name,email,stage,status,tags,created_by,created_by_name) VALUES (?,?,?,?,'prospect','active','[]',?,?)`,
    [id, orgId, name || email, email || null, who.id, who.name]);
  return id;
}
function membershipLevelPayload(l, counts = null) {
  const priceCents = mbCents(l.price), fmvCents = mbCents(l.fmv);
  return { id: l.id, name: l.name, price: priceCents / 100, fmv: fmvCents / 100, deductible: (priceCents - fmvCents) / 100,
    term: l.term, termLabel: MB ? MB.TERM_LABEL[l.term] : l.term, scope: l.scope,
    benefits: Array.isArray(l.benefits) ? l.benefits : [], active: l.active !== false,
    fmvSentence: MB ? MB.fmvSentence({ priceCents, fmvCents }) : null, counts };
}

app.get("/membership-levels", requireAuth, wrap(async (req, res) => {
  await MB_READY;
  const levels = await query(`SELECT * FROM membership_levels WHERE org_id=? ORDER BY active DESC, position, price`, [req.user.orgId]);
  const counts = await query(`SELECT level_id, status, COUNT(*)::int n FROM memberships WHERE org_id=? GROUP BY 1,2`, [req.user.orgId]);
  const by = {};
  for (const c of counts) (by[c.level_id] ||= { active: 0, grace: 0, lapsed: 0, cancelled: 0 })[c.status] = c.n;
  res.json({ levels: levels.map(l => membershipLevelPayload(l, by[l.id] || { active: 0, grace: 0, lapsed: 0, cancelled: 0 })) });
}));

// Prices and the value of benefits are the org's policy: admins set them.
app.post("/membership-levels", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  await MB_READY;
  const v = MB.validateLevel(req.body || {});
  if (!v.ok) return res.status(400).json({ error: v.errors.join("; ") });
  const L = v.level, id = "mbl_" + uuid().slice(0, 8), who = actor(req);
  await run(`INSERT INTO membership_levels (id,org_id,name,price,fmv,term,scope,benefits,created_by,created_by_name)
             VALUES (?,?,?,?,?,?,?,?::jsonb,?,?)`,
    [id, req.user.orgId, L.name, L.priceCents / 100, L.fmvCents / 100, L.term, L.scope, JSON.stringify(L.benefits), who.id, who.name]);
  res.status(201).json({ id, sentence: MB.fmvSentence(L) });
}));

app.put("/membership-levels/:id", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  await MB_READY;
  const [l] = await query(`SELECT * FROM membership_levels WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!l) return res.status(404).json({ error: "Not found" });
  const cur = membershipLevelPayload(l);
  const v = MB.validateLevel({ ...cur, ...req.body });
  if (!v.ok) return res.status(400).json({ error: v.errors.join("; ") });
  const L = v.level;
  const active = typeof req.body?.active === "boolean" ? req.body.active : l.active !== false;
  await run(`UPDATE membership_levels SET name=?, price=?, fmv=?, term=?, scope=?, benefits=?::jsonb, active=? WHERE id=? AND org_id=?`,
    [L.name, L.priceCents / 100, L.fmvCents / 100, L.term, L.scope, JSON.stringify(L.benefits), active, l.id, req.user.orgId]);
  res.json({ ok: true, sentence: MB.fmvSentence(L) });
}));

// A level somebody has held cannot vanish from under their receipt; retire it
// (active=false) instead.
app.delete("/membership-levels/:id", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [used] = await query(`SELECT COUNT(*)::int n FROM memberships WHERE level_id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (used?.n) return res.status(409).json({ error: "level_in_use", message: "People have held this level. It can be retired, not removed." });
  const { changes } = await run(`DELETE FROM membership_levels WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

app.post("/donors/:id/memberships", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [level] = await query(`SELECT * FROM membership_levels WHERE id=? AND org_id=?`, [String(req.body?.levelId || ""), orgId]);
  if (!level) return res.status(404).json({ error: "Level not found" });
  if (level.active === false) return res.status(400).json({ error: `${level.name} is retired. Choose a current level.` });
  const startsOn = req.body?.startsOn && /^\d{4}-\d{2}-\d{2}$/.test(req.body.startsOn) ? req.body.startsOn : null;
  const idem = typeof req.body?.idempotencyKey === "string" && req.body.idempotencyKey.trim() ? req.body.idempotencyKey.trim().slice(0, 128) : null;
  try {
    const r = await enrollMembership({ orgId, donorId: req.params.id, level, startsOn, paid: req.body?.paid !== false,
      paymentMethod: req.body?.paymentMethod || null, idemKey: idem, who: actor(req) });
    res.status(r.duplicate ? 200 : 201).json(r);
  } catch (e) {
    if (e.status) return res.status(e.status).json({ error: e.code || e.message, message: e.message });
    throw e;
  }
}));

app.get("/donors/:id/memberships", requireAuth, wrap(async (req, res) => {
  const [d] = await query(`SELECT id FROM donors WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!d) return res.status(404).json({ error: "Not found" });
  const rows = await query(
    `SELECT m.id, m.status, m.joined_on, m.starts_on, m.expires_on, m.gift_id, m.payment_method, m.source,
            l.id AS level_id, l.name AS level_name, l.term, l.scope
       FROM memberships m JOIN membership_levels l ON l.id=m.level_id
      WHERE m.donor_id=? AND m.org_id=? ORDER BY m.starts_on DESC, m.created_at DESC`, [d.id, req.user.orgId]);
  res.json({ memberships: rows, current: rows.find(r => r.status === "active" || r.status === "grace") || null,
    sentence: "Memberships are counted apart from giving: the payment is a gift, and the part that bought benefits is not deductible." });
}));

// The Members screen: every membership, counts by level and status, sortable
// by expiry (soonest first by default — that is the list someone works from).
// ── BUILD-101 Part 3 — LAPSED MEMBERS ARE THEIR OWN LIST ──────────────────
// A lapsed member and a lapsed donor are different people with different
// asks. This list reads ONLY the memberships table (and, to say whether they
// still give, the gifts that were not membership payments). Nothing here is
// read by Drift, LYBUNT or SYBUNT, and nothing those compute is read here —
// the suite proves both directions byte for byte. A person who lapsed as a
// member and still gives is shown as both.
const LAPSED_MEMBER_SQL = `m.id = (SELECT m2.id FROM memberships m2 WHERE m2.org_id=m.org_id AND m2.donor_id=m.donor_id
                                     ORDER BY m2.starts_on DESC, m2.created_at DESC LIMIT 1)
    AND NOT EXISTS (SELECT 1 FROM memberships c WHERE c.org_id=m.org_id AND c.donor_id=m.donor_id AND c.status IN ('active','grace'))`;

// BUILD-101 Part 5 — THE MEMBER CARD. One page: the org's letterhead, the
// member's name, the level and the date it runs through. The pdfkit pattern
// the acknowledgment letters use; held to one page by construction.
function renderMemberCardPdf({ orgName, accent, logo, memberName, levelName, expiresOn, memberSince }) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margin: 0, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = []; doc.on("data", c => chunks.push(c)); doc.on("end", () => resolve(Buffer.concat(chunks))); doc.on("error", reject);
    doc.addPage();
    const INK = "#0f1a12", SUB = "#5a554f";
    // A wallet-card-sized panel (3.375 x 2.125 in) near the top, to cut out.
    const X = 72, Y = 72, W = 243, H = 153;
    doc.roundedRect(X, Y, W, H, 10).lineWidth(1).strokeColor("#e8e4db").stroke();
    doc.rect(X, Y, W, 8).fill(accent || "#0d5c3a");
    if (logo) { try { doc.image(logo, X + W - 58, Y + 16, { fit: [44, 32] }); } catch { /* a logo that will not draw costs the logo, not the card */ } }
    doc.font("Helvetica-Bold").fontSize(10).fillColor(INK).text(orgName, X + 14, Y + 20, { width: W - 80, height: 26, ellipsis: true });
    doc.font("Helvetica").fontSize(8).fillColor(SUB).text("MEMBER", X + 14, Y + 58, { characterSpacing: 1.5 });
    doc.font("Helvetica-Bold").fontSize(15).fillColor(INK).text(memberName, X + 14, Y + 70, { width: W - 28, height: 20, ellipsis: true });
    doc.font("Helvetica").fontSize(10).fillColor(INK).text(`${levelName} membership`, X + 14, Y + 96, { width: W - 28, height: 14, ellipsis: true });
    doc.font("Helvetica").fontSize(9).fillColor(SUB)
      .text(expiresOn ? `Valid through ${expiresOn}` : "Lifetime member", X + 14, Y + 118, { width: W - 28, height: 12 })
      .text(`Member since ${memberSince}`, X + 14, Y + 131, { width: W - 28, height: 12 });
    doc.end();
  });
}

app.get("/memberships/:id/card.pdf", requireAuth, wrap(async (req, res) => {
  const [m] = await query(
    `SELECT m.*, l.name AS level_name, d.name AS donor_name FROM memberships m
       JOIN membership_levels l ON l.id=m.level_id AND l.org_id=m.org_id
       JOIN donors d ON d.id=m.donor_id AND d.org_id=m.org_id
      WHERE m.id=? AND m.org_id=?`, [req.params.id, req.user.orgId]);
  if (!m) return res.status(404).json({ error: "Not found" });
  const theme = await resolveOrgBrandTheme(req.user.orgId).catch(() => null);
  let logo = null;
  if (theme?.logoDataUri && /^data:image\/(png|jpe?g);base64,/.test(theme.logoDataUri)) { try { logo = Buffer.from(theme.logoDataUri.split(",")[1], "base64"); } catch { logo = null; } }
  const pdf = await renderMemberCardPdf({ orgName: theme?.displayName || "", accent: theme?.band, logo,
    memberName: m.donor_name, levelName: m.level_name, expiresOn: m.expires_on, memberSince: m.joined_on });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `inline; filename="member-card-${m.id}.pdf"`);
  res.send(pdf);
}));

app.get("/memberships/lapsed", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const rows = await query(
    `SELECT m.id, m.donor_id, d.name AS donor_name, l.name AS level_name, m.expires_on,
            COALESCE(m.status_changed_on, m.expires_on) AS lapsed_on,
            (SELECT COUNT(*)::int FROM memberships t WHERE t.org_id=m.org_id AND t.donor_id=m.donor_id
               AND t.status IN ('active','grace','lapsed','renewed')) AS membership_years,
            (SELECT MAX(g.date) FROM gifts g WHERE g.org_id=m.org_id AND g.donor_id=m.donor_id
               AND NOT EXISTS (SELECT 1 FROM memberships x WHERE x.org_id=g.org_id AND x.gift_id=g.id)) AS last_gift_date
       FROM memberships m
       JOIN membership_levels l ON l.id=m.level_id AND l.org_id=m.org_id
       JOIN donors d ON d.id=m.donor_id AND d.org_id=m.org_id AND d.deleted_at IS NULL
      WHERE m.org_id=? AND m.status='lapsed' AND ${LAPSED_MEMBER_SQL}
      ORDER BY lapsed_on DESC, d.name LIMIT 1000`, [orgId]);
  res.json({
    members: rows.map(r => ({ ...r, lastGiftDate: r.last_gift_date ? String(r.last_gift_date).slice(0, 10) : null })),
    sentence: "People whose most recent membership has lapsed and who hold none now. Membership years counts the terms they held. A gift here means a gift that was not a membership payment, so someone can be a lapsed member and a current donor at once.",
  });
}));

app.get("/memberships", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const where = ["m.org_id=?"], args = [orgId];
  if (req.query.status && ["active", "grace", "lapsed", "cancelled"].includes(String(req.query.status))) { where.push("m.status=?"); args.push(String(req.query.status)); }
  // "Lapsed" means a PERSON who lapsed, once: their latest membership lapsed
  // and they hold none now (BUILD-101 Part 3 — the same predicate as the
  // Lapsed list, so the count and the list cannot disagree).
  if (req.query.status === "lapsed") where.push(LAPSED_MEMBER_SQL);
  if (req.query.levelId) { where.push("m.level_id=?"); args.push(String(req.query.levelId)); }
  const dir = req.query.sort === "expiry_desc" ? "DESC" : "ASC";
  const rows = await query(
    `SELECT m.id, m.donor_id, d.name AS donor_name, m.status, m.joined_on, m.starts_on, m.expires_on, m.gift_id,
            l.id AS level_id, l.name AS level_name, l.term
       FROM memberships m JOIN membership_levels l ON l.id=m.level_id JOIN donors d ON d.id=m.donor_id
      WHERE ${where.join(" AND ")} ORDER BY m.expires_on ${dir} NULLS LAST, d.name LIMIT 1000`, args);
  const counts = await query(`SELECT m.status, COUNT(*)::int n FROM memberships m WHERE m.org_id=? AND m.status <> 'lapsed' GROUP BY 1`, [orgId]);
  const byStatus = { active: 0, grace: 0, lapsed: 0, cancelled: 0 };
  for (const c of counts) if (c.status in byStatus) byStatus[c.status] = c.n;
  const [lp] = await query(`SELECT COUNT(*)::int n FROM memberships m WHERE m.org_id=? AND m.status='lapsed' AND ${LAPSED_MEMBER_SQL}`, [orgId]);
  byStatus.lapsed = lp?.n || 0;
  res.json({ members: rows, byStatus,
    sentence: "Each person counts once per membership. Active and in-grace members hold a current membership; lapsed ones have passed their grace period." });
}));

// Cancelling stops a membership; it does not refund the gift (a refund is its
// own act on the gift). Never write-gated: a lapsed org can always stop one.
app.post("/memberships/:id/cancel", requireAuth, wrap(async (req, res) => {
  const r = await query(`UPDATE memberships SET status='cancelled', cancelled_at=NOW(), updated_at=NOW()
                          WHERE id=? AND org_id=? AND status IN ('active','grace') RETURNING id`, [req.params.id, req.user.orgId]);
  if (!r.length) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

// ── BUILD-101 Part 6 — MEMBERSHIPS FROM A FILE ────────────────────────────
// Rows arrive already read by shared/membershipImport.js. Each is placed on a
// person — by EMAIL, exactly, or by NAME when the row has no email (the oldest
// matching record, the proposals/soft-credit rule) — and on one of the org's
// OWN levels, matched case-insensitively. Everything that cannot be placed is
// HELD with its line number and the reason; nothing is created to make a row
// fit. An imported membership is history: it carries no payment (no gift, no
// ledger row), its status comes from its dates, and a re-run adds nothing.
async function importMemberships(orgId, rows, who) {
  await MB_READY;
  const MI = await import("../shared/membershipImport.js");
  const out = { written: 0, skippedDuplicate: 0, held: [] };
  const levels = await query("SELECT * FROM membership_levels WHERE org_id=?", [orgId]);
  const today = orgToday(await orgTz(orgId));                  // ORG_TZ_SEAM_OK
  const { graceDays } = await membershipSettings(orgId);
  const hold = (r, why) => out.held.push({ line: Number.isInteger(r.line) ? r.line : null, name: r.name || r.email || null, level: r.level || null, why });
  for (const r of rows.slice(0, 50000)) {
    const level = MI.matchLevel(levels, r.level);
    if (!level) { hold(r, `no level called "${String(r.level || "").slice(0, 60)}" — add it in Members, or fix the file`); continue; }
    const iso = v => (typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);
    const starts = iso(r.starts) || iso(r.joined);
    if (!starts) { hold(r, "no start date that could be read"); continue; }
    let donor = null;
    if (r.email) [donor] = await query("SELECT id FROM donors WHERE org_id=? AND LOWER(email)=LOWER(?) AND deleted_at IS NULL ORDER BY created_at LIMIT 1", [orgId, r.email]);
    if (!donor && r.name) [donor] = await query("SELECT id FROM donors WHERE org_id=? AND LOWER(name)=LOWER(?) AND deleted_at IS NULL ORDER BY created_at LIMIT 1", [orgId, String(r.name).trim()]);
    if (!donor) { hold(r, "no one on file with that email or name"); continue; }
    const expires = iso(r.expires) || MB.expiryFor({ term: level.term, startsOn: starts });
    const [dup] = await query("SELECT id FROM memberships WHERE org_id=? AND donor_id=? AND level_id=? AND starts_on=?", [orgId, donor.id, level.id, starts]);
    if (dup) { out.skippedDuplicate++; continue; }
    const status = MB.statusOn({ expiresOn: expires, today, graceDays });
    try {
      await run(`INSERT INTO memberships (id,org_id,donor_id,level_id,joined_on,starts_on,expires_on,status,status_changed_on,source,created_by,created_by_name)
                 VALUES (?,?,?,?,?,?,?,?,?,'import',?,?)`,
        ["mb_" + uuid().slice(0, 10), orgId, donor.id, level.id, iso(r.joined) || starts, starts, expires, status,
         status === "lapsed" ? MB.addDaysCivil(expires, graceDays + 1) : null, who.id, who.name]);
      out.written++;
    } catch (e) {
      if (e.code !== "23505") throw e;
      hold(r, "this person already holds a current membership");
    }
  }
  return out;
}

